window.FRAGEN = [{"id":"b01f1","block":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche der folgenden Speicherarten ist nicht-flüchtig und behält Daten auch nach dem Ausschalten des Computers?","optionen":[{"key":"A","text":"RAM"},{"key":"B","text":"SSD"},{"key":"C","text":"Cache"},{"key":"D","text":"Register"}],"loesung_key":"B","loesung":"SSD","kapitel":1,"kapitel_name":"Allgemeines zu IT","quelle":"buch"},{"id":"b01f2","block":"Allgemeines zu IT","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Der Master Boot Record (MBR) befindet sich am Anfang der Festplatte und enthält Informationen über die Partitionierung","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","kapitel":1,"kapitel_name":"Allgemeines zu IT","quelle":"buch","bild":"b01f2.png"},{"id":"b01f3","block":"Allgemeines zu IT","typ":"lueckentext","typ_label":"Lückentext","frage":"Der __________ ist ein Speicher, mit einem einmaligen Schreibvorgang, der Daten vor Manipulation schützt und ideal für Archivierungszwecke ist","loesung":"WORM-Speicher","kapitel":1,"kapitel_name":"Allgemeines zu IT","quelle":"buch","alternativen":["WORM","Write Once Read Many"],"bild":"b01f3.png"},{"id":"b01f4","block":"Allgemeines zu IT","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was passiert beim Einschalten eines Rechners?","loesung":"Nach dem Einschalten startet zunächst das BIOS beziehungsweise UEFI und führt den POST (Power-On Self-Test) durch, bei dem die grundlegende Hardware wie Prozessor, Arbeitsspeicher und Grafikausgabe geprüft wird. Anschließend ermittelt das BIOS/UEFI anhand der Bootreihenfolge das Startlaufwerk und lädt von dort den Bootloader aus dem MBR beziehungsweise der EFI-Systempartition. Der Bootloader lädt den Kernel des Betriebssystems in den Arbeitsspeicher. Danach initialisiert das Betriebssystem die Treiber und Dienste und übergibt schließlich an die Benutzeroberfläche","kapitel":1,"kapitel_name":"Allgemeines zu IT","quelle":"buch"},{"id":"b01f5","block":"Allgemeines zu IT","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Speicherarten den passenden Beschreibungen zu:","begriffe":["Optischer Speicher","Magnetischer Speicher","Elektronischer Speicher"],"beschreibungen":[{"key":"a","text":"Verwendet Laser zur Speicherung von Daten"},{"key":"b","text":"Nutzt magnetisierbare Schichten auf rotierenden Scheiben"},{"key":"c","text":"Speichert Daten auf Flash-Speicherchips"}],"loesung_paare":{"Optischer Speicher":"a","Magnetischer Speicher":"b","Elektronischer Speicher":"c"},"loesung":"Optischer Speicher = a; Magnetischer Speicher = b; Elektronischer Speicher = c","kapitel":1,"kapitel_name":"Allgemeines zu IT","quelle":"buch"},{"id":"b02f1","block":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Unterschied zwischen einer Klasse und einem Objekt in der objektorientierten Programmierung?","loesung":"Eine Klasse ist der Bauplan beziehungsweise die Vorlage. Sie beschreibt, welche Eigenschaften (Attribute) und welches Verhalten (Methoden) ein bestimmter Typ besitzt, belegt selbst aber keinen Speicher für konkrete Werte. Ein Objekt ist eine konkrete Instanz dieser Klasse. Es wird zur Laufzeit erzeugt, besitzt eigene Werte in seinen Attributen und liegt im Arbeitsspeicher. Aus einer Klasse können beliebig viele Objekte erzeugt werden, die unabhängig voneinander existieren","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","quelle":"buch"},{"id":"b02f2","block":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Art der Schleife überprüft die Abbruchbedingung am Ende jeder Iteration?","optionen":[{"key":"A","text":"For-Schleife"},{"key":"B","text":"While-Schleife"},{"key":"C","text":"Do-While-Schleife"},{"key":"D","text":"If-Schleife"}],"loesung_key":"C","loesung":"Do-While-Schleife","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","quelle":"buch"},{"id":"b02f3","block":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Begriffe den passenden Beschreibungen zu:","begriffe":["Compiler","Interpreter","JIT-Compiler"],"beschreibungen":[{"key":"a","text":"Übersetzt den gesamten Code in Maschinensprache vor der Ausführung"},{"key":"b","text":"Führt den Code zeilenweise aus"},{"key":"c","text":"Übersetzt Code während der Laufzeit"}],"loesung_paare":{"Compiler":"a","Interpreter":"b","JIT-Compiler":"c"},"loesung":"Compiler = a; Interpreter = b; JIT-Compiler = c","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","quelle":"buch"},{"id":"b02f4","block":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"HTML ist eine Programmiersprache, weil es Logik und Berechnungen ausführen kann","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","quelle":"buch"},{"id":"b03f1","block":"Testing","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Testart prüft die vollständige, integrierte Softwarelösung gegen die Anforderungen?","optionen":[{"key":"A","text":"Unit Tests"},{"key":"B","text":"Integration Tests"},{"key":"C","text":"System Tests"},{"key":"D","text":"Regression Tests"}],"loesung_key":"C","loesung":"System Tests","kapitel":3,"kapitel_name":"Testing","quelle":"buch","bild":"b03f1.png"},{"id":"b03f2","block":"Testing","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei Whitebox-Tests ist das Testen der internen Struktur und Logik eines Programms von entscheidender Bedeutung","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","kapitel":3,"kapitel_name":"Testing","quelle":"buch"},{"id":"b03f3","block":"Testing","typ":"lueckentext","typ_label":"Lückentext","frage":"Beim Einsatz von _____________ Frameworks werden externe Abhängigkeiten durch simulierte Objekte ersetzt, um Unit Tests zu isolieren","loesung":"Mocking","kapitel":3,"kapitel_name":"Testing","quelle":"buch","alternativen":["Mock"]},{"id":"b03f4","block":"Testing","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Unterschied zwischen Blackbox-Tests und Whitebox-Tests?","loesung":"Beim Blackbox-Test ist die innere Struktur des Programms nicht bekannt. Getestet wird ausschließlich über die Schnittstelle: für definierte Eingaben wird geprüft, ob die erwartete Ausgabe entsteht. Grundlage sind die Anforderungen, nicht der Code. Beim Whitebox-Test ist der Quellcode bekannt, und die Testfälle werden gezielt entlang der internen Logik gebildet, etwa um alle Verzweigungen und Pfade abzudecken. Blackbox prüft also das Verhalten nach außen, Whitebox die innere Umsetzung","kapitel":3,"kapitel_name":"Testing","quelle":"buch"},{"id":"b03f5","block":"Testing","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Testarten den passenden Beschreibungen zu:","begriffe":["Unit Test","Integration Test","System Test"],"beschreibungen":[{"key":"a","text":"Testet die kleinste isolierte Einheit eines Programms"},{"key":"b","text":"Überprüft die Zusammenarbeit mehrerer Komponenten"},{"key":"c","text":"Überprüft das gesamte System auf Einhaltung der Anforderungen"}],"loesung_paare":{"Unit Test":"a","Integration Test":"b","System Test":"c"},"loesung":"Unit Test = a; Integration Test = b; System Test = c","kapitel":3,"kapitel_name":"Testing","quelle":"buch","bild":"b03f1.png"},{"id":"b04f1","block":"Projektmanagement","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter der Sprint Retrospektive im Scrum-Framework, und was ist ihr Ziel?","loesung":"Die Sprint Retrospektive ist ein fixes Scrum-Ereignis am Ende jedes Sprints, das nach dem Sprint Review und vor dem nächsten Sprint stattfindet. Das Team betrachtet dabei nicht das Produkt, sondern die eigene Zusammenarbeit: Was ist gut gelaufen, was hat gestört, und was wird konkret verändert. Ziel ist die kontinuierliche Verbesserung des Arbeitsprozesses. Das Ergebnis sind konkrete Verbesserungsmaßnahmen, die im nächsten Sprint umgesetzt werden","kapitel":4,"kapitel_name":"Projektmanagement","quelle":"buch"},{"id":"b04f2","block":"Projektmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Was ist die primäre Aufgabe des Scrum Masters?","optionen":[{"key":"A","text":"Anforderungen priorisieren"},{"key":"B","text":"Den Entwicklungsprozess unterstützen und Hindernisse beseitigen"},{"key":"C","text":"Produkt-Inkremente liefern"},{"key":"D","text":"Mit Stakeholdern kommunizieren"}],"loesung_key":"B","loesung":"Den Entwicklungsprozess unterstützen und Hindernisse beseitigen","kapitel":4,"kapitel_name":"Projektmanagement","quelle":"buch"},{"id":"b04f3","block":"Projektmanagement","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Rollen im Scrum den entsprechenden Verantwortlichkeiten zu:","begriffe":["Product Owner","Scrum Master","Entwicklungsteam"],"beschreibungen":[{"key":"a","text":"Verantwortlich für das Product Backlog und die Priorisierung der Anforderungen"},{"key":"b","text":"Unterstützung des Scrum-Prozesses und Beseitigung von Hindernissen"},{"key":"c","text":"Erstellung potenziell auslieferbarer Produkt-Inkremente"}],"loesung_paare":{"Product Owner":"a","Scrum Master":"b","Entwicklungsteam":"c"},"loesung":"Product Owner = a; Scrum Master = b; Entwicklungsteam = c","kapitel":4,"kapitel_name":"Projektmanagement","quelle":"buch"},{"id":"b04f4","block":"Projektmanagement","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ ist ein geplanter und oft schrittweiser Prozess, bei dem eine neue Version der Software an eine größere Gruppe von Benutzern verteilt wird","loesung":"Rollout","kapitel":4,"kapitel_name":"Projektmanagement","quelle":"buch"},{"id":"b04f5","block":"Projektmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Im Wasserfallmodell sind Rücksprünge in vorherige Phasen nicht vorgesehen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","kapitel":4,"kapitel_name":"Projektmanagement","quelle":"buch"},{"id":"b05f1","block":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Was ist der Hauptvorteil von NoSQL-Datenbanken gegenüber relationalen Datenbanken?","optionen":[{"key":"A","text":"Unterstützung für relationale Abfragen"},{"key":"B","text":"Höhere Geschwindigkeit und Flexibilität bei großen Datenmengen"},{"key":"C","text":"Strikte Datenintegrität"},{"key":"D","text":"Verwendet SQL als Abfragesprache"}],"loesung_key":"B","loesung":"Höhere Geschwindigkeit und Flexibilität bei großen Datenmengen","kapitel":5,"kapitel_name":"Datenbanken","quelle":"buch"},{"id":"b05f2","block":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Primärschlüssel in einer Datenbanktabelle muss immer aus einer einzigen Spalte bestehen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":5,"kapitel_name":"Datenbanken","quelle":"buch"},{"id":"b05f3","block":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine ______________ ist eine spezielle Art von gespeicherter Prozedur, die automatisch ausgeführt wird, wenn bestimmte Ereignisse auf einer Datenbanktabelle auftreten","loesung":"Trigger","kapitel":5,"kapitel_name":"Datenbanken","quelle":"buch"},{"id":"b05f4","block":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Beschreiben Sie die Hauptvorteile von RAID 5 im Vergleich zu RAID 1","loesung":"RAID 5 verteilt Daten und Paritätsinformationen über alle Festplatten des Verbundes. Dadurch geht nur die Kapazität einer einzigen Platte für die Redundanz verloren, während RAID 1 durch Spiegelung die Hälfte der Gesamtkapazität benötigt. RAID 5 ist damit deutlich speichereffizienter, besonders bei vielen Platten. Zusätzlich verbessert die Verteilung über mehrere Platten die Lesegeschwindigkeit. Beide Verfahren verkraften den Ausfall einer Platte","kapitel":5,"kapitel_name":"Datenbanken","quelle":"buch","bild":"b05f4.png"},{"id":"b05f5","block":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Datenbanktypen den passenden Beschreibungen zu:","begriffe":["Relationale Datenbank","NoSQL-Datenbank","Objektorientierte Datenbank"],"beschreibungen":[{"key":"a","text":"Speichert Daten in Tabellen mit festen Beziehungen"},{"key":"b","text":"Speichert Daten in nicht-relationalen Formaten wie Dokumenten oder Schlüssel-Wert-Paaren"},{"key":"c","text":"Speichert Daten als Objekte, ähnlich wie in Programmiersprachen"}],"loesung_paare":{"Relationale Datenbank":"a","NoSQL-Datenbank":"b","Objektorientierte Datenbank":"c"},"loesung":"Relationale Datenbank = a; NoSQL-Datenbank = b; Objektorientierte Datenbank = c","kapitel":5,"kapitel_name":"Datenbanken","quelle":"buch"},{"id":"b06f1","block":"Datensicherung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Backup-Strategie sichert alle Daten jedes Mal, unabhängig von vorherigen Sicherungen?","optionen":[{"key":"A","text":"Differentielles Backup"},{"key":"B","text":"Inkrementelles Backup"},{"key":"C","text":"Vollbackup"},{"key":"D","text":"Spiegelbackup"}],"loesung_key":"C","loesung":"Vollbackup","kapitel":8,"kapitel_name":"Datensicherung","quelle":"buch","bild":"b06f1.png"},{"id":"b06f2","block":"Datensicherung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"RAID 0 bietet eine hohe Datensicherheit, da es Daten auf mehreren Festplatten spiegelt","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":8,"kapitel_name":"Datensicherung","quelle":"buch"},{"id":"b06f3","block":"Datensicherung","typ":"lueckentext","typ_label":"Lückentext","frage":"Das __________-Prinzip ist eine bewährte Backup-Strategie, die auf einer hierarchischen Struktur von Backups basiert","loesung":"Generationen-Prinzip","kapitel":8,"kapitel_name":"Datensicherung","quelle":"buch","alternativen":["Grandfather-Father-Son","Großvater-Vater-Sohn-Prinzip"]},{"id":"b06f4","block":"Datensicherung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Unterschied zwischen einem inkrementellen und einem differentiellen Backup?","loesung":"Ein inkrementelles Backup sichert nur jene Daten, die sich seit der letzten Sicherung geändert haben, unabhängig davon, ob diese ein Voll- oder ein inkrementelles Backup war. Ein differentielles Backup sichert alle Änderungen seit dem letzten Vollbackup. Inkrementelle Sicherungen sind dadurch kleiner und schneller, benötigen zur Wiederherstellung aber das Vollbackup und lückenlos alle nachfolgenden Inkremente. Für die Wiederherstellung einer differentiellen Sicherung genügen das Vollbackup und die letzte differentielle Sicherung","kapitel":8,"kapitel_name":"Datensicherung","quelle":"buch"},{"id":"b06f5","block":"Datensicherung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden RAID-Level den passenden Beschreibungen zu:","begriffe":["RAID 0","RAID 1","RAID 5"],"beschreibungen":[{"key":"a","text":"Daten werden in Streifen auf alle Festplatten verteilt, keine Redundanz"},{"key":"b","text":"Daten werden auf zwei oder mehr Festplatten gespiegelt"},{"key":"c","text":"Daten und Paritätsinformationen werden in Streifen auf alle Festplatten verteilt"}],"loesung_paare":{"RAID 0":"a","RAID 1":"b","RAID 5":"c"},"loesung":"RAID 0 = a; RAID 1 = b; RAID 5 = c","kapitel":8,"kapitel_name":"Datensicherung","quelle":"buch"},{"id":"b07f1","block":"Wirtschaftsrecht und DSGVO","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die Datenschutz-Grundverordnung (DSGVO) gilt nur für Unternehmen innerhalb der EU","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":9,"kapitel_name":"Wirtschaftsrecht","quelle":"buch"},{"id":"b07f2","block":"Wirtschaftsrecht und DSGVO","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei der ____________ in der DSGVO darf die Einwilligung zur Datenverarbeitung nicht an die Erfüllung eines Vertrages gekoppelt sein","loesung":"Koppelungsverbot","kapitel":9,"kapitel_name":"Wirtschaftsrecht","quelle":"buch"},{"id":"b07f3","block":"Wirtschaftsrecht und DSGVO","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter der Beweislastumkehr bei der Gewährleistung, und wann tritt sie ein?","loesung":"Von einer Beweislastumkehr spricht man, wenn nach Ablauf von zwölf Monaten ab Übergabe der Käufer beweisen muss, dass der Mangel bereits beim Kauf bestanden hat. Innerhalb der ersten zwölf Monate wird dagegen vermutet, dass der Mangel schon bei der Übergabe vorlag, und der Verkäufer müsste das Gegenteil beweisen","kapitel":9,"kapitel_name":"Wirtschaftsrecht","quelle":"buch"},{"id":"b07f4","block":"Wirtschaftsrecht und DSGVO","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Steuersatz gilt für den Verkauf von Büchern in Österreich?","optionen":[{"key":"A","text":"20%"},{"key":"B","text":"13%"},{"key":"C","text":"10%"},{"key":"D","text":"0%"}],"loesung_key":"C","loesung":"10 %","kapitel":9,"kapitel_name":"Wirtschaftsrecht","quelle":"buch","bild":"b07f4.png"},{"id":"b07f5","block":"Wirtschaftsrecht und DSGVO","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Vertragsarten den passenden Beschreibungen zu:","begriffe":["Kaufvertrag","Mietvertrag","Dienstleistungsvertrag"],"beschreibungen":[{"key":"a","text":"Regelt die Überlassung einer Immobilie oder eines Gegenstands zur Nutzung gegen Zahlung eines Mietzinses"},{"key":"b","text":"Vertrag, bei dem der Verkäufer sich verpflichtet, dem Käufer eine Sache zu übergeben"},{"key":"c","text":"Vereinbarungen über die Erbringung einer Dienstleistung gegen Entgelt"}],"loesung_paare":{"Kaufvertrag":"b","Mietvertrag":"a","Dienstleistungsvertrag":"c"},"loesung":"Kaufvertrag = b; Mietvertrag = a; Dienstleistungsvertrag = c","kapitel":9,"kapitel_name":"Wirtschaftsrecht","quelle":"buch"},{"id":"b08f1","block":"Drucker","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Druckertechnologie ist am besten für den schnellen Schwarzweißdruck geeignet und bietet gleichzeitig dokumentenechte Ergebnisse?","optionen":[{"key":"A","text":"Tintenstrahldrucker"},{"key":"B","text":"Laserdrucker"},{"key":"C","text":"Nadeldrucker"},{"key":"D","text":"Thermodirektdrucker"}],"loesung_key":"B","loesung":"Laserdrucker","kapitel":11,"kapitel_name":"Drucker","quelle":"buch"},{"id":"b08f2","block":"Drucker","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Tintenstrahldrucker eignen sich besser für hochwertige Fotoausdrucke als Laserdrucker","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","kapitel":11,"kapitel_name":"Drucker","quelle":"buch"},{"id":"b08f3","block":"Drucker","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein ___________ Drucker verwendet Nadeln, die durch ein Farbband auf das Papier schlagen, um Texte und Bilder zu drucken","loesung":"Nadeldrucker","kapitel":11,"kapitel_name":"Drucker","quelle":"buch","alternativen":["Matrixdrucker","Nadelmatrixdrucker"]},{"id":"b08f4","block":"Drucker","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Vorteile von Laserdruckern gegenüber Tintenstrahldruckern","loesung":"Laserdrucker arbeiten deutlich schneller, insbesondere bei hohem Druckaufkommen im Schwarzweißbereich. Zweitens sind die Kosten pro Seite geringer, da eine Tonerkartusche eine wesentlich höhere Reichweite hat als eine Tintenpatrone. Zusätzlich sind Laserausdrucke dokumentenecht und der Toner kann im Gerät nicht eintrocknen, was bei seltener Nutzung ein Vorteil ist","kapitel":11,"kapitel_name":"Drucker","quelle":"buch"},{"id":"b08f5","block":"Drucker","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Druckerarten den passenden Beschreibungen zu:","begriffe":["Nadeldrucker","Tintenstrahldrucker","Laserdrucker"],"beschreibungen":[{"key":"a","text":"Arbeitet mit mechanischem Druck und erzeugt eine Punktmatrix"},{"key":"b","text":"Nutzt Tinte in Patronen, um Bilder und Texte zu spritzen"},{"key":"c","text":"Verwendet eine Walze und Toner, um das Bild zu übertragen"}],"loesung_paare":{"Nadeldrucker":"a","Tintenstrahldrucker":"b","Laserdrucker":"c"},"loesung":"Nadeldrucker = a; Tintenstrahldrucker = b; Laserdrucker = c","kapitel":11,"kapitel_name":"Drucker","quelle":"buch"},{"id":"b09f1","block":"Domain Controller und Netzwerkadministration","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Rolle spielt ein Domänencontroller in einem Netzwerk?","optionen":[{"key":"A","text":"Er speichert Daten für alle Benutzer"},{"key":"B","text":"Er authentifiziert und autorisiert alle Benutzer und Computer in einem Windows-Domänennetzwerk"},{"key":"C","text":"Er fungiert als Backup-Server für die gesamten Netzwerkdaten"},{"key":"D","text":"Er verwaltet den Internetzugang für alle Benutzer"}],"loesung_key":"B","loesung":"Er authentifiziert und autorisiert alle Benutzer und Computer in einem Windows-Domänennetzwerk","kapitel":13,"kapitel_name":"Domänencontroller","quelle":"buch"},{"id":"b09f2","block":"Domain Controller und Netzwerkadministration","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Lokale Administratoren haben in einem Netzwerk mit Domänencontroller immer mehr Rechte als Domänenadministratoren","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":13,"kapitel_name":"Domänencontroller","quelle":"buch"},{"id":"b09f3","block":"Domain Controller und Netzwerkadministration","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Sicherheitsvorteile bietet die Verwendung eines Domänencontrollers gegenüber der Verwaltung von Benutzern und Computern in einer Arbeitsgruppe?","loesung":"In einer Domäne werden Benutzerkonten und Kennwörter zentral verwaltet. Ein Benutzer meldet sich mit einem einzigen Konto an jedem berechtigten Rechner an, statt auf jedem Gerät ein eigenes lokales Konto zu benötigen. Sicherheitsrichtlinien wie Kennwortkomplexität, Sperrschwellen und Softwareeinschränkungen lassen sich über Gruppenrichtlinien einheitlich durchsetzen. Berechtigungen werden über Gruppen vergeben und sind dadurch nachvollziehbar. Beim Ausscheiden eines Mitarbeiters genügt das Sperren eines einzigen Kontos, um den Zugang zu allen Systemen zu entziehen. In der Arbeitsgruppe ist jede dieser Maßnahmen auf jedem Rechner einzeln vorzunehmen","kapitel":13,"kapitel_name":"Domänencontroller","quelle":"buch"},{"id":"b09f4","block":"Domain Controller und Netzwerkadministration","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Begriffe den passenden Definitionen zu:","begriffe":["Active Directory","Group Policy","Organizational Unit (OU)"],"beschreibungen":[{"key":"a","text":"Eine Funktion von Windows Server zur zentralen Verwaltung und Konfiguration von Betriebssystemen, Anwendungen und Benutzereinstellungen in einer Active Directory Umgebung"},{"key":"b","text":"Eine Hierarchie, die verwendet wird, um Benutzer, Gruppen, Computer und andere Objekte in einer Domäne zu organisieren"},{"key":"c","text":"Ein Verzeichnisdienst von Microsoft für Windows-Domänennetzwerke"}],"loesung_paare":{"Active Directory":"c","Group Policy":"a","Organizational Unit (OU)":"b"},"loesung":"Active Directory = c; Group Policy = a; Organizational Unit (OU) = b","kapitel":13,"kapitel_name":"Domänencontroller","quelle":"buch"},{"id":"b09f5","block":"Domain Controller und Netzwerkadministration","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ ist ein Server, der die Anmeldungen der Benutzer in einem Netzwerk verwaltet und autorisiert","loesung":"Domänencontroller","kapitel":13,"kapitel_name":"Domänencontroller","quelle":"buch","alternativen":["DC","Domain Controller"]},{"id":"b10f1","block":"Netzwerktechnik und Netzwerke","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche der folgenden Aussagen beschreibt ein WAN (Wide Area Network)?","optionen":[{"key":"A","text":"Ein kleines Netzwerk in einem Büro"},{"key":"B","text":"Ein Netzwerk, das Städte oder Länder verbindet"},{"key":"C","text":"Ein Netzwerk in einer einzelnen Wohnung"},{"key":"D","text":"Ein Netzwerk, das nur drahtlose Verbindungen nutzt"}],"loesung_key":"B","loesung":"Ein Netzwerk, das Städte oder Länder verbindet","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b10f2","block":"Netzwerktechnik und Netzwerke","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein LAN (Local Area Network) deckt typischerweise eine größere geografische Fläche als ein WAN ab","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b10f3","block":"Netzwerktechnik und Netzwerke","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine _____________ beschreibt die physische oder logische Struktur eines Netzwerks und die Art, wie die Geräte miteinander verbunden sind","loesung":"Netzwerktopologie","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch","alternativen":["Topologie"]},{"id":"b10f4","block":"Netzwerktechnik und Netzwerke","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was sind die Hauptunterschiede zwischen einem LAN, WAN und MAN?","loesung":"Die drei Netzwerktypen unterscheiden sich vor allem in ihrer räumlichen Ausdehnung. Ein LAN ist ein lokales Netzwerk innerhalb eines Gebäudes oder Geländes, es wird meist selbst betrieben und erreicht hohe Übertragungsraten bei geringen Kosten. Ein MAN verbindet mehrere Standorte innerhalb einer Stadt oder Region, etwa mehrere Firmenniederlassungen. Ein WAN überbrückt sehr große Entfernungen zwischen Städten oder Ländern, nutzt dafür in der Regel Leitungen öffentlicher Anbieter und weist gegenüber dem LAN höhere Latenzen und geringere Bandbreiten auf","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b10f5","block":"Netzwerktechnik und Netzwerke","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Netzwerktopologien den entsprechenden Beschreibungen zu:","begriffe":["Stern-Topologie","Bus-Topologie","Ring-Topologie","Baum-Topologie"],"beschreibungen":[{"key":"a","text":"Alle Geräte sind direkt mit einem zentralen Gerät verbunden"},{"key":"b","text":"Alle Geräte sind an ein gemeinsames Übertragungsmedium angeschlossen"},{"key":"c","text":"Geräte sind in einer kreisförmigen Struktur miteinander verbunden"},{"key":"d","text":"Eine hierarchische Struktur, die Bus- und Stern-Topologie kombiniert"}],"loesung_paare":{"Stern-Topologie":"a","Bus-Topologie":"b","Ring-Topologie":"c","Baum-Topologie":"d"},"loesung":"Stern-Topologie = a; Bus-Topologie = b; Ring-Topologie = c; Baum-Topologie = d","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b11f1","block":"MAC- und IP-Adressen","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Adresse wird zur Identifikation von Geräten innerhalb eines LANs verwendet?","optionen":[{"key":"A","text":"IP-Adresse"},{"key":"B","text":"MAC-Adresse"},{"key":"C","text":"Hostname"},{"key":"D","text":"URL"}],"loesung_key":"B","loesung":"MAC-Adresse","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b11f2","block":"MAC- und IP-Adressen","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine IPv6-Adresse besteht aus 128 Bit und bietet eine nahezu unerschöpfliche Anzahl von Adressen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b11f3","block":"MAC- und IP-Adressen","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine MAC-Adresse besteht aus _____________ Bit und ist fest in die Netzwerkschnittstellenkarte (NIC) eingebrannt","loesung":"48","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch","alternativen":["48 Bit","6 Byte"],"bild":"b11f3.png"},{"id":"b11f4","block":"MAC- und IP-Adressen","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Beschreiben Sie den Unterschied zwischen einer statischen und einer dynamischen IP-Adresse","loesung":"Eine statische IP-Adresse wird einem Gerät fest zugewiesen und bleibt dauerhaft unverändert. Sie wird dort eingesetzt, wo ein Gerät zuverlässig unter derselben Adresse erreichbar sein muss, etwa bei Servern, Druckern oder Netzwerkkomponenten. Eine dynamische IP-Adresse wird einem Gerät bei der Anmeldung im Netzwerk automatisch von einem DHCP-Server aus einem Adresspool zugeteilt und ist nur für die Dauer der Lease gültig. Das reduziert den Verwaltungsaufwand und vermeidet Adresskonflikte, weshalb Clientgeräte üblicherweise dynamisch adressiert werden","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b11f5","block":"MAC- und IP-Adressen","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Adresstypen ihren Beschreibungen zu:","begriffe":["MAC-Adresse","IPv4-Adresse","IPv6-Adresse"],"beschreibungen":[{"key":"a","text":"Eine 48-Bit-Adresse, die Geräte in einem lokalen Netzwerk identifiziert"},{"key":"b","text":"Eine 32-Bit-Adresse, die Geräte in einem Netzwerk identifiziert, bestehend aus vier Oktetten"},{"key":"c","text":"Eine 128-Bit-Adresse, die aus acht Gruppen von vier hexadezimalen Ziffern besteht"}],"loesung_paare":{"MAC-Adresse":"a","IPv4-Adresse":"b","IPv6-Adresse":"c"},"loesung":"MAC-Adresse = a; IPv4-Adresse = b; IPv6-Adresse = c","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b12f1","block":"Netzwerkgeräte und Komponenten","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche aktive Netzwerkkomponente verstärkt das Signal über große Entfernungen?","optionen":[{"key":"A","text":"Router"},{"key":"B","text":"Repeater"},{"key":"C","text":"Switch"},{"key":"D","text":"Modem"}],"loesung_key":"B","loesung":"Repeater","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b12f2","block":"Netzwerkgeräte und Komponenten","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Switch leitet Datenpakete basierend auf IP-Adressen weiter","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch","bild":"b12f2.png"},{"id":"b12f3","block":"Netzwerkgeräte und Komponenten","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ ermöglicht drahtlosen Geräten den Zugang zu einem kabelgebundenen Netzwerk und fungiert als Brücke zwischen WLAN-Clients und dem LAN","loesung":"Access Point","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch","alternativen":["AP","WLAN Access Point","Wireless Access Point"]},{"id":"b12f4","block":"Netzwerkgeräte und Komponenten","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Hauptunterschiede zwischen einem Router und einem Switch","loesung":"Der erste Unterschied liegt in der Schicht des OSI-Modells: Der Switch arbeitet auf Schicht 2 und trifft seine Weiterleitungsentscheidung anhand der MAC-Adresse, der Router arbeitet auf Schicht 3 und entscheidet anhand der IP-Adresse. Der zweite Unterschied liegt im Aufgabenbereich: Der Switch verbindet Geräte innerhalb desselben Netzwerks, der Router verbindet unterschiedliche Netzwerke miteinander und stellt beispielsweise die Verbindung des LAN zum Internet her","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch","bild":"b12f4.png"},{"id":"b12f5","block":"Netzwerkgeräte und Komponenten","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Netzwerkgeräte den passenden Funktionen zu:","begriffe":["Repeater","Router","Switch"],"beschreibungen":[{"key":"a","text":"Verstärkt das Signal, um die Reichweite zu erhöhen"},{"key":"b","text":"Verbindet verschiedene Netzwerke und leitet Daten basierend auf IP-Adressen weiter"},{"key":"c","text":"Leitet Datenpakete innerhalb eines Netzwerks basierend auf MAC-Adressen"}],"loesung_paare":{"Repeater":"a","Router":"b","Switch":"c"},"loesung":"Repeater = a; Router = b; Switch = c","kapitel":6,"kapitel_name":"Netzwerktechnik","quelle":"buch"},{"id":"b13f1","block":"Antivirus","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Funktion bietet ein Antivirus-Programm, um das System kontinuierlich vor Bedrohungen zu schützen?","optionen":[{"key":"A","text":"Gelegentliche Scans"},{"key":"B","text":"Echtzeit-Überwachung"},{"key":"C","text":"Manuelle Updates"},{"key":"D","text":"Nur Online-Schutz"}],"loesung_key":"B","loesung":"Echtzeit-Überwachung","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b13f2","block":"Antivirus","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Antivirus-Software kann nur bekannte Bedrohungen erkennen und bietet keinen Schutz vor neuen Bedrohungen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b13f3","block":"Antivirus","typ":"lueckentext","typ_label":"Lückentext","frage":"Die ___________ Erkennung analysiert das Verhalten von Programmen, um verdächtige Aktivitäten zu identifizieren","loesung":"verhaltensbasierte","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","alternativen":["heuristische"]},{"id":"b13f4","block":"Antivirus","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Hauptfunktionen eines Antivirus-Programms, die zum Schutz des Systems beitragen","loesung":"Die erste Hauptfunktion ist die Echtzeit-Überwachung. Dabei werden alle Dateizugriffe und laufenden Prozesse fortlaufend überprüft, sodass Schadsoftware blockiert wird, bevor sie ausgeführt werden kann. Die zweite Hauptfunktion ist der signaturbasierte Scan in Verbindung mit regelmäßigen Signatur-Updates, mit dem der gesamte Datenbestand geplant oder manuell auf bekannte Schädlinge geprüft wird. Ergänzend kommt die verhaltensbasierte Erkennung hinzu, die auch unbekannte Bedrohungen anhand auffälliger Aktivitäten identifiziert","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b13f5","block":"Antivirus","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Funktionen eines Antivirus-Programms den passenden Beschreibungen zu:","begriffe":["Echtzeit-Überwachung","Verhaltensbasierte Erkennung","Regelmäßige Scans"],"beschreibungen":[{"key":"a","text":"Scannt das System kontinuierlich auf Bedrohungen, während es verwendet wird"},{"key":"b","text":"Erkennt Bedrohungen basierend auf auffälligem Verhalten von Programmen"},{"key":"c","text":"Führt geplante Überprüfungen des gesamten Systems durch"}],"loesung_paare":{"Echtzeit-Überwachung":"a","Verhaltensbasierte Erkennung":"b","Regelmäßige Scans":"c"},"loesung":"Echtzeit-Überwachung = a; Verhaltensbasierte Erkennung = b; Regelmäßige Scans = c","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b14f1","block":"Passwortmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Passwortrichtlinie verhindert die Wiederverwendung alter Passwörter?","optionen":[{"key":"A","text":"Ablaufzeit"},{"key":"B","text":"Komplexität"},{"key":"C","text":"History"},{"key":"D","text":"Länge"}],"loesung_key":"C","loesung":"History","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b14f2","block":"Passwortmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Passwörter sollten niemals Sonderzeichen enthalten, da sie schwer zu merken sind","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b14f3","block":"Passwortmanagement","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine empfohlene Passwortrichtlinie sieht vor, dass Passwörter regelmäßig, etwa alle __________ Tage, geändert werden sollten","loesung":"60 bis 90","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","alternativen":["90 Tage"]},{"id":"b14f4","block":"Passwortmanagement","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter der Komplexität eines Passworts? Nennen Sie zwei Anforderungen","loesung":"Die Komplexität beschreibt, aus wie vielen unterschiedlichen Zeichenarten ein Passwort zusammengesetzt ist und wie schwer es dadurch zu erraten oder systematisch durchzuprobieren ist. Eine erste Anforderung ist die Kombination mehrerer Zeichenarten, also Groß- und Kleinbuchstaben, Ziffern und Sonderzeichen. Eine zweite Anforderung ist eine ausreichende Mindestlänge, üblicherweise mindestens acht bis zwölf Zeichen. Zusätzlich sollte ein Passwort keine Wörterbuchbegriffe und keinen Bezug zur Person enthalten","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b14f5","block":"Passwortmanagement","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Passwortrichtlinien den entsprechenden Beschreibungen zu:","begriffe":["Komplexität","Ablaufzeit","History"],"beschreibungen":[{"key":"a","text":"Definiert, wie häufig ein Passwort geändert werden muss"},{"key":"b","text":"Verhindert die Wiederverwendung der letzten Passwörter"},{"key":"c","text":"Bestimmt die Kombination aus Buchstaben, Zahlen und Sonderzeichen"}],"loesung_paare":{"Komplexität":"c","Ablaufzeit":"a","History":"b"},"loesung":"Komplexität = c; Ablaufzeit = a; History = b","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b15f1","block":"Multi-Faktor-Authentifizierung (MFA)","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Art von MFA verwendet biometrische Merkmale zur Authentifizierung?","optionen":[{"key":"A","text":"Einmalpasswort (OTP)"},{"key":"B","text":"Hardware-Token"},{"key":"C","text":"Biometrische Authentifizierung"},{"key":"D","text":"SMS-Code"}],"loesung_key":"C","loesung":"Biometrische Authentifizierung","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b15f2","block":"Multi-Faktor-Authentifizierung (MFA)","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"MFA schützt vor unbefugtem Zugriff, indem es nur ein zusätzliches Passwort erfordert","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b15f3","block":"Multi-Faktor-Authentifizierung (MFA)","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein _________ generiert Einmal-Codes und kann als physisches Gerät oder App verwendet werden","loesung":"Token","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","alternativen":["Authenticator","Hardware-Token","OTP-Token"]},{"id":"b15f4","block":"Multi-Faktor-Authentifizierung (MFA)","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Vorteile der Multi-Faktor-Authentifizierung","loesung":"Der erste Vorteil ist der deutlich höhere Schutz bei kompromittierten Zugangsdaten. Selbst wenn ein Angreifer das Passwort durch Phishing oder ein Datenleck erlangt, fehlt ihm der zweite Faktor, sodass die Anmeldung scheitert. Der zweite Vorteil ist die wirksame Abwehr automatisierter Angriffe wie Brute Force oder Credential Stuffing, da diese Verfahren ausschließlich auf das Passwort zielen. Zusätzlich wird ein Anmeldeversuch für den Benutzer sichtbar, weil er eine unerwartete Bestätigungsanfrage erhält","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b15f5","block":"Multi-Faktor-Authentifizierung (MFA)","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die MFA-Typen den entsprechenden Funktionen zu:","begriffe":["Einmalpasswort (OTP)","Biometrische Authentifizierung","Hardware-Token"],"beschreibungen":[{"key":"a","text":"Erzeugt Einmal-Codes für die Anmeldung"},{"key":"b","text":"Verwendet Fingerabdruck oder Gesichtserkennung"},{"key":"c","text":"Physisches Gerät, das zur Authentifizierung genutzt wird"}],"loesung_paare":{"Einmalpasswort (OTP)":"a","Biometrische Authentifizierung":"b","Hardware-Token":"c"},"loesung":"Einmalpasswort (OTP) = a; Biometrische Authentifizierung = b; Hardware-Token = c","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b16f1","block":"Ausfallsicherheit","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Netzwerktopologie bietet hohe Redundanz und ist besonders für kritische Anwendungen geeignet?","optionen":[{"key":"A","text":"Stern-Topologie"},{"key":"B","text":"Vermaschte Topologie"},{"key":"C","text":"Bus-Topologie"},{"key":"D","text":"Ring-Topologie"}],"loesung_key":"B","loesung":"Vermaschte Topologie","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b16f2","block":"Ausfallsicherheit","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine passive USV bietet unterbrechungsfreie Stromversorgung bei allen Arten von Spannungsabweichungen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b16f3","block":"Ausfallsicherheit","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine ________ sorgt dafür, dass bei einem Stromausfall eine unterbrechungsfreie Stromversorgung gewährleistet bleibt","loesung":"USV","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","alternativen":["UPS","unterbrechungsfreie Stromversorgung"]},{"id":"b16f4","block":"Ausfallsicherheit","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Vorteile einer vermaschten Netzwerktopologie","loesung":"Der erste Vorteil ist die hohe Ausfallsicherheit. Da jedes Gerät über mehrere Verbindungen verfügt, kann der Datenverkehr bei einem Leitungsausfall über einen alternativen Pfad umgeleitet werden, ohne dass das Netzwerk ausfällt. Der zweite Vorteil ist die hohe Leistungsfähigkeit, weil die Last auf mehrere Wege verteilt wird und Punkt-zu-Punkt-Verbindungen bestehen, sodass es keine gemeinsam genutzte Engstelle gibt","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","bild":"b16f4.png"},{"id":"b16f5","block":"Ausfallsicherheit","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die USV-Typen ihren Einsatzbereichen zu:","begriffe":["Aktive USV","Passive USV","Netzinteraktive USV"],"beschreibungen":[{"key":"a","text":"Bietet kontinuierlichen Schutz und Spannungsanpassungen"},{"key":"b","text":"Schaltet sich bei Stromausfällen ein, für weniger kritische Systeme"},{"key":"c","text":"Gewährleistet konstante Stromversorgung für kritische Infrastrukturen"}],"loesung_paare":{"Aktive USV":"c","Passive USV":"b","Netzinteraktive USV":"a"},"loesung":"Aktive USV = c; Passive USV = b; Netzinteraktive USV = a","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b17f1","block":"Sicherheitstechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Sicherheitstechnik schützt vor elektrischem Schlag durch sofortiges Abschalten des Stroms?","optionen":[{"key":"A","text":"LS-Schalter"},{"key":"B","text":"FI-Schalter"},{"key":"C","text":"Überspannungsschutz"},{"key":"D","text":"Sicherung"}],"loesung_key":"B","loesung":"FI-Schalter","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b17f2","block":"Sicherheitstechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"LS-Schalter schützen ausschließlich vor Kurzschlüssen, nicht aber vor Überlastungen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","bild":"b17f2.png"},{"id":"b17f3","block":"Sicherheitstechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein _________ unterbricht den Stromkreis, wenn der Strom eine gefährliche Höhe erreicht, um Leitungen zu schützen","loesung":"LS-Schalter","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","alternativen":["Leitungsschutzschalter","Sicherungsautomat"],"bild":"b17f2.png"},{"id":"b17f4","block":"Sicherheitstechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie die Funktion eines FI-Schalters in einem Stromkreis","loesung":"Der FI-Schalter (Fehlerstromschutzschalter, auch RCD) misst laufend den Strom, der über den Außenleiter in den Stromkreis hineinfließt, und den Strom, der über den Neutralleiter zurückfließt. Im fehlerfreien Betrieb sind beide gleich groß. Fließt ein Teil des Stroms über einen anderen Weg ab, etwa über den Körper eines Menschen oder eine schadhafte Isolierung zur Erde, entsteht eine Differenz. Überschreitet diese Differenz den Nennfehlerstrom, typischerweise 30 Milliampere im Wohnbereich, trennt der FI-Schalter den Stromkreis innerhalb von Millisekunden. Er dient damit in erster Linie dem Personenschutz und zusätzlich dem Brandschutz","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch","bild":"b17f4.png"},{"id":"b17f5","block":"Sicherheitstechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Sicherheitstechniken den entsprechenden Funktionen zu:","begriffe":["FI-Schalter","LS-Schalter","Überspannungsschutz"],"beschreibungen":[{"key":"a","text":"Schützt vor gefährlichen Fehlerströmen und elektrischem Schlag"},{"key":"b","text":"Unterbricht bei Überlast und Kurzschluss"},{"key":"c","text":"Verhindert Schäden durch Spannungsüberschläge"}],"loesung_paare":{"FI-Schalter":"a","LS-Schalter":"b","Überspannungsschutz":"c"},"loesung":"FI-Schalter = a; LS-Schalter = b; Überspannungsschutz = c","kapitel":7,"kapitel_name":"Sicherheitstechnik","quelle":"buch"},{"id":"b18f1","block":"Kupferkabel","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Warum sind Kupferkabel eine bevorzugte Wahl für lokale Netzwerke (LANs)?","optionen":[{"key":"A","text":"Sie verwenden Lichtsignale"},{"key":"B","text":"Sie sind teuer und schwer zu installieren"},{"key":"C","text":"Sie sind flexibel, kosteneffizient und einfach zu installieren"},{"key":"D","text":"Sie sind nur für Langstreckenverbindungen geeignet"}],"loesung_key":"C","loesung":"Sie sind flexibel, kosteneffizient und einfach zu installieren","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b18f2","block":"Kupferkabel","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Kupferkabel sind ausschließlich in großen Weitverkehrsnetzen (WANs) zu finden","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b18f3","block":"Kupferkabel","typ":"lueckentext","typ_label":"Lückentext","frage":"Kupferkabel verwenden ___________ Signale zur Datenübertragung und sind besonders in Bürokomplexen weit verbreitet","loesung":"elektrische","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b18f4","block":"Kupferkabel","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Vorteile der Verwendung von Kupferkabeln in lokalen Netzwerken","loesung":"Der erste Vorteil sind die geringen Kosten. Sowohl das Kabelmaterial als auch die benötigten Netzwerkkomponenten und Stecker sind deutlich günstiger als bei Glasfaser. Der zweite Vorteil ist die einfache Installation, da Kupferkabel flexibel sind, sich mit einer einfachen Crimpzange konfektionieren lassen und kein Spezialwerkzeug wie ein Spleißgerät erfordern. Zusätzlich ermöglichen Kupferkabel Power over Ethernet, also die Stromversorgung von Endgeräten über dasselbe Kabel","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b18f5","block":"Kupferkabel","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Eigenschaften den Kabeltypen zu:","begriffe":["Flexibilität","Verwendung elektrischer Signale","Einfache Installation"],"beschreibungen":[{"key":"a","text":"Sind leicht zu verlegen und passen sich gut an verschiedene Umgebungen an"},{"key":"b","text":"Nutzen Strom für die Übertragung von Daten"},{"key":"c","text":"Erfordern keine spezialisierten Werkzeuge oder Fachkenntnisse"}],"loesung_paare":{"Flexibilität":"a","Verwendung elektrischer Signale":"b","Einfache Installation":"c"},"loesung":"Flexibilität = a; Verwendung elektrischer Signale = b; Einfache Installation = c","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b19f1","block":"Steckertypen für Kupferkabel","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Steckertyp wird häufig in Ethernet-Netzwerken verwendet?","optionen":[{"key":"A","text":"BNC"},{"key":"B","text":"RJ45"},{"key":"C","text":"VGA"},{"key":"D","text":"HDMI"}],"loesung_key":"B","loesung":"RJ45","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b19f2","block":"Steckertypen für Kupferkabel","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"BNC-Stecker werden ausschließlich in modernen Ethernet-Netzwerken eingesetzt","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b19f2.png"},{"id":"b19f3","block":"Steckertypen für Kupferkabel","typ":"lueckentext","typ_label":"Lückentext","frage":"Der _________ Stecker ist der Standard für Twisted-Pair-Kabel in Ethernet-Netzwerken","loesung":"RJ45","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b19f4","block":"Steckertypen für Kupferkabel","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"In welchen speziellen Anwendungen werden BNC-Stecker verwendet?","loesung":"BNC-Stecker werden vor allem in der professionellen Videoübertragung eingesetzt, etwa bei Überwachungskameras und SDI-Verbindungen im Studiobereich. Ein weiteres Anwendungsgebiet ist die Mess- und Labortechnik, beispielsweise an Oszilloskopen und Signalgeneratoren. Historisch wurden sie außerdem in Koaxial-Ethernet-Netzwerken verwendet. Der Vorteil des Steckers liegt im Bajonettverschluss, der eine sichere und schnell lösbare Verbindung ermöglicht","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b19f2.png"},{"id":"b19f5","block":"Steckertypen für Kupferkabel","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Steckertypen den entsprechenden Verwendungen zu:","begriffe":["RJ45","BNC"],"beschreibungen":[{"key":"a","text":"Wird in professionellen Videoübertragungen und älteren Netzwerken genutzt"},{"key":"b","text":"Standardstecker für Ethernet-Verbindungen"}],"loesung_paare":{"RJ45":"b","BNC":"a"},"loesung":"RJ45 = b; BNC = a","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b20f1","block":"Typen von Kupferkabeln","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Twisted Pair Kabel bietet die höchste Übertragungsgeschwindigkeit und Bandbreite?","optionen":[{"key":"A","text":"Cat5"},{"key":"B","text":"Cat6"},{"key":"C","text":"Cat7"},{"key":"D","text":"Cat8"}],"loesung_key":"D","loesung":"Cat8","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b20f1.png"},{"id":"b20f2","block":"Typen von Kupferkabeln","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Twisted Pair Kabel sind immer ungeschirmt, um Kosten zu sparen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b20f3","block":"Typen von Kupferkabeln","typ":"lueckentext","typ_label":"Lückentext","frage":"Twisted Pair Kabel bestehen aus mehreren paarweise __________ Drähten, um Störungen zu reduzieren","loesung":"verdrillten","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","alternativen":["verdrillt","verseilten"],"bild":"b20f1.png"},{"id":"b20f4","block":"Typen von Kupferkabeln","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Hauptunterschied zwischen Cat5 und Cat6 Kabeln?","loesung":"Der Hauptunterschied liegt in der übertragbaren Bandbreite und der daraus folgenden Geschwindigkeit. Cat5 ist für eine Bandbreite von 100 MHz ausgelegt und erreicht damit 100 Mbit/s, in der Variante Cat5e bis zu 1 Gbit/s. Cat6 ist für 250 MHz spezifiziert und ermöglicht 1 Gbit/s über die volle Länge von 100 Metern sowie 10 Gbit/s über verkürzte Strecken. Erreicht wird das durch eine engere Verdrillung und häufig einen Kunststoffsteg, der die Adernpaare voneinander trennt und so das Übersprechen reduziert","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b20f1.png"},{"id":"b20f5","block":"Typen von Kupferkabeln","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Twisted Pair Kabel den Kategorien zu:","begriffe":["Cat5","Cat6","Cat7"],"beschreibungen":[{"key":"a","text":"Eignet sich für hohe Übertragungsgeschwindigkeiten und störungsarme Umgebungen"},{"key":"b","text":"Verwendet für Standard-Ethernet-Verbindungen in Büroumgebungen"},{"key":"c","text":"Bietet höhere Bandbreite und längere Übertragungsdistanzen als frühere Generationen"}],"loesung_paare":{"Cat5":"b","Cat6":"c","Cat7":"a"},"loesung":"Cat5 = b; Cat6 = c; Cat7 = a","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b21f1","block":"Abschirmungsarten bei Twisted Pair Kabeln","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Abschirmungsart bietet den höchsten Schutz vor elektromagnetischen Störungen?","optionen":[{"key":"A","text":"UTP"},{"key":"B","text":"STP"},{"key":"C","text":"FTP"},{"key":"D","text":"SSTP"}],"loesung_key":"D","loesung":"SSTP","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b21f2","block":"Abschirmungsarten bei Twisted Pair Kabeln","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Unshielded Twisted Pair (UTP) Kabel sind teurer als abgeschirmte Kabel","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b21f3","block":"Abschirmungsarten bei Twisted Pair Kabeln","typ":"lueckentext","typ_label":"Lückentext","frage":"___________ Twisted Pair Kabel sind mit einer Aluminiumfolie umwickelt, die zusätzlichen Schutz bietet","loesung":"Foiled (FTP)","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","alternativen":["FTP","Foiled Twisted Pair"]},{"id":"b21f4","block":"Abschirmungsarten bei Twisted Pair Kabeln","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Vorteil von Shielded Twisted Pair (STP) Kabeln gegenüber UTP?","loesung":"Der Vorteil liegt in der Abschirmung, die elektromagnetische Störungen von außen weitgehend abhält und gleichzeitig verhindert, dass das Kabel selbst störend abstrahlt. Dadurch bleibt die Signalqualität auch in Umgebungen mit starken Störquellen erhalten, etwa in Industriehallen, in der Nähe von Motoren oder entlang von Stromleitungen. Zusätzlich wird das Übersprechen zwischen den Adernpaaren reduziert, wodurch höhere Übertragungsraten zuverlässig erreicht werden. Voraussetzung ist allerdings eine korrekte Erdung des Schirms, da eine fehlerhafte Erdung die Störungen sogar verstärken kann","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b21f5","block":"Abschirmungsarten bei Twisted Pair Kabeln","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Abschirmungsarten den Eigenschaften zu:","begriffe":["UTP","STP","FTP","SSTP"],"beschreibungen":[{"key":"a","text":"Bietet keinen zusätzlichen Schutz, ist aber kostengünstig"},{"key":"b","text":"Jedes Paar ist einzeln abgeschirmt, und das gesamte Kabel ist zusätzlich umwickelt"},{"key":"c","text":"Umwickelt mit einer Folie für zusätzlichen Schutz"},{"key":"d","text":"Schirmt die einzelnen Paare und das gesamte Kabel ab"}],"loesung_paare":{"UTP":"a","STP":"d","FTP":"c","SSTP":"b"},"loesung":"UTP = a; STP = d; FTP = c; SSTP = b","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b22f1","block":"Koaxialkabel","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wo werden Koaxialkabel typischerweise eingesetzt?","optionen":[{"key":"A","text":"In modernen WLAN-Netzwerken"},{"key":"B","text":"In Kabel-TV-Netzwerken"},{"key":"C","text":"Nur in Rechenzentren"},{"key":"D","text":"In der Glasfasertechnik"}],"loesung_key":"B","loesung":"In Kabel-TV-Netzwerken","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b22f1.png"},{"id":"b22f2","block":"Koaxialkabel","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Koaxialkabel bieten weniger Schutz vor elektromagnetischen Störungen als Twisted Pair Kabel","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b22f3","block":"Koaxialkabel","typ":"lueckentext","typ_label":"Lückentext","frage":"Koaxialkabel bestehen aus einem zentralen Kupferleiter, einem __________ und einer äußeren Isolationshülle","loesung":"Isoliermaterial und metallisches Abschirmgeflecht","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","alternativen":["Abschirmung","Außenleiter"],"bild":"b22f1.png"},{"id":"b22f4","block":"Koaxialkabel","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Vorteile von Koaxialkabeln","loesung":"Der erste Vorteil ist die sehr gute Abschirmung gegen elektromagnetische Störungen, die durch das umlaufende Schirmgeflecht erreicht wird. Der zweite Vorteil ist die hohe Bandbreite bei gleichzeitig geringer Dämpfung, wodurch Signale über deutlich größere Entfernungen übertragen werden können als mit Twisted Pair. Hinzu kommt die robuste mechanische Bauweise, die das Kabel unempfindlich gegen äußere Einflüsse macht","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b22f1.png"},{"id":"b22f5","block":"Koaxialkabel","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Einsatzgebiete den Kabeltypen zu:","begriffe":["Koaxialkabel","Twisted Pair Kabel","Glasfaserkabel"],"beschreibungen":[{"key":"a","text":"Hohe Bandbreite und robuste Bauweise, oft für TV- und Breitbandnetzwerke"},{"key":"b","text":"Verwendung in lokalen Netzwerken aufgrund einfacher Installation und Flexibilität"},{"key":"c","text":"Optimiert für extrem hohe Geschwindigkeiten und große Entfernungen"}],"loesung_paare":{"Koaxialkabel":"a","Twisted Pair Kabel":"b","Glasfaserkabel":"c"},"loesung":"Koaxialkabel = a; Twisted Pair Kabel = b; Glasfaserkabel = c","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b23f1","block":"Lichtwellenleiterkabel (Glasfaserkabel)","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Glasfaserkabelart ist optimal für Langstreckenübertragungen?","optionen":[{"key":"A","text":"Multi-Mode-Faser (MMF)"},{"key":"B","text":"Single-Mode-Faser (SMF)"},{"key":"C","text":"Stufenindex-Faser"},{"key":"D","text":"Gradientindex-Faser"}],"loesung_key":"B","loesung":"Single-Mode-Faser (SMF)","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b23f1.png"},{"id":"b23f2","block":"Lichtwellenleiterkabel (Glasfaserkabel)","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Glasfaserkabel sind immun gegen elektromagnetische Interferenzen","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b23f3","block":"Lichtwellenleiterkabel (Glasfaserkabel)","typ":"lueckentext","typ_label":"Lückentext","frage":"__________ Glasfaserkabel haben einen kleinen Kern, der nur einen Lichtmodus transportiert und hohe Datenraten über große Entfernungen ermöglicht","loesung":"Single-Mode","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","alternativen":["Monomode","SMF"],"bild":"b23f1.png"},{"id":"b23f4","block":"Lichtwellenleiterkabel (Glasfaserkabel)","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Hauptunterschied zwischen Single-Mode und Multi-Mode Fasern?","loesung":"Der Hauptunterschied liegt im Durchmesser des Faserkerns und damit in der Anzahl der Lichtmoden. Die Single-Mode-Faser hat einen sehr kleinen Kern von etwa 9 Mikrometern, in dem sich das Licht nur in einem Modus ausbreitet. Dadurch entstehen keine Laufzeitunterschiede, und es sind sehr große Reichweiten möglich. Die Multi-Mode-Faser hat einen Kern von 50 oder 62,5 Mikrometern, in dem sich das Licht auf mehreren Wegen ausbreitet. Die daraus entstehende Modendispersion begrenzt die Reichweite auf einige hundert Meter. Dafür ist die Multi-Mode-Faser günstiger und einfacher zu konfektionieren, weshalb sie innerhalb von Gebäuden und in Rechenzentren eingesetzt wird","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch"},{"id":"b23f5","block":"Lichtwellenleiterkabel (Glasfaserkabel)","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Glasfaserkabel den jeweiligen Einsatzgebieten zu:","begriffe":["Single-Mode-Faser","Multi-Mode-Faser"],"beschreibungen":[{"key":"a","text":"Weit verbreitet in lokalen Netzwerken und Rechenzentren, mit begrenzter Reichweite"},{"key":"b","text":"Ideal für lange Strecken wie in Weitverkehrsnetzen"}],"loesung_paare":{"Single-Mode-Faser":"b","Multi-Mode-Faser":"a"},"loesung":"Single-Mode-Faser = b; Multi-Mode-Faser = a","kapitel":12,"kapitel_name":"Netzwerkkabel","quelle":"buch","bild":"b23f1.png"},{"id":"b24f1","block":"Ergonomie am Arbeitsplatz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Was ist das Hauptziel der Ergonomie am Arbeitsplatz?","optionen":[{"key":"A","text":"Erhöhung der Arbeitszeit"},{"key":"B","text":"Optimierung der Arbeitsumgebung zur Förderung der Gesundheit und des Wohlbefindens"},{"key":"C","text":"Erhöhung der Büroausstattungskosten"},{"key":"D","text":"Einführung neuer Technologien"}],"loesung_key":"B","loesung":"Optimierung der Arbeitsumgebung zur Förderung der Gesundheit und des Wohlbefindens","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","bild":"b24f1.png"},{"id":"b24f2","block":"Ergonomie am Arbeitsplatz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ergonomie befasst sich ausschließlich mit der Gestaltung von Büromöbeln","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b24f3","block":"Ergonomie am Arbeitsplatz","typ":"lueckentext","typ_label":"Lückentext","frage":"Ergonomie zielt darauf ab, den Arbeitsplatz so zu gestalten, dass er den natürlichen __________ und __________ des Körpers entspricht","loesung":"Bewegungen und Haltungen","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","alternativen":["Bewegungen und Haltungen","Maßen und Bewegungsabläufen"]},{"id":"b24f4","block":"Ergonomie am Arbeitsplatz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche zwei gesundheitlichen Vorteile bietet ein ergonomisch gestalteter Arbeitsplatz?","loesung":"Der erste Vorteil ist die Vorbeugung von Muskel-Skelett-Erkrankungen. Eine korrekte Sitzhaltung, richtig eingestellte Tisch- und Monitorhöhe und wechselnde Körperhaltungen verringern Rücken- und Nackenbeschwerden sowie Belastungen wie das Karpaltunnelsyndrom. Der zweite Vorteil ist die Entlastung der Augen. Ausreichende und blendfreie Beleuchtung, ein passender Sehabstand und regelmäßige Blickwechsel in die Ferne reduzieren Ermüdung, Kopfschmerzen und trockene Augen. Als Folge sinken Fehlzeiten, und Konzentration sowie Leistungsfähigkeit bleiben länger erhalten","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","bild":"b24f1.png"},{"id":"b24f5","block":"Ergonomie am Arbeitsplatz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie den ergonomischen Prinzipien die zugehörigen Ziele zu:","begriffe":["Reduktion von körperlichen Belastungen","Förderung der Gesundheit","Steigerung der Produktivität"],"beschreibungen":[{"key":"a","text":"Vermeidung von Überlastungen durch falsche Haltungen oder sich wiederholende Bewegungen"},{"key":"b","text":"Prävention von Muskel-Skelett-Erkrankungen wie Rückenschmerzen und Karpaltunnelsyndrom"},{"key":"c","text":"Erhöhung der Effizienz und Zufriedenheit der Mitarbeiter"}],"loesung_paare":{"Reduktion von körperlichen Belastungen":"a","Förderung der Gesundheit":"b","Steigerung der Produktivität":"c"},"loesung":"Reduktion von körperlichen Belastungen = a; Förderung der Gesundheit = b; Steigerung der Produktivität = c","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b25f1","block":"Der ergonomische Arbeitsplatz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Was ist die ideale Tischhöhe bei einem ergonomischen Arbeitsplatz?","optionen":[{"key":"A","text":"80 cm"},{"key":"B","text":"Eine Höhe, die den Unterarmen einen 90-Grad-Winkel zum Körper ermöglicht"},{"key":"C","text":"70 cm"},{"key":"D","text":"Eine Höhe, die die Füße baumeln lässt"}],"loesung_key":"B","loesung":"Eine Höhe, die den Unterarmen einen 90-Grad-Winkel zum Körper ermöglicht","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","bild":"b25f1.png"},{"id":"b25f2","block":"Der ergonomische Arbeitsplatz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein ergonomischer Stuhl sollte immer Armlehnen haben, die in einer festen Position verbleiben","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b25f3","block":"Der ergonomische Arbeitsplatz","typ":"lueckentext","typ_label":"Lückentext","frage":"Die __________ des Monitors sollte sich auf Augenhöhe befinden, um Nackenbelastungen zu vermeiden","loesung":"Oberkante","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","alternativen":["obere Bildschirmkante"],"bild":"b25f3.png"},{"id":"b25f4","block":"Der ergonomische Arbeitsplatz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Merkmale eines ergonomischen Stuhls, die zur Unterstützung der Körperhaltung beitragen","loesung":"Ein erstes Merkmal ist eine Rückenlehne mit Lendenwirbelstütze, die die natürliche S-Form der Wirbelsäule unterstützt und ein Zusammensacken im unteren Rücken verhindert. Ein zweites Merkmal ist die Höhenverstellbarkeit der Sitzfläche, damit Ober- und Unterschenkel einen Winkel von etwa 90 Grad bilden und die Füße flach auf dem Boden stehen. Ergänzend tragen eine dynamische Rückenlehne, die Bewegung beim Sitzen zulässt, und verstellbare Armlehnen zur Entlastung bei","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","bild":"b25f4.png"},{"id":"b25f5","block":"Der ergonomische Arbeitsplatz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die ergonomischen Arbeitsplatzkomponenten den Beschreibungen zu:","begriffe":["Stuhl","Tisch","Monitor"],"beschreibungen":[{"key":"a","text":"Sollte höhenverstellbar sein, um sowohl im Sitzen als auch im Stehen arbeiten zu können"},{"key":"b","text":"Muss die Lendenwirbelsäule unterstützen und sollte mit Rollen für Beweglichkeit ausgestattet sein"},{"key":"c","text":"Sollte leicht nach hinten geneigt und in einer Armlänge Entfernung aufgestellt werden"}],"loesung_paare":{"Stuhl":"b","Tisch":"a","Monitor":"c"},"loesung":"Stuhl = b; Tisch = a; Monitor = c","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b26f1","block":"Beleuchtung und Raumklima","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Lichtquelle ist am besten für die Ergonomie am Arbeitsplatz geeignet?","optionen":[{"key":"A","text":"Künstliches Licht"},{"key":"B","text":"Kerzenlicht"},{"key":"C","text":"Natürliches Tageslicht"},{"key":"D","text":"Neonröhren ohne Abdeckung"}],"loesung_key":"C","loesung":"Natürliches Tageslicht","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b26f2","block":"Beleuchtung und Raumklima","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine relative Luftfeuchtigkeit von 20-30 % ist ideal für ein angenehmes Raumklima","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b26f3","block":"Beleuchtung und Raumklima","typ":"lueckentext","typ_label":"Lückentext","frage":"Die ideale Raumtemperatur am Arbeitsplatz sollte zwischen __________ Grad Celsius liegen","loesung":"20 und 22","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","alternativen":["20 bis 22"]},{"id":"b26f4","block":"Beleuchtung und Raumklima","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche zwei Maßnahmen können helfen, Blendungen am Arbeitsplatz zu vermeiden?","loesung":"Eine erste Maßnahme ist die richtige Ausrichtung des Bildschirms. Der Monitor sollte seitlich zum Fenster stehen, also weder direkt davor noch mit dem Rücken zum Fenster, damit weder direktes Licht in die Augen fällt noch Spiegelungen auf dem Bildschirm entstehen. Eine zweite Maßnahme ist die Regulierung des einfallenden Lichts durch Jalousien, Rollos oder Vorhänge. Ergänzend helfen entspiegelte Bildschirmoberflächen, blendfreie Leuchten mit Abdeckung und indirekte Beleuchtung","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b26f5","block":"Beleuchtung und Raumklima","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Raumklimafaktoren den empfohlenen Bedingungen zu:","begriffe":["Frischluftzufuhr","Temperatur","Luftfeuchtigkeit"],"beschreibungen":[{"key":"a","text":"Regelmäßiges Lüften oder Einsatz von Luftreinigern, um Sauerstoffkonzentration zu erhalten"},{"key":"b","text":"20-22 Grad Celsius für eine angenehme Arbeitsatmosphäre"},{"key":"c","text":"40-60 % zur Vermeidung von Reizungen der Augen und Atemwege"}],"loesung_paare":{"Frischluftzufuhr":"a","Temperatur":"b","Luftfeuchtigkeit":"c"},"loesung":"Frischluftzufuhr = a; Temperatur = b; Luftfeuchtigkeit = c","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b27f1","block":"Sicherheit und Prävention","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Institution in Österreich ist für die Umsetzung und Überwachung von Sicherheitsstandards am Arbeitsplatz zuständig?","optionen":[{"key":"A","text":"WHO"},{"key":"B","text":"AUVA (Allgemeine Unfallversicherungsanstalt)"},{"key":"C","text":"ÖAMTC"},{"key":"D","text":"EU-Kommission"}],"loesung_key":"B","loesung":"AUVA (Allgemeine Unfallversicherungsanstalt)","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b27f2","block":"Sicherheit und Prävention","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Regelmäßige Pausen sind nur dann notwendig, wenn man körperlich arbeitet","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b27f3","block":"Sicherheit und Prävention","typ":"lueckentext","typ_label":"Lückentext","frage":"Zur Prävention von Muskel-Skelett-Erkrankungen sollten Büroarbeiter regelmäßige __________ und __________ einlegen","loesung":"Pausen und Bewegungsübungen","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch","alternativen":["Pausen und Dehnübungen","Pausen und Haltungswechsel"]},{"id":"b27f4","block":"Sicherheit und Prävention","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Maßnahmen können helfen, Muskelverspannungen bei Büroarbeit zu reduzieren?","loesung":"Wirksam ist zunächst der regelmäßige Wechsel der Körperhaltung, etwa durch einen höhenverstellbaren Tisch, der abwechselnd sitzendes und stehendes Arbeiten erlaubt. Ergänzend sollten alle 30 bis 60 Minuten kurze Pausen mit Dehn- und Lockerungsübungen für Nacken, Schultern und Rücken eingelegt werden. Wichtig ist außerdem die korrekte Einstellung des Arbeitsplatzes, also Stuhlhöhe, Tischhöhe und Monitorposition, damit keine dauerhafte Zwangshaltung entsteht. Auch das bewusste Vermeiden hochgezogener Schultern bei der Maus- und Tastaturnutzung sowie ausreichend Bewegung außerhalb der Arbeitszeit tragen bei","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b27f5","block":"Sicherheit und Prävention","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie den Präventionsmaßnahmen die zugehörigen Aktivitäten zu:","begriffe":["Regelmäßige Pausen","Bewegung und Dehnung","Wechselnde Haltungen"],"beschreibungen":[{"key":"a","text":"Hilft, Verspannungen zu lösen und die Muskulatur zu entspannen"},{"key":"b","text":"Fördert die Durchblutung und reduziert einseitige Belastungen"},{"key":"c","text":"Sollten alle 30-60 Minuten erfolgen, um die Augen zu entlasten und den Körper zu entspannen"}],"loesung_paare":{"Regelmäßige Pausen":"c","Bewegung und Dehnung":"a","Wechselnde Haltungen":"b"},"loesung":"Regelmäßige Pausen = c; Bewegung und Dehnung = a; Wechselnde Haltungen = b","kapitel":14,"kapitel_name":"Ergonomie","quelle":"buch"},{"id":"b28f1","block":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Aussage beschreibt Künstliche Intelligenz (KI) am besten?","optionen":[{"key":"A","text":"KI führt nur feste, vom Entwickler programmierte Regeln aus"},{"key":"B","text":"KI bezeichnet Systeme, die Aufgaben lösen, die normalerweise menschliche Intelligenz erfordern"},{"key":"C","text":"KI ist ausschließlich für Robotik zuständig"},{"key":"D","text":"KI ist ein anderes Wort für Datenbanken"}],"loesung_key":"B","loesung":"KI bezeichnet Systeme, die Aufgaben lösen, die normalerweise menschliche Intelligenz erfordern","kapitel":15,"kapitel_name":"Künstliche Intelligenz","quelle":"buch"},{"id":"b28f2","block":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Starke (General) KI ist heutzutage weit verbreitet","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","kapitel":15,"kapitel_name":"Künstliche Intelligenz","quelle":"buch"},{"id":"b28f3","block":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Machine Learning ist ein Teilgebiet der KI, bei dem Systeme aus __________________________ lernen und Muster erkennen","loesung":"Daten","kapitel":15,"kapitel_name":"Künstliche Intelligenz","quelle":"buch","alternativen":["Erfahrung","Trainingsdaten"]},{"id":"b28f4","block":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Beschreiben Sie kurz den Unterschied zwischen überwachten und unüberwachten Lernen","loesung":"Beim überwachten Lernen liegen die Trainingsdaten mit bekannten Zielwerten vor, sind also gelabelt. Das Modell lernt die Zuordnung von Eingabe zu Zielwert und kann diese anschließend auf neue Daten anwenden. Typische Anwendungen sind Klassifikation, etwa die Einteilung von E-Mails in Spam und Nicht-Spam, sowie Regression zur Vorhersage von Zahlenwerten. Beim unüberwachten Lernen fehlen diese Zielwerte. Das System sucht selbstständig nach Strukturen in den Daten und bildet daraus Gruppen oder reduziert die Dimensionen. Typische Anwendungen sind Clustering, etwa die Segmentierung von Kunden, und die Erkennung von Anomalien","kapitel":15,"kapitel_name":"Künstliche Intelligenz","quelle":"buch"},{"id":"b28f5","block":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die ML-Arten den passenden Beschreibungen zu:","begriffe":["Überwachtes Lernen","Unüberwachtes Lernen","Reinforcement Learning"],"beschreibungen":[{"key":"a","text":"Lernen ohne Zielwerte, das System erkennt Muster und Gruppen selbstständig"},{"key":"b","text":"Lernen durch Belohnung und Strafe (\"Trial and Error\")"},{"key":"c","text":"Lernen mit Eingabedaten und bekanntem Zielwert"}],"loesung_paare":{"Überwachtes Lernen":"c","Unüberwachtes Lernen":"a","Reinforcement Learning":"b"},"loesung":"Überwachtes Lernen = c; Unüberwachtes Lernen = a; Reinforcement Learning = b","kapitel":15,"kapitel_name":"Künstliche Intelligenz","quelle":"buch"},{"id":"n01f001","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Laserwellenlänge verwendet eine Blu-ray Disc?","optionen":[{"key":"A","text":"405 nm"},{"key":"B","text":"780 nm"},{"key":"C","text":"650 nm"},{"key":"D","text":"1024 nm"}],"loesung_key":"A","loesung":"405 nm","quelle":"extra"},{"id":"n01f002","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie viele Partitionen kann ein Master Boot Record (MBR) maximal verwalten?","optionen":[{"key":"A","text":"Zwei primäre Partitionen"},{"key":"B","text":"Vier primäre Partitionen oder drei primäre und eine erweiterte Partition"},{"key":"C","text":"Acht primäre Partitionen"},{"key":"D","text":"Eine unbegrenzte Anzahl an Partitionen"}],"loesung_key":"B","loesung":"Vier primäre Partitionen oder drei primäre und eine erweiterte Partition","quelle":"extra"},{"id":"n01f003","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Aussage beschreibt das Kodierungsformat UTF-8 korrekt?","optionen":[{"key":"A","text":"Es verwendet immer genau 2 Byte pro Zeichen"},{"key":"B","text":"Es verwendet immer genau 4 Byte pro Zeichen"},{"key":"C","text":"Es verwendet 1 bis 4 Byte pro Zeichen und ist zu ASCII kompatibel"},{"key":"D","text":"Es kann ausschließlich westeuropäische Sonderzeichen darstellen"}],"loesung_key":"C","loesung":"Es verwendet 1 bis 4 Byte pro Zeichen und ist zu ASCII kompatibel","quelle":"extra"},{"id":"n01f004","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Sicherheitsanforderung ist bei Windows 11 verpflichtend, bei Windows 7 aber nicht erforderlich?","optionen":[{"key":"A","text":"BitLocker"},{"key":"B","text":"Windows Defender"},{"key":"C","text":"Ein Benutzerkonto mit Administratorrechten"},{"key":"D","text":"TPM 2.0 und Secure Boot"}],"loesung_key":"D","loesung":"TPM 2.0 und Secure Boot","quelle":"extra"},{"id":"n01f005","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches der folgenden Werkzeuge ist ein Build Server?","optionen":[{"key":"A","text":"Jenkins"},{"key":"B","text":"Git"},{"key":"C","text":"Docker"},{"key":"D","text":"Maven"}],"loesung_key":"A","loesung":"Jenkins","quelle":"extra"},{"id":"n01f006","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wofür steht das V für Veracity bei den vier Vs von Big Data?","optionen":[{"key":"A","text":"Menge der Daten"},{"key":"B","text":"Geschwindigkeit der Daten"},{"key":"C","text":"Wahrhaftigkeit der Daten"},{"key":"D","text":"Vielfalt der Daten"}],"loesung_key":"C","loesung":"Wahrhaftigkeit der Daten","quelle":"extra"},{"id":"n01f007","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Der Power-On Self-Test (POST) kann erkannte Hardwareprobleme durch akustische Signale oder Fehlercodes melden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n01f008","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine Festplatte, die mit 500 GB nach SI-Einheiten beworben wird, bietet tatsächlich nur etwa 465 GiB nutzbaren Speicher.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n01f009","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"UEFI-basierte Systeme verwenden die EFI-System-Partition (ESP) und die GUID Partition Table (GPT).","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n01f010","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die ersten 32 Zeichen des ursprünglichen ASCII-Zeichensatzes sind druckbare Sonderzeichen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n01f011","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Beim Continuous Deployment sind vor der Bereitstellung in die Produktionsumgebung noch manuelle Freigabeschritte vorgesehen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n01f012","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei UEFI-basierten Systemen wird anstelle des MBR die __________ als Partitionstabelle verwendet.","loesung":"GUID Partition Table","alternativen":["GPT","GUID Partition Table (GPT)"],"quelle":"extra"},{"id":"n01f013","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein Halbbyte aus 4 Bit, das 16 verschiedene Werte darstellen kann, wird auch als __________ bezeichnet.","loesung":"Nibble","quelle":"extra"},{"id":"n01f014","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Zeichenkodierung __________ verfolgt das Ziel, fast alle Schriftzeichen weltweit einheitlich zu codieren.","loesung":"Unicode","quelle":"extra"},{"id":"n01f015","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ ist eine Software zur Erstellung, Verwaltung und Veröffentlichung von Inhalten auf Webseiten ohne tiefgehende Programmierkenntnisse.","loesung":"CMS","alternativen":["Content Management System","Content-Management-System"],"quelle":"extra"},{"id":"n01f016","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie den Unterschied zwischen IEC-Einheiten und SI-Einheiten bei Speichergrößen und nennen Sie ein Beispiel.","loesung":"IEC-Einheiten wie KiB, MiB oder GiB rechnen zur Basis 1024, SI-Einheiten wie kB, MB oder GB zur Basis 1000. IEC-Einheiten werden vor allem in technischen Dokumentationen und in der Softwareentwicklung verwendet, SI-Einheiten vor allem in Werbung und Verkauf, weil die Zahlen dort größer wirken. Eine Festplatte, die mit 500 GB beworben wird, bietet daher tatsächlich nur rund 465 GiB nutzbaren Speicher.","quelle":"extra"},{"id":"n01f017","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter Continuous Integration und welche Vorteile bringt sie?","loesung":"Bei Continuous Integration integrieren mehrere Entwickler ihre Codeänderungen häufig, oft mehrmals täglich, in ein gemeinsames Repository. Bei jeder Integration laufen automatisch ein Build und automatisierte Tests, die den neuen Code prüfen und sicherstellen, dass bestehende Funktionen weiter laufen. Vorteile sind die frühzeitige Fehlererkennung, weniger Integrationsprobleme und mehr Transparenz im Team.","quelle":"extra"},{"id":"n01f018","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie einen Vorteil und zwei Nachteile der hybriden App-Entwicklung.","loesung":"Der große Vorteil ist, dass man mit einer einzigen Codebasis beide Plattformen, also iOS und Android, bedienen kann. Nachteilig ist, dass plattformspezifische Anforderungen wie die Sensorik von Mobiltelefonen oft nicht in einer gemeinsamen Codebasis abbildbar sind, was zu stärker fragmentierten Projekten und schwierigerer Wartung führt. Außerdem unterstützt nicht jede hybride Entwicklungsumgebung die nativen Controls der Zielsysteme, wodurch auch das Frontend-Design uneinheitlich werden kann.","quelle":"extra"},{"id":"n01f019","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist ein Version Control System und welche Aufgaben erfüllt es?","loesung":"Ein Version Control System, auch Versionskontrolle genannt, ist ein System zur Verwaltung von Änderungen an Dokumenten, Programmen und anderen Informationssammlungen. Es ermöglicht das Nachverfolgen von Änderungen, das Verzweigen und Zusammenführen von Versionen sowie das Wiederherstellen früherer Versionen. Bekannte Tools sind Git, Subversion und Mercurial.","quelle":"extra"},{"id":"n01f020","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Unicode-Formate ihrer Kodierungslänge zu:","begriffe":["UTF-8","UTF-16","UTF-32"],"beschreibungen":[{"key":"a","text":"Variable Länge von 1 bis 4 Byte pro Zeichen, kompatibel mit ASCII"},{"key":"b","text":"Benötigt 2 oder 4 Byte pro Zeichen"},{"key":"c","text":"Benötigt immer 4 Byte pro Zeichen, alle Zeichen sind gleich lang kodiert"}],"loesung_paare":{"UTF-8":"a","UTF-16":"b","UTF-32":"c"},"loesung":"UTF-8 = a; UTF-16 = b; UTF-32 = c","quelle":"extra"},{"id":"n01f021","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Stufen der Industrie-Evolution ihrem Kennzeichen zu:","begriffe":["Industrie 1.0","Industrie 2.0","Industrie 3.0","Industrie 4.0"],"beschreibungen":[{"key":"a","text":"Mechanisierung"},{"key":"b","text":"Elektrifizierung"},{"key":"c","text":"Automatisierung"},{"key":"d","text":"Digitalisierung und Vernetzung der Produktionsprozesse"}],"loesung_paare":{"Industrie 1.0":"a","Industrie 2.0":"b","Industrie 3.0":"c","Industrie 4.0":"d"},"loesung":"Industrie 1.0 = a; Industrie 2.0 = b; Industrie 3.0 = c; Industrie 4.0 = d","quelle":"extra"},{"id":"n01f022","kapitel":1,"kapitel_name":"Allgemeines zu IT","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Fachbegriffe ihrer Bedeutung zu:","begriffe":["Corporate Identity","Corporate Design","CMS","Version Control System"],"beschreibungen":[{"key":"a","text":"Gesamtheit der Merkmale, die ein Unternehmen kennzeichnen und von anderen unterscheiden"},{"key":"b","text":"Visueller Teil der Corporate Identity, also Logo, Farben, Typografie und Designrichtlinien"},{"key":"c","text":"Software zur Erstellung und Veröffentlichung von Webinhalten ohne tiefe Programmierkenntnisse"},{"key":"d","text":"System zur Verwaltung von Änderungen, Verzweigungen und früheren Versionen"}],"loesung_paare":{"Corporate Identity":"a","Corporate Design":"b","CMS":"c","Version Control System":"d"},"loesung":"Corporate Identity = a; Corporate Design = b; CMS = c; Version Control System = d","quelle":"extra"},{"id":"n02f001","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Zugriffsmodifikator in C# erlaubt den Zugriff innerhalb der eigenen Klasse und zusätzlich in abgeleiteten Klassen?","optionen":[{"key":"A","text":"private"},{"key":"B","text":"protected"},{"key":"C","text":"internal"},{"key":"D","text":"public"}],"loesung_key":"B","loesung":"protected","quelle":"extra"},{"id":"n02f002","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wo werden in C# Objekte, die aus einer Klasse erzeugt wurden, abgelegt?","optionen":[{"key":"A","text":"Auf dem Stack"},{"key":"B","text":"Im Prozessor-Cache"},{"key":"C","text":"Auf dem Heap"},{"key":"D","text":"In der Auslagerungsdatei"}],"loesung_key":"C","loesung":"Auf dem Heap","quelle":"extra"},{"id":"n02f003","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Schlüsselwort kennzeichnet in C# eine Methode, die in einer abgeleiteten Klasse überschrieben werden muss?","optionen":[{"key":"A","text":"virtual"},{"key":"B","text":"sealed"},{"key":"C","text":"internal"},{"key":"D","text":"abstract"}],"loesung_key":"D","loesung":"abstract","quelle":"extra"},{"id":"n02f004","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Collection in C# ist ungeordnet und verhindert doppelte Elemente?","optionen":[{"key":"A","text":"HashSet"},{"key":"B","text":"List"},{"key":"C","text":"Dictionary"},{"key":"D","text":"Array"}],"loesung_key":"A","loesung":"HashSet","quelle":"extra"},{"id":"n02f005","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Datentyp in C# ist wegen seiner hohen Präzision besonders für Finanz- und Währungsberechnungen geeignet?","optionen":[{"key":"A","text":"float"},{"key":"B","text":"double"},{"key":"C","text":"decimal"},{"key":"D","text":"long"}],"loesung_key":"C","loesung":"decimal","quelle":"extra"},{"id":"n02f006","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Übersetzungsmechanismus übersetzt den Code erst während der Laufzeit und wird von C# mit .NET verwendet?","optionen":[{"key":"A","text":"Interpreter"},{"key":"B","text":"Assembler"},{"key":"C","text":"AOT-Compiler"},{"key":"D","text":"JIT-Compiler"}],"loesung_key":"D","loesung":"JIT-Compiler","quelle":"extra"},{"id":"n02f007","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Entwurfsmuster stellt sicher, dass von einer Klasse nur eine einzige Instanz existiert und bietet einen globalen Zugriffspunkt darauf?","optionen":[{"key":"A","text":"Singleton Pattern"},{"key":"B","text":"Factory Pattern"},{"key":"C","text":"Observer Pattern"},{"key":"D","text":"Interface Pattern"}],"loesung_key":"A","loesung":"Singleton Pattern","quelle":"extra"},{"id":"n02f008","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welchen Wertebereich hat der Datentyp byte in C#?","optionen":[{"key":"A","text":"-128 bis 127"},{"key":"B","text":"0 bis 255"},{"key":"C","text":"0 bis 65.535"},{"key":"D","text":"-32.768 bis 32.767"}],"loesung_key":"B","loesung":"0 bis 255","quelle":"extra"},{"id":"n02f009","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Structs in C# sind Werttypen, bei deren Zuweisung eine Kopie der Daten erstellt wird.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n02f010","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Structs in C# können von anderen Structs oder von Klassen erben.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n02f011","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Beim Call by Value wirken sich Änderungen innerhalb der Methode auf den ursprünglichen Wert aus.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n02f012","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine als abstract deklarierte Klasse kann nicht instanziiert werden und dient nur als Basis für andere Klassen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n02f013","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Der Stack hat eine feste Größe, die beim Starten des Programms definiert wird.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n02f014","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Dictionary in C# speichert eine ungeordnete Sammlung von Werten ohne zugehörige Schlüssel.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n02f015","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Jede rekursive Funktion benötigt mindestens eine Basisbedingung, die die Rekursion stoppt.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n02f016","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Interpreter übersetzt den gesamten Quellcode vor der Ausführung vollständig in Maschinensprache.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n02f017","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Der Bereich des Arbeitsspeichers, der lokale Variablen und Rücksprungadressen nach dem LIFO-Prinzip verwaltet, heißt __________.","loesung":"Stack","alternativen":["Stapelspeicher"],"quelle":"extra"},{"id":"n02f018","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine Warteschlange (Queue) arbeitet nach dem __________-Prinzip.","loesung":"FIFO","alternativen":["First In, First Out"],"quelle":"extra"},{"id":"n02f019","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine spezielle Methode, die beim Erstellen einer Instanz aufgerufen wird und das Objekt initialisiert, nennt man __________.","loesung":"Konstruktor","quelle":"extra"},{"id":"n02f020","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Das Schlüsselwort __________ verhindert in C#, dass eine Klasse weiter vererbt oder eine Methode überschrieben wird.","loesung":"sealed","quelle":"extra"},{"id":"n02f021","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Das Prinzip __________ fordert, Redundanzen durch die Wiederverwendung von Code zu vermeiden.","loesung":"DRY","alternativen":["Don't Repeat Yourself","Dont Repeat Yourself"],"quelle":"extra"},{"id":"n02f022","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Exceptions können im Code mittels __________-Anweisungen abgefangen werden.","loesung":"try/catch","alternativen":["try catch","try-catch"],"quelle":"extra"},{"id":"n02f023","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Das leichtgewichtige Datenformat __________ besteht aus Objekten mit Schlüssel-Wert-Paaren und aus Arrays und wird für den Datenaustausch zwischen Server und Webanwendung genutzt.","loesung":"JSON","alternativen":["Javascript Object Notation","JavaScript Object Notation"],"quelle":"extra"},{"id":"n02f024","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"lueckentext","typ_label":"Lückentext","frage":"Der menschenlesbare Code, der erst in Maschinencode umgewandelt werden muss, heißt __________.","loesung":"Quellcode","alternativen":["Sourcecode","Source Code"],"quelle":"extra"},{"id":"n02f025","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen und erklären Sie die vier Säulen der objektorientierten Programmierung.","loesung":"Die vier Säulen sind Vererbung, Kapselung, Polymorphismus und Abstraktion. Bei der Vererbung können Klassen von anderen Klassen erben, was Wiederverwendbarkeit und Erweiterbarkeit fördert. Die Kapselung verbirgt Daten und Methoden innerhalb einer Klasse, um den Zugriff von außen zu kontrollieren, und der Polymorphismus erlaubt unterschiedliche Implementierungen, die über dieselbe Schnittstelle aufgerufen werden. Die Abstraktion stellt komplexe Systeme über einfache Schnittstellen dar und zeigt nur die notwendigen Details.","quelle":"extra"},{"id":"n02f026","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie die wesentlichen Unterschiede zwischen Stack und Heap.","loesung":"Der Stack verwaltet Funktionsaufrufe und lokale Variablen nach dem LIFO-Prinzip, wird automatisch verwaltet, ist sehr schnell, hat aber eine feste, begrenzte Größe. Der Heap dient der dynamischen Speicherzuweisung zur Laufzeit, hat keine feste Größe und nimmt komplexe Datentypen wie Objekte und Arrays auf. Der Zugriff auf den Heap ist langsamer, weil die Verwaltung der Speicheradressen mehr Overhead verursacht. In C# und Java übernimmt die Garbage Collection das Freigeben nicht mehr benutzter Objekte.","quelle":"extra"},{"id":"n02f027","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist der Unterschied zwischen Call by Value und Call by Reference?","loesung":"Beim Call by Value wird der Methode eine Kopie des Wertes übergeben. Änderungen innerhalb der Methode wirken sich deshalb nicht auf den ursprünglichen Wert aus. Beim Call by Reference wird ein Verweis auf den Speicherort übergeben, daher verändern Zuweisungen innerhalb der Methode auch das ursprüngliche Argument.","quelle":"extra"},{"id":"n02f028","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie die vier Ursachen von Exceptions und erklären Sie sie kurz.","loesung":"Syntaxfehler sind Fehler im Code selbst. Logische Fehler entstehen durch eine falsche Logik im Programm. Laufzeitfehler treten während der Programmausführung auf, zum Beispiel eine Division durch Null. Zugriffsfehler entstehen beim Zugriff auf externe Ressourcen, etwa bei einem Netzwerkausfall, einer vollen Festplatte oder fehlenden Schreibrechten.","quelle":"extra"},{"id":"n02f029","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie den Unterschied zwischen Release, Deploy und Rollout.","loesung":"Ein Release ist der Akt, eine neue Version der Software zu erstellen, zum Beispiel das Pushen des aktuellen Codestandes auf den main-Branch. Ein Deploy ist das Übertragen und Installieren dieser Software in eine bestimmte Umgebung, typischerweise eine Test- oder Produktionsumgebung. Ein Rollout ist die geplante, oft schrittweise Verteilung der neuen Version an eine größere Benutzergruppe, etwa zuerst an 10 Prozent der Benutzer, um Probleme frühzeitig zu erkennen.","quelle":"extra"},{"id":"n02f030","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Warum können zwei Instanzen einer Person-Klasse mit identischen Eigenschaften in dasselbe HashSet eingefügt werden, und wie lässt sich das verhindern?","loesung":"Ein HashSet prüft die Gleichheit von Objekten standardmäßig über die Referenz, also über die Speicheradresse. Zwei verschiedene Instanzen liegen an unterschiedlichen Speicherorten und gelten deshalb als unterschiedlich, auch wenn ihre Eigenschaften identisch sind. Verhindern lässt sich das, indem man in der Person-Klasse die Methoden Equals() und GetHashCode() überschreibt, sodass die Gleichheit anhand der Eigenschaften, zum Beispiel des Namens, geprüft wird.","quelle":"extra"},{"id":"n02f031","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist eine integrierte Entwicklungsumgebung (IDE) und welche Hauptmerkmale bietet sie?","loesung":"Eine IDE ist eine Software, die mehrere Entwicklungswerkzeuge in einer einzigen Benutzeroberfläche vereint. Zu den Hauptmerkmalen zählen ein Code-Editor mit Syntax-Highlighting und Codevervollständigung, ein Compiler oder Interpreter, ein Debugger, Build-Automatisierung, die Anbindung an Versionskontrollsysteme, Projektmanagement und die Erweiterbarkeit über Plugins. Bekannte Beispiele sind Visual Studio und Eclipse.","quelle":"extra"},{"id":"n02f032","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter einer API und worin unterscheidet sie sich von einer ABI?","loesung":"Eine API (Application Programming Interface) ist eine Schnittstelle, über die verschiedene Softwarekomponenten miteinander kommunizieren. Sie definiert die Methoden und Datenformate, ohne dass die internen Implementierungsdetails der anderen Anwendung bekannt sein müssen. Eine ABI (Application Binary Interface) legt dagegen fest, wie Softwarekomponenten auf der Binär- oder Maschinenebene zusammenspielen, typischerweise zwischen Betriebssystem und Anwendung.","quelle":"extra"},{"id":"n02f033","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Zugriffsmodifikatoren in C# ihrer Wirkung zu:","begriffe":["public","private","protected","internal"],"beschreibungen":[{"key":"a","text":"Zugriff von überall im Code möglich"},{"key":"b","text":"Zugriff nur innerhalb der eigenen Klasse möglich"},{"key":"c","text":"Zugriff innerhalb der eigenen Klasse und in abgeleiteten Klassen möglich"},{"key":"d","text":"Zugriff nur für Code innerhalb derselben Assembly möglich"}],"loesung_paare":{"public":"a","private":"b","protected":"c","internal":"d"},"loesung":"public = a; private = b; protected = c; internal = d","quelle":"extra"},{"id":"n02f034","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Übersetzungsmechanismen ihrer Arbeitsweise zu:","begriffe":["Interpreter","Compiler","JIT-Compiler","AOT-Compiler"],"beschreibungen":[{"key":"a","text":"Übersetzt und führt den Code zeilenweise aus, zum Beispiel Python oder JavaScript"},{"key":"b","text":"Übersetzt den gesamten Code vor der Ausführung in Maschinensprache und erstellt eine ausführbare Datei, zum Beispiel C oder C++"},{"key":"c","text":"Übersetzt den Code während der Laufzeit, zum Beispiel C# mit .NET"},{"key":"d","text":"Übersetzt vor der Ausführung vollständig für eine bestimmte Zielplattform, zum Beispiel WebAssembly oder native mobile Apps"}],"loesung_paare":{"Interpreter":"a","Compiler":"b","JIT-Compiler":"c","AOT-Compiler":"d"},"loesung":"Interpreter = a; Compiler = b; JIT-Compiler = c; AOT-Compiler = d","quelle":"extra"},{"id":"n02f035","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Entwurfsmuster ihrer Beschreibung zu:","begriffe":["Factory Pattern","Singleton Pattern","Observer Pattern"],"beschreibungen":[{"key":"a","text":"Erzeugt Objekte über eine eigene Methode statt durch direkte Instanziierung"},{"key":"b","text":"Sorgt dafür, dass von einer Klasse nur eine einzige Instanz existiert"},{"key":"c","text":"Ein Subjekt verwaltet eine Liste von Beobachtern und benachrichtigt sie über Zustandsänderungen"}],"loesung_paare":{"Factory Pattern":"a","Singleton Pattern":"b","Observer Pattern":"c"},"loesung":"Factory Pattern = a; Singleton Pattern = b; Observer Pattern = c","quelle":"extra"},{"id":"n02f036","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Collection-Typen in C# ihren Eigenschaften zu:","begriffe":["List","HashSet","Dictionary"],"beschreibungen":[{"key":"a","text":"Geordnete Sammlung, in der die Reihenfolge der Elemente erhalten bleibt"},{"key":"b","text":"Ungeordnete Sammlung, die keine doppelten Elemente zulässt"},{"key":"c","text":"Assoziatives Array, das Schlüssel-Wert-Paare speichert"}],"loesung_paare":{"List":"a","HashSet":"b","Dictionary":"c"},"loesung":"List = a; HashSet = b; Dictionary = c","quelle":"extra"},{"id":"n02f037","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden SOLID-Prinzipien ihrer Aussage zu:","begriffe":["Single Responsibility Principle","Open/Closed Principle","Liskov Substitution Principle","Dependency Inversion Principle"],"beschreibungen":[{"key":"a","text":"Eine Klasse soll nur eine einzige Verantwortlichkeit und damit nur einen Grund zur Änderung haben"},{"key":"b","text":"Software-Entitäten sollen für Erweiterungen offen, für Änderungen aber geschlossen sein"},{"key":"c","text":"Objekte einer Basisklasse müssen durch Objekte einer abgeleiteten Klasse ersetzbar sein, ohne das Verhalten zu ändern"},{"key":"d","text":"Hochrangige Module sollen von Abstraktionen abhängen und nicht von konkreten Implementierungen"}],"loesung_paare":{"Single Responsibility Principle":"a","Open/Closed Principle":"b","Liskov Substitution Principle":"c","Dependency Inversion Principle":"d"},"loesung":"Single Responsibility Principle = a; Open/Closed Principle = b; Liskov Substitution Principle = c; Dependency Inversion Principle = d","quelle":"extra"},{"id":"n02f038","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Fehlerarten ihrer Ursache zu:","begriffe":["Syntaxfehler","Logischer Fehler","Laufzeitfehler","Zugriffsfehler"],"beschreibungen":[{"key":"a","text":"Verstoß gegen die Sprachregeln, verhindert die Kompilierung"},{"key":"b","text":"Das Programm läuft, liefert aber wegen falscher Logik ein falsches Ergebnis"},{"key":"c","text":"Tritt während der Programmausführung auf, zum Beispiel eine Division durch Null"},{"key":"d","text":"Zugriff auf eine externe Ressource scheitert, etwa bei Netzwerkausfall oder fehlenden Schreibrechten"}],"loesung_paare":{"Syntaxfehler":"a","Logischer Fehler":"b","Laufzeitfehler":"c","Zugriffsfehler":"d"},"loesung":"Syntaxfehler = a; Logischer Fehler = b; Laufzeitfehler = c; Zugriffsfehler = d","quelle":"extra"},{"id":"n02f039","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Programmierparadigmen ihrer Beschreibung zu:","begriffe":["Objektorientiert","Prozedural","Ereignisgesteuert","Deklarativ"],"beschreibungen":[{"key":"a","text":"Strukturierung des Programms durch Objekte und Klassen"},{"key":"b","text":"Strukturierung des Programms durch Prozeduren oder Funktionen"},{"key":"c","text":"Der Ablauf reagiert auf Ereignisse oder Benutzerinteraktionen"},{"key":"d","text":"Beschreibt das Was statt des Wie, zum Beispiel SQL oder HTML"}],"loesung_paare":{"Objektorientiert":"a","Prozedural":"b","Ereignisgesteuert":"c","Deklarativ":"d"},"loesung":"Objektorientiert = a; Prozedural = b; Ereignisgesteuert = c; Deklarativ = d","quelle":"extra"},{"id":"n02f040","kapitel":2,"kapitel_name":"Grundlagen der Programmierung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Operatorengruppen ihren Beispielen zu:","begriffe":["Zuweisungsoperatoren","Arithmetische Operatoren","Vergleichsoperatoren","Logische Operatoren"],"beschreibungen":[{"key":"a","text":"=, +=, -="},{"key":"b","text":"+, -, *, /, %"},{"key":"c","text":"==, <, >, <=, >=, !="},{"key":"d","text":"&& (AND), || (OR), ! (NOT), ^ (XOR)"}],"loesung_paare":{"Zuweisungsoperatoren":"a","Arithmetische Operatoren":"b","Vergleichsoperatoren":"c","Logische Operatoren":"d"},"loesung":"Zuweisungsoperatoren = a; Arithmetische Operatoren = b; Vergleichsoperatoren = c; Logische Operatoren = d","quelle":"extra"},{"id":"n03f001","kapitel":3,"kapitel_name":"Testing","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Was wird bei einem Unit Test geprüft?","optionen":[{"key":"A","text":"Eine kleine Einheit wie eine einzelne Funktion oder Methode, isoliert vom Rest"},{"key":"B","text":"Die Zusammenarbeit mehrerer Module über ihre Schnittstellen"},{"key":"C","text":"Das vollständige, integrierte System gegen alle Anforderungen"},{"key":"D","text":"Die Akzeptanz der Software durch den Endbenutzer"}],"loesung_key":"A","loesung":"Eine kleine Einheit wie eine einzelne Funktion oder Methode, isoliert vom Rest","quelle":"extra"},{"id":"n03f002","kapitel":3,"kapitel_name":"Testing","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Teststufe prüft gezielt die Schnittstellen und Interaktionen zwischen mehreren Komponenten?","optionen":[{"key":"A","text":"Unit Test"},{"key":"B","text":"Integrationstest"},{"key":"C","text":"Abnahmetest"},{"key":"D","text":"Schreibtischtest"}],"loesung_key":"B","loesung":"Integrationstest","quelle":"extra"},{"id":"n03f003","kapitel":3,"kapitel_name":"Testing","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Von wem werden Abnahmetests (User Acceptance Testing) üblicherweise durchgeführt?","optionen":[{"key":"A","text":"Vom Entwicklungsteam während der Implementierung"},{"key":"B","text":"Automatisiert durch ein Mocking Framework"},{"key":"C","text":"Vom Kunden oder vom Endbenutzer"},{"key":"D","text":"Vom Datenbankadministrator im Rahmen der Wartung"}],"loesung_key":"C","loesung":"Vom Kunden oder vom Endbenutzer","quelle":"extra"},{"id":"n03f004","kapitel":3,"kapitel_name":"Testing","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Prinzip von Unit Tests fordert, dass ein Test unabhängig von der Ausführungsreihenfolge und vom Zustand der Umgebung dasselbe Ergebnis liefert?","optionen":[{"key":"A","text":"Isoliertheit"},{"key":"B","text":"Wartbarkeit"},{"key":"C","text":"Skalierbarkeit"},{"key":"D","text":"Reproduzierbarkeit"}],"loesung_key":"D","loesung":"Reproduzierbarkeit","quelle":"extra"},{"id":"n03f005","kapitel":3,"kapitel_name":"Testing","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Warum zählt der Schreibtischtest zur statischen Analyse?","optionen":[{"key":"A","text":"Weil der Code dabei nicht ausgeführt, sondern manuell durchgegangen wird"},{"key":"B","text":"Weil dabei nur die Benutzeroberfläche und nicht der Code geprüft wird"},{"key":"C","text":"Weil dabei ausschließlich automatisierte Testwerkzeuge zum Einsatz kommen"},{"key":"D","text":"Weil dabei die Laufzeit des Programms gemessen wird"}],"loesung_key":"A","loesung":"Weil der Code dabei nicht ausgeführt, sondern manuell durchgegangen wird","quelle":"extra"},{"id":"n03f006","kapitel":3,"kapitel_name":"Testing","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Unit Tests sollen keine Abhängigkeiten von externen Ressourcen wie Datenbanken, Dateisystemen oder Netzwerken haben.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n03f007","kapitel":3,"kapitel_name":"Testing","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Systemtests decken ausschließlich funktionale Anforderungen ab.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n03f008","kapitel":3,"kapitel_name":"Testing","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Integrationstests dürfen keine externen Abhängigkeiten wie Datenbanken oder Webservices verwenden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n03f009","kapitel":3,"kapitel_name":"Testing","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Vorteil von Code-Reviews ist der Wissenstransfer innerhalb des Teams.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n03f010","kapitel":3,"kapitel_name":"Testing","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Abkürzung UAT steht für User __________ Testing.","loesung":"Acceptance","quelle":"extra"},{"id":"n03f011","kapitel":3,"kapitel_name":"Testing","typ":"lueckentext","typ_label":"Lückentext","frage":"Das Prinzip der __________ verlangt, dass Unit Tests keine Abhängigkeiten von Datenbanken, Dateisystemen oder Netzwerken haben.","loesung":"Isoliertheit","alternativen":["Isolation","Isoliertheit"],"quelle":"extra"},{"id":"n03f012","kapitel":3,"kapitel_name":"Testing","typ":"lueckentext","typ_label":"Lückentext","frage":"Whitebox Tests konzentrieren sich auf die Code-Struktur, die __________ und die internen Zustände eines Programms.","loesung":"Logikpfade","alternativen":["Logikpfade","Logikpfad"],"quelle":"extra"},{"id":"n03f013","kapitel":3,"kapitel_name":"Testing","typ":"lueckentext","typ_label":"Lückentext","frage":"Der Schreibtischtest wird im Englischen auch als __________ bezeichnet.","loesung":"Dry Run","alternativen":["Dry Run","Dry-Run","Dryrun"],"quelle":"extra"},{"id":"n03f014","kapitel":3,"kapitel_name":"Testing","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welchen Zweck verfolgen Code-Reviews und welche Vorteile bringen sie? Nennen Sie mindestens zwei Vorteile.","loesung":"Code-Reviews dienen der Verbesserung der Qualität und der Wartbarkeit von Code. Dabei sehen sich Entwicklerinnen und Entwickler den Quellcode gegenseitig an. Vorteile sind unter anderem die Förderung von Best Practices und Konsistenz im Code sowie der Wissenstransfer innerhalb des Teams. Außerdem steigt die Codequalität, Bugs werden reduziert und die Teamkommunikation verbessert sich.","quelle":"extra"},{"id":"n03f015","kapitel":3,"kapitel_name":"Testing","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich Unit Tests und Integrationstests im Umgang mit externen Abhängigkeiten?","loesung":"Unit Tests testen eine kleine Einheit isoliert und sollen keine Abhängigkeiten von externen Ressourcen wie Datenbanken, Dateisystemen oder Netzwerken haben. Solche Abhängigkeiten werden daher durch Mocks ersetzt. Integrationstests prüfen dagegen das Zusammenspiel mehrerer Komponenten und dürfen externe Abhängigkeiten wie Datenbanken oder Webservices tatsächlich nutzen.","quelle":"extra"},{"id":"n03f016","kapitel":3,"kapitel_name":"Testing","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welchen Zweck haben Abnahmetests und worauf liegt dabei der Fokus?","loesung":"Abnahmetests sollen sicherstellen, dass das System die Geschäftsanforderungen und Spezifikationen erfüllt und vom Endbenutzer akzeptiert werden kann. Sie werden oft vom Kunden oder vom Endbenutzer selbst durchgeführt. Der Fokus liegt auf der Erfüllung der funktionalen Anforderungen und auf der Benutzerfreundlichkeit.","quelle":"extra"},{"id":"n03f017","kapitel":3,"kapitel_name":"Testing","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Methoden und Werkzeuge der Qualitätssicherung ihrer Beschreibung zu:","begriffe":["Mocking Framework","Code-Review","Schreibtischtest"],"beschreibungen":[{"key":"a","text":"Ersetzt externe Abhängigkeiten in Unit Tests durch sogenannte Mocks und isoliert sie dadurch"},{"key":"b","text":"Gegenseitige Durchsicht des Quellcodes zur Verbesserung von Qualität, Wartbarkeit und Teamkommunikation"},{"key":"c","text":"Manuelles Durchgehen des Codes durch die Entwicklerin oder den Entwickler, ohne den Code auszuführen"}],"loesung_paare":{"Mocking Framework":"a","Code-Review":"b","Schreibtischtest":"c"},"loesung":"Mocking Framework = a; Code-Review = b; Schreibtischtest = c","quelle":"extra"},{"id":"n03f018","kapitel":3,"kapitel_name":"Testing","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Teststufen ihrem jeweiligen Prüfumfang zu:","begriffe":["Unit Test","Integrationstest","Systemtest","Abnahmetest"],"beschreibungen":[{"key":"a","text":"Prüft eine einzelne Funktion oder Methode isoliert vom Rest des Programms"},{"key":"b","text":"Prüft die Zusammenarbeit mehrerer Komponenten oder Module"},{"key":"c","text":"Prüft das vollständige, integrierte System auf funktionale und nicht-funktionale Anforderungen"},{"key":"d","text":"Prüft, ob das System die Geschäftsanforderungen erfüllt und vom Endbenutzer akzeptiert wird"}],"loesung_paare":{"Unit Test":"a","Integrationstest":"b","Systemtest":"c","Abnahmetest":"d"},"loesung":"Unit Test = a; Integrationstest = b; Systemtest = c; Abnahmetest = d","quelle":"extra"},{"id":"n04f001","kapitel":4,"kapitel_name":"Projektmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Phase folgt im Wasserfallmodell unmittelbar auf die Anforderungsanalyse?","optionen":[{"key":"A","text":"Systemdesign"},{"key":"B","text":"Implementierung"},{"key":"C","text":"Testen"},{"key":"D","text":"Betrieb und Wartung"}],"loesung_key":"A","loesung":"Systemdesign","quelle":"extra"},{"id":"n04f002","kapitel":4,"kapitel_name":"Projektmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wofür steht der Buchstabe A in der SMART-Formulierung eines Projektziels?","optionen":[{"key":"A","text":"Adaptable, also anpassbar"},{"key":"B","text":"Achievable, also erreichbar"},{"key":"C","text":"Accurate, also genau"},{"key":"D","text":"Agile, also agil"}],"loesung_key":"B","loesung":"Achievable, also erreichbar","quelle":"extra"},{"id":"n04f003","kapitel":4,"kapitel_name":"Projektmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Softwareprozessmodell stellt die Testphasen parallel zu den Entwicklungsphasen dar?","optionen":[{"key":"A","text":"Wasserfallmodell"},{"key":"B","text":"Spiralmodell"},{"key":"C","text":"V-Modell"},{"key":"D","text":"Kanban"}],"loesung_key":"C","loesung":"V-Modell","quelle":"extra"},{"id":"n04f004","kapitel":4,"kapitel_name":"Projektmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Dokument beschreibt die Anforderungen und Wünsche des Kunden und bildet die Grundlage für die Projektentwicklung?","optionen":[{"key":"A","text":"Pflichtenheft"},{"key":"B","text":"Product Backlog"},{"key":"C","text":"Story Board"},{"key":"D","text":"Lastenheft"}],"loesung_key":"D","loesung":"Lastenheft","quelle":"extra"},{"id":"n04f005","kapitel":4,"kapitel_name":"Projektmanagement","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie lange dauert ein Sprint im Scrum-Framework typischerweise?","optionen":[{"key":"A","text":"1 bis 2 Tage"},{"key":"B","text":"3 bis 6 Monate"},{"key":"C","text":"6 bis 12 Monate"},{"key":"D","text":"1 bis 4 Wochen"}],"loesung_key":"D","loesung":"1 bis 4 Wochen","quelle":"extra"},{"id":"n04f006","kapitel":4,"kapitel_name":"Projektmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Das V-Modell ist eine Erweiterung des Wasserfallmodells.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n04f007","kapitel":4,"kapitel_name":"Projektmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Das Sprint Backlog enthält alle Anforderungen des gesamten Projekts.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n04f008","kapitel":4,"kapitel_name":"Projektmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Agile Methoden eignen sich besonders für Projekte, bei denen sich die Anforderungen häufig ändern können.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n04f009","kapitel":4,"kapitel_name":"Projektmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Nicht-Ziele sind wünschenswerte Funktionen, die nicht zwingend erforderlich sind, aber einen Mehrwert bieten.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n04f010","kapitel":4,"kapitel_name":"Projektmanagement","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"DevOps fördert die kontinuierliche Integration und die kontinuierliche Bereitstellung (CI/CD).","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n04f011","kapitel":4,"kapitel_name":"Projektmanagement","typ":"lueckentext","typ_label":"Lückentext","frage":"Das __________ enthält die detaillierte Planung und Umsetzung des Projekts, unter anderem Zeitplan, technische Spezifikationen, Ressourcen und Testpläne.","loesung":"Pflichtenheft","quelle":"extra"},{"id":"n04f012","kapitel":4,"kapitel_name":"Projektmanagement","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine __________ beschreibt eine Funktion kurz aus Sicht des Endnutzers und definiert damit Anforderungen in einem agilen Projekt.","loesung":"User Story","alternativen":["User Story","Userstory","User-Story"],"quelle":"extra"},{"id":"n04f013","kapitel":4,"kapitel_name":"Projektmanagement","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei der __________ wird der aktuelle Zustand eines Systems oder Prozesses mit dem gewünschten Zustand verglichen, um Abweichungen zu erkennen.","loesung":"Soll-Ist-Analyse","alternativen":["Soll-Ist-Analyse","Soll Ist Analyse","Ist-Soll-Analyse"],"quelle":"extra"},{"id":"n04f014","kapitel":4,"kapitel_name":"Projektmanagement","typ":"lueckentext","typ_label":"Lückentext","frage":"Die vier Säulen des Projektmanagements sind Initiierung, Planung, Durchführung und __________.","loesung":"Abschluss","alternativen":["Abschluss","Projektabschluss"],"quelle":"extra"},{"id":"n04f015","kapitel":4,"kapitel_name":"Projektmanagement","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche drei Fragen beantwortet jedes Teammitglied im Daily Scrum?","loesung":"Jedes Teammitglied beantwortet im Daily Scrum drei Fragen. Erstens: Was habe ich seit dem letzten Daily Scrum erreicht? Zweitens: Was werde ich bis zum nächsten Daily Scrum machen? Drittens: Welche Hindernisse stehen mir im Weg? Das Daily Scrum ist ein kurzes Meeting zur täglichen Synchronisierung und Planung der Teamaktivitäten.","quelle":"extra"},{"id":"n04f016","kapitel":4,"kapitel_name":"Projektmanagement","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Warum ist die Analyse des Ist-Zustands beim Kunden wichtig? Nennen Sie ein Beispiel.","loesung":"Bei der Analyse des Ist-Zustands wird geprüft, was beim Kunden bereits vorhanden ist, zum Beispiel die bestehende Hardware und die vorhandenen Datenbanken. Das ist wichtig, weil die neue Lösung dazu kompatibel sein muss. Hat der Kunde etwa seine Daten in einer alten Datenbank, muss die neue Anwendung damit umgehen können. Deshalb wird im Kundengespräch gezielt nach diesen Aspekten gefragt.","quelle":"extra"},{"id":"n04f017","kapitel":4,"kapitel_name":"Projektmanagement","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie den Unterschied zwischen Muss-Zielen, Nice-to-have-Zielen und Nicht-Zielen.","loesung":"Muss-Ziele sind unabdingbare Anforderungen, die unbedingt erfüllt werden müssen. Nice-to-have-Ziele sind wünschenswerte Funktionen, die nicht zwingend erforderlich sind, aber einen Mehrwert bieten. Nicht-Ziele sind Aspekte, die bewusst nicht im Projektumfang enthalten sind und damit ausgeschlossen werden. Diese Unterscheidung wird bei der Anforderungsanalyse getroffen.","quelle":"extra"},{"id":"n04f018","kapitel":4,"kapitel_name":"Projektmanagement","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich das Wasserfallmodell und agiles Projektmanagement?","loesung":"Das Wasserfallmodell ist sequenziell aufgebaut. Jede Phase muss abgeschlossen sein, bevor die nächste beginnt, und Rücksprünge sind kaum vorgesehen. Es eignet sich für Projekte mit stabilen, klar definierten Anforderungen, festem Budget und Zeitrahmen sowie für streng reglementierte Entwicklungsprozesse. Agiles Projektmanagement arbeitet dagegen iterativ mit kurzen Entwicklungszyklen, regelmäßigen Feedbackschleifen und enger Zusammenarbeit im Team und eignet sich, wenn sich Anforderungen häufig ändern.","quelle":"extra"},{"id":"n04f019","kapitel":4,"kapitel_name":"Projektmanagement","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Scrum-Praktiken ihrer Beschreibung zu:","begriffe":["Sprint Planning","Daily Scrum","Sprint Retrospektive"],"beschreibungen":[{"key":"a","text":"Festlegen der Ziele und des Umfangs für den kommenden Sprint, bestehend aus den Teilen Was und Wie"},{"key":"b","text":"Kurzes tägliches Meeting zur Synchronisierung und Planung der Teamaktivitäten"},{"key":"c","text":"Reflexion über den vergangenen Sprint und Identifikation von Verbesserungsmöglichkeiten"}],"loesung_paare":{"Sprint Planning":"a","Daily Scrum":"b","Sprint Retrospektive":"c"},"loesung":"Sprint Planning = a; Daily Scrum = b; Sprint Retrospektive = c","quelle":"extra"},{"id":"n04f020","kapitel":4,"kapitel_name":"Projektmanagement","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Artefakte und Werkzeuge aus Scrum ihrer Beschreibung zu:","begriffe":["Product Backlog","Sprint Backlog","Story Board"],"beschreibungen":[{"key":"a","text":"Priorisierte Liste aller Aufgaben und Anforderungen des gesamten Produkts"},{"key":"b","text":"Liste der Aufgaben, die für den aktuellen Sprint vorgesehen sind"},{"key":"c","text":"Visuelles Werkzeug, das den Fortschritt der User Stories in den verschiedenen Phasen darstellt"}],"loesung_paare":{"Product Backlog":"a","Sprint Backlog":"b","Story Board":"c"},"loesung":"Product Backlog = a; Sprint Backlog = b; Story Board = c","quelle":"extra"},{"id":"n04f021","kapitel":4,"kapitel_name":"Projektmanagement","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Bestandteile der SMART-Formulierung ihrer deutschen Bedeutung zu:","begriffe":["Specific","Measurable","Relevant","Time-bound"],"beschreibungen":[{"key":"a","text":"Spezifisch"},{"key":"b","text":"Messbar"},{"key":"c","text":"Relevant"},{"key":"d","text":"Zeitgebunden"}],"loesung_paare":{"Specific":"a","Measurable":"b","Relevant":"c","Time-bound":"d"},"loesung":"Specific = a; Measurable = b; Relevant = c; Time-bound = d","quelle":"extra"},{"id":"n04f022","kapitel":4,"kapitel_name":"Projektmanagement","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Begriffe aus dem Projektmanagement ihrer Definition zu:","begriffe":["Softwareprozessmodell","Softwareentwurf","Prototyp","Projekt"],"beschreibungen":[{"key":"a","text":"Strukturierter Ansatz zur Softwareentwicklung, der bestimmte Phasen und Aktivitäten definiert"},{"key":"b","text":"Phase, in der die Architektur und das Design des Systems detailliert geplant werden"},{"key":"c","text":"Vorläufiges Arbeitsmodell zur Testung von Konzepten und zur Einholung von Nutzerfeedback"},{"key":"d","text":"Zeitlich begrenztes Vorhaben zur Erzeugung eines einzigartigen Produkts oder Ergebnisses"}],"loesung_paare":{"Softwareprozessmodell":"a","Softwareentwurf":"b","Prototyp":"c","Projekt":"d"},"loesung":"Softwareprozessmodell = a; Softwareentwurf = b; Prototyp = c; Projekt = d","quelle":"extra"},{"id":"n05f001","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher der folgenden SQL-Befehle gehört zur Data Definition Language (DDL)?","optionen":[{"key":"A","text":"ALTER"},{"key":"B","text":"UPDATE"},{"key":"C","text":"GRANT"},{"key":"D","text":"SELECT"}],"loesung_key":"A","loesung":"ALTER","quelle":"extra"},{"id":"n05f002","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher SQL-Operator gibt nur die gemeinsamen Ergebnisse zweier SELECT-Abfragen zurück?","optionen":[{"key":"A","text":"UNION"},{"key":"B","text":"INTERSECT"},{"key":"C","text":"UNION ALL"},{"key":"D","text":"CROSS JOIN"}],"loesung_key":"B","loesung":"INTERSECT","quelle":"extra"},{"id":"n05f003","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie viele Clustered Indizes kann eine Tabelle besitzen?","optionen":[{"key":"A","text":"Beliebig viele"},{"key":"B","text":"Einen pro Spalte"},{"key":"C","text":"Maximal einen"},{"key":"D","text":"Höchstens zwei"}],"loesung_key":"C","loesung":"Maximal einen","quelle":"extra"},{"id":"n05f004","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Join gibt das kartesische Produkt zweier Tabellen zurück, kombiniert also jede Zeile der ersten Tabelle mit jeder Zeile der zweiten?","optionen":[{"key":"A","text":"INNER JOIN"},{"key":"B","text":"FULL JOIN"},{"key":"C","text":"SELF JOIN"},{"key":"D","text":"CROSS JOIN"}],"loesung_key":"D","loesung":"CROSS JOIN","quelle":"extra"},{"id":"n05f005","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welchem Schritt der Datenmodellierung wird das ER-Diagramm erstellt?","optionen":[{"key":"A","text":"Anforderungsanalyse"},{"key":"B","text":"Logisches Modell"},{"key":"C","text":"Physisches Datenmodell"},{"key":"D","text":"Konzeptionelles Modell"}],"loesung_key":"D","loesung":"Konzeptionelles Modell","quelle":"extra"},{"id":"n05f006","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Aussage trifft auf eine Stored Function zu?","optionen":[{"key":"A","text":"Sie wird automatisch ausgeführt, sobald ein INSERT auf einer Tabelle erfolgt"},{"key":"B","text":"Sie gibt einen einzelnen Wert zurück und kann Eingabeparameter haben"},{"key":"C","text":"Sie ordnet die physische Reihenfolge der Daten in einer Tabelle"},{"key":"D","text":"Sie kombiniert die Ergebnisse zweier SELECT-Abfragen"}],"loesung_key":"B","loesung":"Sie gibt einen einzelnen Wert zurück und kann Eingabeparameter haben","quelle":"extra"},{"id":"n05f007","kapitel":5,"kapitel_name":"Datenbanken","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Anwendungsbereiche werden für hierarchische Datenbanken genannt?","optionen":[{"key":"A","text":"Finanzsysteme und E-Commerce-Plattformen"},{"key":"B","text":"Multimedia-Anwendungen und Echtzeit-Überwachungssysteme"},{"key":"C","text":"Verzeichnisdienste, Netzwerkadressierung und Routing Tabellen"},{"key":"D","text":"Social Media und Echtzeitanalysen"}],"loesung_key":"C","loesung":"Verzeichnisdienste, Netzwerkadressierung und Routing Tabellen","quelle":"extra"},{"id":"n05f008","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Non-Clustered Index legt eine separate Struktur in der Datenbank an, die Verweise auf die physischen Daten enthält.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n05f009","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Indizes beschleunigen sowohl Leseoperationen als auch Schreiboperationen wie INSERT, UPDATE und DELETE.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n05f010","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"UNION ALL kombiniert die Ergebnisse zweier SELECT-Abfragen einschließlich der Duplikate.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n05f011","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Rollback speichert die Änderungen einer Transaktion dauerhaft in der Datenbank.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n05f012","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine Transaktion ist eine Gruppe von Datenbankoperationen, die als Einheit ausgeführt wird.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n05f013","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"NoSQL-Datenbanken verfügen über eine einheitliche, standardisierte Abfragesprache.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n05f014","kapitel":5,"kapitel_name":"Datenbanken","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Nachteil hierarchischer Datenbanken ist, dass sie schwierig zu ändern sind, wenn sich die Struktur der Daten ändert.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n05f015","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ ist ein Attribut, das auf den Primärschlüssel einer anderen Tabelle verweist, um Beziehungen zu erstellen.","loesung":"Fremdschlüssel","alternativen":["Fremdschlüssel","Foreign Key","FK"],"quelle":"extra"},{"id":"n05f016","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"__________ bedeutet, dass dieselben Daten mehrfach in der Datenbank gespeichert sind, was zu Inkonsistenzen und unnötigem Speicherverbrauch führen kann.","loesung":"Redundanz","quelle":"extra"},{"id":"n05f017","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Die __________ regelt die Sortierung und den Vergleich von Zeichenfolgen in einer Datenbank, zum Beispiel utf8_general_ci für Vergleiche ohne Beachtung der Groß- und Kleinschreibung.","loesung":"Collation","alternativen":["Collation","Kollation","Sortierreihenfolge"],"quelle":"extra"},{"id":"n05f018","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Der __________ JOIN gibt alle Datensätze der linken Tabelle zurück und liefert NULL für die rechte Tabelle, wenn keine Übereinstimmung gefunden wird.","loesung":"LEFT","alternativen":["LEFT","LEFT OUTER","LEFT OUTER JOIN"],"quelle":"extra"},{"id":"n05f019","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Abkürzung DBMS steht für __________.","loesung":"Datenbankmanagementsystem","alternativen":["Datenbankmanagementsystem","Datenbank-Management-System","Database Management System"],"quelle":"extra"},{"id":"n05f020","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei einem __________ JOIN wird eine Tabelle mit sich selbst verknüpft, etwa um hierarchische oder rekursive Beziehungen abzubilden.","loesung":"SELF","alternativen":["SELF","SELF JOIN"],"quelle":"extra"},{"id":"n05f021","kapitel":5,"kapitel_name":"Datenbanken","typ":"lueckentext","typ_label":"Lückentext","frage":"Die __________ ist ein Prozess zur Organisation von Daten, um Redundanz zu minimieren und die Datenintegrität zu gewährleisten.","loesung":"Normalisierung","quelle":"extra"},{"id":"n05f022","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist ein Datenbankmanagementsystem (DBMS) und welche Funktionen stellt es bereit?","loesung":"Ein Datenbankmanagementsystem ist eine Software zur Verwaltung von Datenbanken. Es ermöglicht das Erstellen, Verwalten und Manipulieren von Datenbanken. Zusätzlich stellt es Funktionen zur Datenintegrität, zur Sicherheit und zur Wiederherstellung bereit. Bekannte Beispiele sind MySQL und Oracle.","quelle":"extra"},{"id":"n05f023","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist eine Stored Procedure und welche Vorteile bietet sie?","loesung":"Eine Stored Procedure ist eine vordefinierte und in der Datenbank gespeicherte Abfolge von SQL-Befehlen, die als Einheit ausgeführt werden kann. Sie kann Eingabe- und Ausgabeparameter haben und komplexe Operationen sowie Geschäftslogik direkt in der Datenbank ausführen. Vorteile sind die Wiederverwendbarkeit und ein Gewinn an Sicherheit.","quelle":"extra"},{"id":"n05f024","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Schritte umfasst das logische Modell bei der Vorgehensweise der Datenmodellierung?","loesung":"Im logischen Modell wird das ER-Diagramm in ein relationales Schema umgewandelt. Auf Basis der Entitäten und Attribute werden Tabellen und Spalten definiert. Anschließend werden die Primärschlüssel festgelegt und die Fremdschlüssel bestimmt. Zum Schluss wird die Datenbank normalisiert, um Redundanz zu vermeiden.","quelle":"extra"},{"id":"n05f025","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich ein ER-Diagramm und ein UML-Diagramm?","loesung":"Ein ER-Diagramm ist ein visuelles Modell zur Beschreibung der Struktur einer Datenbank. Es zeigt Entitäten und die Beziehungen zwischen diesen Entitäten und wird vor allem bei der Datenmodellierung und beim Datenbankentwurf eingesetzt. Ein UML-Diagramm stellt dagegen Struktur, Verhalten und Beziehungen von Software-Systemen dar und zeigt Klassen, Objekte, Schnittstellen und deren Interaktionen. UML unterstützt damit die Planung und Dokumentation von Softwareprojekten und die Kommunikation zwischen Entwicklern, Designern und Stakeholdern.","quelle":"extra"},{"id":"n05f026","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen und erklären Sie drei Nachteile von NoSQL-Datenbanken.","loesung":"Erstens die Konsistenz: NoSQL-Datenbanken bieten eventuell keine vollständige ACID-Konformität, da oft das BASE-Modell verwendet wird. Zweitens die Komplexität: Es kann herausfordernd sein, die richtige NoSQL-Datenbank für die jeweiligen Anforderungen auszuwählen. Drittens die fehlende Standardisierung: Es gibt keine einheitliche Abfragesprache, was die Portabilität zwischen verschiedenen NoSQL-Systemen erschwert.","quelle":"extra"},{"id":"n05f027","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist ein Constraint in einer Datenbank? Geben Sie ein Beispiel an.","loesung":"Ein Constraint ist eine Einschränkung für Datenbankspalten, mit der die Datenintegrität sichergestellt wird. Es legt fest, welche Werte in einer Spalte zulässig sind. Ein Beispiel ist CHECK (age >= 18), womit nur Werte ab 18 erlaubt sind. Weitere Beispiele für Constraints sind NOT NULL und UNIQUE, die beim physischen Datenmodell festgelegt werden.","quelle":"extra"},{"id":"n05f028","kapitel":5,"kapitel_name":"Datenbanken","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Merkmale und Vorteile haben objektorientierte Datenbanken?","loesung":"Objektorientierte Datenbanken speichern Daten als Objekte, die Klassen, Attribute und Methoden enthalten. Objekte können Eigenschaften anderer Objekte erben und Methoden überschreiben, und komplexe Datenstrukturen und Beziehungen werden direkt im Datenmodell unterstützt. Vorteile sind die gute Eignung für Anwendungen mit objektorientierten Programmiersprachen und die direkte Abbildung von Objekten aus der Programmiersprache in die Datenbank. Eingesetzt werden sie etwa bei Multimedia-Anwendungen und Echtzeit-Überwachungssystemen, ein Beispiel ist db4o.","quelle":"extra"},{"id":"n05f029","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die SQL-Sprachbestandteile ihrer Aufgabe zu:","begriffe":["Data Definition Language (DDL)","Data Manipulation Language (DML)","Data Control Language (DCL)"],"beschreibungen":[{"key":"a","text":"Definiert und ändert die Struktur von Datenbankobjekten, Befehle sind CREATE, ALTER, DROP und TRUNCATE"},{"key":"b","text":"Manipuliert und liest die Daten, Befehle sind SELECT, INSERT, UPDATE und DELETE"},{"key":"c","text":"Steuert Berechtigungen und Zugriff auf Datenbankobjekte, Befehle sind GRANT und REVOKE"}],"loesung_paare":{"Data Definition Language (DDL)":"a","Data Manipulation Language (DML)":"b","Data Control Language (DCL)":"c"},"loesung":"Data Definition Language (DDL) = a; Data Manipulation Language (DML) = b; Data Control Language (DCL) = c","quelle":"extra"},{"id":"n05f030","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Join-Arten ihrem Ergebnis zu:","begriffe":["INNER JOIN","RIGHT JOIN","FULL JOIN"],"beschreibungen":[{"key":"a","text":"Gibt nur die Datensätze zurück, die in beiden Tabellen übereinstimmende Werte in den verbundenen Spalten haben"},{"key":"b","text":"Gibt alle Datensätze der rechten Tabelle zurück und NULL für die linke Tabelle, wenn es keine Übereinstimmung gibt"},{"key":"c","text":"Gibt alle Datensätze zurück, sobald es in einer der beiden Tabellen eine Übereinstimmung gibt, fehlende Werte werden mit NULL gefüllt"}],"loesung_paare":{"INNER JOIN":"a","RIGHT JOIN":"b","FULL JOIN":"c"},"loesung":"INNER JOIN = a; RIGHT JOIN = b; FULL JOIN = c","quelle":"extra"},{"id":"n05f031","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Arten der Integrität ihrer Bedeutung zu:","begriffe":["Entitätsintegrität","Referentielle Integrität","Domänenbezogene Integrität"],"beschreibungen":[{"key":"a","text":"Jeder Datensatz muss eindeutig identifizierbar sein"},{"key":"b","text":"Beziehungen zwischen Tabellen müssen konsistent bleiben"},{"key":"c","text":"Daten müssen bestimmten Regeln entsprechen"}],"loesung_paare":{"Entitätsintegrität":"a","Referentielle Integrität":"b","Domänenbezogene Integrität":"c"},"loesung":"Entitätsintegrität = a; Referentielle Integrität = b; Domänenbezogene Integrität = c","quelle":"extra"},{"id":"n05f032","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Normalformen ihrer Definition zu:","begriffe":["0. Normalform","1. Normalform","2. Normalform","3. Normalform"],"beschreibungen":[{"key":"a","text":"Zustand einer Tabelle, die keine Normalisierungsregeln befolgt"},{"key":"b","text":"Alle Attributwerte sind atomar und jede Zeile ist eindeutig identifizierbar"},{"key":"c","text":"Liegt in der ersten Normalform vor und jedes Nicht-Schlüsselattribut hängt vollständig vom gesamten Primärschlüssel ab"},{"key":"d","text":"Liegt in der zweiten Normalform vor und kein Nicht-Schlüsselattribut hängt transitiv vom Primärschlüssel ab"}],"loesung_paare":{"0. Normalform":"a","1. Normalform":"b","2. Normalform":"c","3. Normalform":"d"},"loesung":"0. Normalform = a; 1. Normalform = b; 2. Normalform = c; 3. Normalform = d","quelle":"extra"},{"id":"n05f033","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden NoSQL-Kategorien den passenden Produktbeispielen zu:","begriffe":["Dokumentendatenbank","Key-Value-Datenbank","Spaltenorientierte Datenbank","Graphdatenbank"],"beschreibungen":[{"key":"a","text":"MongoDB und CouchDB"},{"key":"b","text":"Redis und Amazon DynamoDB"},{"key":"c","text":"Apache Cassandra und HBase"},{"key":"d","text":"Neo4j und Amazon Neptune"}],"loesung_paare":{"Dokumentendatenbank":"a","Key-Value-Datenbank":"b","Spaltenorientierte Datenbank":"c","Graphdatenbank":"d"},"loesung":"Dokumentendatenbank = a; Key-Value-Datenbank = b; Spaltenorientierte Datenbank = c; Graphdatenbank = d","quelle":"extra"},{"id":"n05f034","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Begriffe rund um Transaktionen ihrer Bedeutung zu:","begriffe":["Transaktion","Commit","Rollback"],"beschreibungen":[{"key":"a","text":"Gruppe von Datenbankoperationen, die als Einheit ausgeführt werden"},{"key":"b","text":"Speichert die Änderungen nach der Ausführung in der Datenbank"},{"key":"c","text":"Macht alle Operationen wieder rückgängig"}],"loesung_paare":{"Transaktion":"a","Commit":"b","Rollback":"c"},"loesung":"Transaktion = a; Commit = b; Rollback = c","quelle":"extra"},{"id":"n05f035","kapitel":5,"kapitel_name":"Datenbanken","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Trigger-Typen ihrem Ausführungszeitpunkt und Einsatzzweck zu:","begriffe":["BEFORE Trigger","AFTER Trigger","INSTEAD OF Trigger"],"beschreibungen":[{"key":"a","text":"Wird vor dem Datenbank-Ereignis ausgeführt und kann Eingabedaten validieren oder ändern"},{"key":"b","text":"Wird nach dem Datenbank-Ereignis ausgeführt, etwa um verwandte Tabellen zu aktualisieren oder Log-Einträge zu schreiben"},{"key":"c","text":"Wird anstelle des eigentlichen Ereignisses ausgeführt und ist für Views nützlich, die nicht direkt aktualisierbar sind"}],"loesung_paare":{"BEFORE Trigger":"a","AFTER Trigger":"b","INSTEAD OF Trigger":"c"},"loesung":"BEFORE Trigger = a; AFTER Trigger = b; INSTEAD OF Trigger = c","quelle":"extra"},{"id":"n06f001","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter Netzwerktechnik und welche Aufgabe erfüllt sie?","loesung":"Netzwerktechnik umfasst alle Methoden und Technologien, die nötig sind, um Geräte miteinander zu verbinden, sodass sie Informationen austauschen können. Das reicht von kleinen lokalen Netzwerken bis zu globalen Netzwerken wie dem Internet. Sie bildet die Grundlage für nahezu alle modernen Kommunikationsformen und Datenverarbeitungssysteme.","quelle":"extra"},{"id":"n06f002","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Netzwerktopologie bietet durch die Verbindung jedes Geräts mit jedem anderen die höchste Redundanz und Ausfallsicherheit?","optionen":[{"key":"A","text":"Bus-Topologie"},{"key":"B","text":"Stern-Topologie"},{"key":"C","text":"Ring-Topologie"},{"key":"D","text":"Vollvermaschte Topologie"}],"loesung_key":"D","loesung":"Vollvermaschte Topologie","quelle":"extra"},{"id":"n06f003","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"In einer Ring-Topologie werden die Daten in nur einer Richtung weitergeleitet, wodurch keine Kollisionen entstehen und die volle Bandbreite nutzbar ist.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f004","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Die __________-Topologie ist eine hierarchische Kombination aus Bus- und Stern-Topologie, bei der es eine zentrale Wurzel gibt, von der aus Äste und Zweige abzweigen.","loesung":"Baum","alternativen":["Baum-Topologie","Baumtopologie"],"quelle":"extra"},{"id":"n06f005","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Beschreiben Sie die Peer-to-Peer-Topologie und nennen Sie je einen Vorteil und einen Nachteil.","loesung":"In einem Peer-to-Peer-Netzwerk sind alle Geräte gleichberechtigt und kommunizieren direkt miteinander, ohne dass ein zentrales Gerät wie ein Server nötig ist. Vorteil ist, dass die Lösung kostengünstig und einfach einzurichten ist, weil kein dedizierter Server gebraucht wird. Nachteil ist, dass sie schlecht skaliert, weniger sicher ist und in größeren Netzwerken unübersichtlich und ineffizient wird.","quelle":"extra"},{"id":"n06f006","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Was kennzeichnen die ersten 24 Bit einer MAC-Adresse?","optionen":[{"key":"A","text":"Die Seriennummer des Geräts"},{"key":"B","text":"Den Hersteller des Geräts (Organizationally Unique Identifier)"},{"key":"C","text":"Die Prüfsumme des Datenrahmens"},{"key":"D","text":"Den Netzwerkanteil der zugehörigen IP-Adresse"}],"loesung_key":"B","loesung":"Den Hersteller des Geräts (Organizationally Unique Identifier)","quelle":"extra"},{"id":"n06f007","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine IPv4-Adresse besteht aus 32 Bit und wird in vier __________ dargestellt, die durch Punkte voneinander getrennt sind.","loesung":"Oktetten","alternativen":["Oktette","Oktett"],"quelle":"extra"},{"id":"n06f008","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Aufeinanderfolgende Nullblöcke in einer IPv6-Adresse dürfen innerhalb einer Adresse beliebig oft durch einen doppelten Doppelpunkt zusammengefasst werden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f009","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Bestandteile der Netzwerkadressierung ihrer Bedeutung zu:","begriffe":["Netzwerkanteil","Hostanteil","OUI"],"beschreibungen":[{"key":"a","text":"Teil der IP-Adresse, der das Netzwerk kennzeichnet, zu dem ein Gerät gehört"},{"key":"b","text":"Teil der IP-Adresse, der das einzelne Gerät innerhalb des Netzwerks kennzeichnet"},{"key":"c","text":"Die ersten 24 Bit einer MAC-Adresse, die den Hersteller kennzeichnen"}],"loesung_paare":{"Netzwerkanteil":"a","Hostanteil":"b","OUI":"c"},"loesung":"Netzwerkanteil = a; Hostanteil = b; OUI = c","quelle":"extra"},{"id":"n06f010","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie viele unterschiedliche Adressen sind mit dem 32 Bit langen IPv4-Adressraum theoretisch möglich?","optionen":[{"key":"A","text":"65.536"},{"key":"B","text":"16.777.216"},{"key":"C","text":"4.294.967.296"},{"key":"D","text":"340 Undezillionen"}],"loesung_key":"C","loesung":"4.294.967.296","quelle":"extra"},{"id":"n06f011","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Hub leitet eingehende Datenpakete gezielt nur an den Port weiter, an dem das Zielgerät angeschlossen ist.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f012","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Patchpanels zählen zu den aktiven Netzwerkkomponenten, weil sie die durchlaufenden Signale verstärken.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f013","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Aufgabe erfüllt ein Modem in einem Netzwerk?","loesung":"Ein Modem wandelt digitale Signale in analoge Signale um und umgekehrt. Dadurch wird die Kommunikation über Übertragungsmedien wie Telefonleitungen möglich. In Heimnetzwerken findet man Modems häufig gemeinsam mit einem Router oder als kombiniertes Gerät.","quelle":"extra"},{"id":"n06f014","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Switching-Verfahren wartet, bis die ersten 64 Byte eines Pakets empfangen sind, um Kollisionen zu vermeiden?","optionen":[{"key":"A","text":"Fragment Free Switching"},{"key":"B","text":"Cut-Through Switching"},{"key":"C","text":"Store-and-Forward Switching"},{"key":"D","text":"Adaptive Cut-Through Switching"}],"loesung_key":"A","loesung":"Fragment Free Switching","quelle":"extra"},{"id":"n06f015","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Switching-Verfahren ihrer Arbeitsweise zu:","begriffe":["Cut-Through Switching","Store-and-Forward Switching","Adaptive Cut-Through Switching"],"beschreibungen":[{"key":"a","text":"Leitet das Paket sofort nach dem Lesen der Ziel-MAC-Adresse weiter, sehr schnell, aber weniger sicher"},{"key":"b","text":"Empfängt das gesamte Paket, prüft es auf Fehler und leitet es erst danach weiter"},{"key":"c","text":"Wechselt je nach Fehlerhäufigkeit im Netzwerk dynamisch zwischen zwei Verfahren"}],"loesung_paare":{"Cut-Through Switching":"a","Store-and-Forward Switching":"b","Adaptive Cut-Through Switching":"c"},"loesung":"Cut-Through Switching = a; Store-and-Forward Switching = b; Adaptive Cut-Through Switching = c","quelle":"extra"},{"id":"n06f016","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein Switch verwendet eine __________, um zu entscheiden, an welchen Port ein eingehendes Paket gesendet werden soll.","loesung":"MAC-Adresstabelle","alternativen":["MAC-Adress-Tabelle","SAT","Source Address Table"],"quelle":"extra"},{"id":"n06f017","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Routing-Protokoll wird zwischen autonomen Systemen im Internet eingesetzt?","optionen":[{"key":"A","text":"RIP"},{"key":"B","text":"BGP"},{"key":"C","text":"OSPF"},{"key":"D","text":"EIGRP"}],"loesung_key":"B","loesung":"BGP","quelle":"extra"},{"id":"n06f018","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Routing-Protokolle ihrer Arbeitsweise zu:","begriffe":["RIP","OSPF","EIGRP"],"beschreibungen":[{"key":"a","text":"Verwendet die Anzahl der Hops als Metrik, einfach, aber bei großen Netzwerken weniger effizient"},{"key":"b","text":"Link-State-Protokoll, das den besten Pfad auf Basis einer umfassenden Netzwerkansicht berechnet"},{"key":"c","text":"Hybrides Protokoll, das Merkmale von Distance-Vector- und Link-State-Protokollen kombiniert"}],"loesung_paare":{"RIP":"a","OSPF":"b","EIGRP":"c"},"loesung":"RIP = a; OSPF = b; EIGRP = c","quelle":"extra"},{"id":"n06f019","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Routing arbeitet über mehrere Netzwerke hinweg und leitet Daten anhand von IP-Adressen weiter, während Switching innerhalb eines Netzwerks anhand von MAC-Adressen arbeitet.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f020","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Aufgabe hat die Primärverkabelung und welches Übertragungsmedium wird dafür typischerweise verwendet?","loesung":"Die Primärverkabelung, auch Backbone-Verkabelung genannt, verbindet die zentralen Netzwerkkomponenten wie Hauptverteilerräume innerhalb eines großen Standorts oder zwischen mehreren Standorten. Sie überbrückt große Distanzen und bildet das Rückgrat des Netzwerks. Dafür werden meist Glasfaserkabel eingesetzt, weil sie hohe Bandbreiten und geringe Latenzzeiten bieten.","quelle":"extra"},{"id":"n06f021","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Sekundärverkabelung wird auch als __________ Verkabelung bezeichnet, weil sie meist durch die Etagen eines Gebäudes verläuft und die Hauptverteiler mit den Unterverteilern verbindet.","loesung":"vertikale","alternativen":["vertikal","Vertikalverkabelung"],"quelle":"extra"},{"id":"n06f022","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welcher Reihenfolge laufen die drei Schritte des TCP Three-Way Handshake ab?","optionen":[{"key":"A","text":"ACK, SYN, SYN-ACK"},{"key":"B","text":"SYN, ACK, SYN-ACK"},{"key":"C","text":"SYN-ACK, SYN, ACK"},{"key":"D","text":"SYN, SYN-ACK, ACK"}],"loesung_key":"D","loesung":"SYN, SYN-ACK, ACK","quelle":"extra"},{"id":"n06f023","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"UDP baut vor der Datenübertragung eine Verbindung auf und garantiert die Reihenfolge sowie die Zuverlässigkeit der übertragenen Daten.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f024","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Der Ablauf, mit dem ein DHCP-Server einem Client eine IP-Adresse zuweist, wird als __________-Prozess bezeichnet.","loesung":"DORA","alternativen":["DORA-Prozess"],"quelle":"extra"},{"id":"n06f025","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Portnummern den zugehörigen Diensten zu:","begriffe":["Port 443","Port 53","Port 21","Port 110"],"beschreibungen":[{"key":"a","text":"HTTPS"},{"key":"b","text":"DNS"},{"key":"c","text":"FTP, Steuerverbindung"},{"key":"d","text":"POP3, unverschlüsselt"}],"loesung_paare":{"Port 443":"a","Port 53":"b","Port 21":"c","Port 110":"d"},"loesung":"Port 443 = a; Port 53 = b; Port 21 = c; Port 110 = d","quelle":"extra"},{"id":"n06f026","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie am Beispiel blog.example.com den Aufbau einer Domain.","loesung":"Der Teil ganz rechts, hier .com, ist die Top-Level-Domain, also die oberste Ebene der DNS-Hierarchie. Davor steht mit example die Second-Level-Domain, die von einer Organisation oder Person registriert wurde. Der vorangestellte Teil blog ist eine Sub-Domain, mit der innerhalb der Hauptdomain eigene Bereiche oder Dienste organisiert werden können.","quelle":"extra"},{"id":"n06f027","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche NAT-Variante ändert zusätzlich die Portnummern, damit mehrere Geräte über eine einzige öffentliche IP-Adresse kommunizieren können?","optionen":[{"key":"A","text":"SNAT (Source NAT)"},{"key":"B","text":"DNAT (Destination NAT)"},{"key":"C","text":"PAT (Port Address Translation)"},{"key":"D","text":"APIPA (Automatic Private IP Addressing)"}],"loesung_key":"C","loesung":"PAT (Port Address Translation)","quelle":"extra"},{"id":"n06f028","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei POP3 bleiben die E-Mails standardmäßig auf dem Server gespeichert und werden zwischen mehreren Geräten synchronisiert.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f029","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Beim SSL/TLS-Handshake erzeugt der Client eine zufällige Zahl, das sogenannte __________, und verschlüsselt sie mit dem öffentlichen Schlüssel des Servers.","loesung":"Pre-Master Secret","alternativen":["Pre Master Secret","Premaster Secret"],"quelle":"extra"},{"id":"n06f030","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich SSL und TLS?","loesung":"SSL war das ursprüngliche Protokoll für die sichere Kommunikation im Internet, hatte aber bekannte Sicherheitslücken. TLS ist die Weiterentwicklung von SSL und bietet verbesserte Sicherheitsfunktionen sowie eine stärkere Verschlüsselung. SSL wurde deshalb weitgehend durch TLS ersetzt, der Begriff SSL wird aber umgangssprachlich noch für verschlüsselte Verbindungen allgemein verwendet.","quelle":"extra"},{"id":"n06f031","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welchen UDP-Port verwendet ein DHCP-Client, um die Nachrichten des DHCP-Servers zu empfangen?","optionen":[{"key":"A","text":"UDP-Port 68"},{"key":"B","text":"UDP-Port 67"},{"key":"C","text":"UDP-Port 53"},{"key":"D","text":"UDP-Port 69"}],"loesung_key":"A","loesung":"UDP-Port 68","quelle":"extra"},{"id":"n06f032","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Erkennen zwei Geräte bei CSMA/CD eine Kollision, stoppen sie die Übertragung und senden ein __________, um alle anderen Geräte darüber zu informieren.","loesung":"Jam-Signal","alternativen":["Jam Signal","Jamsignal"],"quelle":"extra"},{"id":"n06f033","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei CSMA/CA signalisiert das sendewillige Gerät seine Absicht mit einem RTS-Signal und sendet die Daten erst, nachdem der Empfänger mit einem CTS-Signal geantwortet hat.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f034","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Medienzugriffsverfahren ihrer Funktionsweise zu:","begriffe":["Token Passing","Polling","TDMA","FDMA"],"beschreibungen":[{"key":"a","text":"Nur das Gerät, das ein umlaufendes Sonderdatenpaket besitzt, darf senden"},{"key":"b","text":"Ein zentraler Controller erteilt jedem Gerät der Reihe nach die Erlaubnis zu senden"},{"key":"c","text":"Die Zeit wird in Slots unterteilt, jedes Gerät darf nur in seinem Zeitfenster senden"},{"key":"d","text":"Das Frequenzspektrum wird in Bänder unterteilt, jedes Gerät sendet auf einem eigenen Frequenzband"}],"loesung_paare":{"Token Passing":"a","Polling":"b","TDMA":"c","FDMA":"d"},"loesung":"Token Passing = a; Polling = b; TDMA = c; FDMA = d","quelle":"extra"},{"id":"n06f035","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Auf der Vermittlungsschicht des OSI-Modells werden die Daten in Form von Frames übertragen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f036","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die OSI-Schichten ihrer Funktion zu:","begriffe":["Transportschicht","Sitzungsschicht","Darstellungsschicht","Anwendungsschicht"],"beschreibungen":[{"key":"a","text":"Segmentiert die Daten und sorgt für Flusskontrolle sowie fehlerfreie Übertragung zwischen Endgeräten"},{"key":"b","text":"Baut Kommunikationssitzungen zwischen Anwendungen auf, verwaltet und beendet sie"},{"key":"c","text":"Übersetzt Datenformate und ist für Datenkompression und Verschlüsselung zuständig"},{"key":"d","text":"Stellt Schnittstellen für Endbenutzer-Anwendungen wie E-Mail, Dateitransfer und Web-Browsing bereit"}],"loesung_paare":{"Transportschicht":"a","Sitzungsschicht":"b","Darstellungsschicht":"c","Anwendungsschicht":"d"},"loesung":"Transportschicht = a; Sitzungsschicht = b; Darstellungsschicht = c; Anwendungsschicht = d","quelle":"extra"},{"id":"n06f037","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die Frame Check Sequence (FCS) eines Ethernet-Frames ist 4 Byte lang und dient der Fehlererkennung mittels CRC.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f038","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Das Feld __________ im IPv4-Header gibt die Lebensdauer eines Pakets an und verhindert dadurch Endlosschleifen im Netzwerk.","loesung":"TTL","alternativen":["Time to Live","TTL (Time to Live)"],"quelle":"extra"},{"id":"n06f039","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"In welche zwei Teilschichten ist die Sicherungsschicht unterteilt und welche Aufgaben haben diese?","loesung":"Die Sicherungsschicht besteht aus der MAC-Teilschicht und der LLC-Teilschicht. Die MAC-Schicht (Media Access Control) verwaltet den Zugriff auf das physische Medium und die MAC-Adressen. Die LLC-Schicht (Logical Link Control) bietet Dienste zur Flusskontrolle, zur Fehlerbehandlung und zum Multiplexing.","quelle":"extra"},{"id":"n06f040","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Protokoll der Sicherungsschicht übersetzt IP-Adressen in MAC-Adressen?","optionen":[{"key":"A","text":"STP (Spanning Tree Protocol)"},{"key":"B","text":"ARP (Address Resolution Protocol)"},{"key":"C","text":"ICMP (Internet Control Message Protocol)"},{"key":"D","text":"PPP (Point-to-Point Protocol)"}],"loesung_key":"B","loesung":"ARP (Address Resolution Protocol)","quelle":"extra"},{"id":"n06f041","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Nachteil ist typisch für die symmetrische Verschlüsselung?","optionen":[{"key":"A","text":"Sie ist bei großen Datenmengen deutlich langsamer als die asymmetrische Verschlüsselung"},{"key":"B","text":"Sie benötigt zwingend ein Zertifikat einer Zertifizierungsstelle"},{"key":"C","text":"Sie kann ausschließlich für digitale Signaturen eingesetzt werden"},{"key":"D","text":"Der gemeinsame geheime Schlüssel muss sicher zwischen den Parteien ausgetauscht werden"}],"loesung_key":"D","loesung":"Der gemeinsame geheime Schlüssel muss sicher zwischen den Parteien ausgetauscht werden","quelle":"extra"},{"id":"n06f042","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie das Prinzip der asymmetrischen Verschlüsselung und nennen Sie ein Beispielverfahren.","loesung":"Bei der asymmetrischen Verschlüsselung wird ein Schlüsselpaar verwendet: Mit dem öffentlichen Schlüssel werden Daten verschlüsselt, mit dem privaten Schlüssel wieder entschlüsselt. Weil der öffentliche Schlüssel frei zugänglich sein darf, entfällt das Risiko beim Schlüsselaustausch. Ein bekanntes Beispiel ist RSA, das unter anderem für digitale Signaturen und für den Schlüsselaustausch bei SSL/TLS eingesetzt wird. Nachteil ist, dass das Verfahren langsamer ist als die symmetrische Verschlüsselung.","quelle":"extra"},{"id":"n06f043","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welchem Adressbereich weist sich ein Gerät per APIPA selbst eine Adresse zu, wenn kein DHCP-Server erreichbar und keine statische Adresse konfiguriert ist?","optionen":[{"key":"A","text":"10.0.0.x"},{"key":"B","text":"172.16.x.x"},{"key":"C","text":"169.254.x.x"},{"key":"D","text":"192.168.x.x"}],"loesung_key":"C","loesung":"169.254.x.x","quelle":"extra"},{"id":"n06f044","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Adressen der Klasse D werden für Multicast-Gruppen verwendet und besitzen keine Standard-Subnetzmaske.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f045","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die IP-Klassen ihren privaten Adressbereichen und Standard-Subnetzmasken zu:","begriffe":["Klasse A","Klasse B","Klasse C"],"beschreibungen":[{"key":"a","text":"10.0.0.0 bis 10.255.255.255, Standard-Subnetzmaske /8"},{"key":"b","text":"172.16.0.0 bis 172.31.255.255, Standard-Subnetzmaske /16"},{"key":"c","text":"192.168.0.0 bis 192.168.255.255, Standard-Subnetzmaske /24"}],"loesung_paare":{"Klasse A":"a","Klasse B":"b","Klasse C":"c"},"loesung":"Klasse A = a; Klasse B = b; Klasse C = c","quelle":"extra"},{"id":"n06f046","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Ein Netzwerk mit der Adresse 192.168.10.0/24 soll in vier gleich große Subnetze geteilt werden. Welche Subnetzmaske ist dafür nötig und wie viele Adressen umfasst jedes Subnetz?","loesung":"Für vier Subnetze wird die Präfixlänge /26 benötigt, das entspricht der Subnetzmaske 255.255.255.192. Damit werden die ersten 26 Bit für die Netzwerkadresse und die restlichen 6 Bit für Hosts verwendet. Jedes der vier Subnetze umfasst dadurch 64 IP-Adressen, zum Beispiel 192.168.10.0/26, 192.168.10.64/26, 192.168.10.128/26 und 192.168.10.192/26.","quelle":"extra"},{"id":"n06f047","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine Hybrid Cloud kombiniert Private und Public Cloud und ermöglicht es, Workloads zwischen beiden Umgebungen zu verschieben.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f048","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Cloud-Modelle ihrer Beschreibung zu:","begriffe":["IaaS","PaaS","SaaS"],"beschreibungen":[{"key":"a","text":"Bereitstellung grundlegender IT-Infrastruktur wie Rechenleistung, Speicher und Netzwerke"},{"key":"b","text":"Bereitstellung einer Plattform, auf der Entwickler Anwendungen erstellen, bereitstellen und verwalten können"},{"key":"c","text":"Bereitstellung fertiger Softwareanwendungen über das Internet, zum Beispiel Microsoft Office 365"}],"loesung_paare":{"IaaS":"a","PaaS":"b","SaaS":"c"},"loesung":"IaaS = a; PaaS = b; SaaS = c","quelle":"extra"},{"id":"n06f049","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Schadsoftware verbreitet sich selbstständig über Netzwerke, ohne dass ein Benutzereingriff nötig ist, und nutzt dabei Sicherheitslücken aus?","optionen":[{"key":"A","text":"Wurm"},{"key":"B","text":"Virus"},{"key":"C","text":"Trojaner"},{"key":"D","text":"Spyware"}],"loesung_key":"A","loesung":"Wurm","quelle":"extra"},{"id":"n06f050","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Spyware ist eine selbstreplizierende Schadsoftware, die sich an andere Programme anhängt und sich dadurch verbreitet.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n06f051","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Angriffe, die Sicherheitslücken in Software ausnutzen, bevor diese durch Updates behoben werden können, nennt man __________.","loesung":"Zero-Day-Exploits","alternativen":["Zero-Day-Exploit","Zero Day Exploit"],"quelle":"extra"},{"id":"n06f052","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Firewalls beginnen ab Layer __________ des OSI-Modells zu arbeiten, wo sie IP-Pakete sowie Absender- und Empfängeradressen analysieren.","loesung":"3","alternativen":["Layer 3","drei","Vermittlungsschicht"],"quelle":"extra"},{"id":"n06f053","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Firewall-Typen ihrer Funktionsweise zu:","begriffe":["Paketfilter-Firewall","Stateful Inspection Firewall","Proxy-Firewall","Next-Generation Firewall"],"beschreibungen":[{"key":"a","text":"Analysiert nur die Header von Datenpaketen und entscheidet anhand vordefinierter Regeln"},{"key":"b","text":"Überwacht den Zustand von Verbindungen und berücksichtigt den Kontext des Datenverkehrs"},{"key":"c","text":"Agiert als Vermittler zwischen internen Clients und externen Servern und prüft den Verkehr auf Anwendungsebene"},{"key":"d","text":"Kombiniert klassische Firewall-Funktionen mit IPS, Deep Packet Inspection und Anwendungsbewusstsein"}],"loesung_paare":{"Paketfilter-Firewall":"a","Stateful Inspection Firewall":"b","Proxy-Firewall":"c","Next-Generation Firewall":"d"},"loesung":"Paketfilter-Firewall = a; Stateful Inspection Firewall = b; Proxy-Firewall = c; Next-Generation Firewall = d","quelle":"extra"},{"id":"n06f054","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich Hardware-Firewalls und Software-Firewalls?","loesung":"Eine Hardware-Firewall ist ein eigenes physisches Gerät, das zwischen dem internen und dem externen Netzwerk installiert wird und den gesamten ein- und ausgehenden Datenverkehr filtert. Durch die dedizierte Hardware ist sie sehr leistungsfähig und wird vor allem in Unternehmen eingesetzt. Eine Software-Firewall ist ein Programm, das auf einem einzelnen Computer oder Server läuft und nur den Verkehr dieses Geräts kontrolliert, zum Beispiel die Windows Defender Firewall.","quelle":"extra"},{"id":"n06f055","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Proxy-Typ nimmt Anfragen externer Clients entgegen und leitet sie an interne Server weiter, etwa zur Lastverteilung?","optionen":[{"key":"A","text":"Forward Proxy"},{"key":"B","text":"Reverse Proxy"},{"key":"C","text":"Transparent Proxy"},{"key":"D","text":"Paketfilter-Proxy"}],"loesung_key":"B","loesung":"Reverse Proxy","quelle":"extra"},{"id":"n06f056","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Beim __________ werden häufig angeforderte Webinhalte auf dem Proxy-Server gespeichert, um Ladezeiten zu verkürzen und die Bandbreitennutzung zu reduzieren.","loesung":"URL Caching","alternativen":["URL-Caching","Caching"],"quelle":"extra"},{"id":"n06f057","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei einer Whitelist werden ausdrücklich erlaubte Adressen oder URLs aufgelistet, während der übrige Zugriff blockiert wird.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n06f058","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist eine DMZ und wie ist sie im Netzwerk platziert?","loesung":"Eine DMZ (Demilitarized Zone) ist eine eigene Sicherheitszone, die öffentlich erreichbare Dienste wie Web- oder Mailserver vom internen Netzwerk trennt. Sie liegt zwischen zwei Firewalls, von denen eine das interne und eine das externe Netzwerk absichert. Strenge Regeln legen fest, welcher Datenverkehr zwischen Internet, DMZ und internem Netzwerk erlaubt ist. Dadurch bleibt das interne Netzwerk auch dann geschützt, wenn ein Server in der DMZ kompromittiert wird.","quelle":"extra"},{"id":"n06f059","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Cookie-Arten ihrer Beschreibung zu:","begriffe":["Session Cookies","Persistente Cookies","Erstanbieter Cookies","Drittanbieter Cookies"],"beschreibungen":[{"key":"a","text":"Werden nur während einer Sitzung gespeichert und gelöscht, sobald der Browser geschlossen wird"},{"key":"b","text":"Speichern Informationen über mehrere Sitzungen hinweg, zum Beispiel Spracheinstellungen"},{"key":"c","text":"Werden direkt von der besuchten Website gesetzt"},{"key":"d","text":"Werden von Werbenetzwerken oder Analysediensten gesetzt, um Aktivitäten über mehrere Websites hinweg zu verfolgen"}],"loesung_paare":{"Session Cookies":"a","Persistente Cookies":"b","Erstanbieter Cookies":"c","Drittanbieter Cookies":"d"},"loesung":"Session Cookies = a; Persistente Cookies = b; Erstanbieter Cookies = c; Drittanbieter Cookies = d","quelle":"extra"},{"id":"n06f060","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Tracking-Technik nutzt HTML5-Canvas-Elemente, um eine unsichtbare Grafik zu rendern und daraus einen Nutzer wiederzuerkennen?","optionen":[{"key":"A","text":"Tracking-Pixel"},{"key":"B","text":"Session Cookie"},{"key":"C","text":"Do Not Track"},{"key":"D","text":"Canvas Fingerprinting"}],"loesung_key":"D","loesung":"Canvas Fingerprinting","quelle":"extra"},{"id":"n06f061","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Die unbefugte Nutzung persönlicher Daten einer Person, um illegale Handlungen durchzuführen oder finanzielle Vorteile zu erlangen, bezeichnet man als __________.","loesung":"Identitätsdiebstahl","quelle":"extra"},{"id":"n06f062","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie wird es bezeichnet, wenn ein Angreifer einem autorisierten Mitarbeiter unbemerkt in ein gesichertes Gebäude folgt?","optionen":[{"key":"A","text":"Baiting"},{"key":"B","text":"Pretexting"},{"key":"C","text":"Tailgating"},{"key":"D","text":"Quid-Pro-Quo"}],"loesung_key":"C","loesung":"Tailgating","quelle":"extra"},{"id":"n06f063","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter Spear-Phishing und wodurch unterscheidet es sich vom gewöhnlichen Phishing?","loesung":"Spear-Phishing ist eine gezielte Form des Phishing. Während gewöhnliches Phishing breit gestreute gefälschte E-Mails oder Webseiten verwendet, sammelt der Angreifer beim Spear-Phishing vorher detaillierte Informationen über das konkrete Opfer. Damit wirkt die Täuschung deutlich glaubwürdiger und die Erfolgswahrscheinlichkeit steigt.","quelle":"extra"},{"id":"n06f064","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Benutzerkontotypen ihren Rechten zu:","begriffe":["Administrator","Standardbenutzer","Gast"],"beschreibungen":[{"key":"a","text":"Vollzugriff auf das System, kann Einstellungen ändern, Software installieren und Benutzerkonten verwalten"},{"key":"b","text":"Eingeschränkter Zugriff, kann Anwendungen ausführen und nur Einstellungen des eigenen Kontos ändern"},{"key":"c","text":"Sehr eingeschränkte Zugriffsrechte, gedacht für temporäre Benutzer ohne Änderungsbedarf"}],"loesung_paare":{"Administrator":"a","Standardbenutzer":"b","Gast":"c"},"loesung":"Administrator = a; Standardbenutzer = b; Gast = c","quelle":"extra"},{"id":"n06f065","kapitel":6,"kapitel_name":"Netzwerktechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Das Prinzip der __________ besagt, dass Benutzern nur die minimalen Rechte gewährt werden sollen, die sie zur Ausführung ihrer Aufgaben benötigen.","loesung":"geringsten Privilegien","alternativen":["geringste Privilegien","Least Privilege"],"quelle":"extra"},{"id":"n07f001","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welchen zusätzlichen Schutz bieten moderne Antivirus-Lösungen laut Buch neben der Erkennung und Entfernung von Malware?","optionen":[{"key":"A","text":"Schutz vor Phishing"},{"key":"B","text":"Automatische Datensicherung auf ein NAS"},{"key":"C","text":"Zentrale Verwaltung von Benutzerkonten"},{"key":"D","text":"Verteilung von Gruppenrichtlinien"}],"loesung_key":"A","loesung":"Schutz vor Phishing","quelle":"extra"},{"id":"n07f002","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Steckertyp gehört laut Buch zu Geräten der Schutzklasse 1?","optionen":[{"key":"A","text":"Eurostecker"},{"key":"B","text":"Schukostecker"},{"key":"C","text":"USB-Stecker"},{"key":"D","text":"Niedervoltstecker"}],"loesung_key":"B","loesung":"Schukostecker","quelle":"extra"},{"id":"n07f003","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Zu welchem Authentifizierungsfaktor zählt die Anmeldung mittels Fingerabdruck?","optionen":[{"key":"A","text":"Wissen"},{"key":"B","text":"Besitz"},{"key":"C","text":"Inhärenz"},{"key":"D","text":"Verhalten"}],"loesung_key":"C","loesung":"Inhärenz","quelle":"extra"},{"id":"n07f004","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welchen Vorteil nennt das Buch bei der vermaschten Topologie unter dem Punkt Skalierbarkeit?","optionen":[{"key":"A","text":"Erweiterungen sind nur bis zu einer festgelegten Anzahl von Geräten möglich."},{"key":"B","text":"Bei jeder Erweiterung muss die bestehende Verkabelung vollständig neu geplant werden."},{"key":"C","text":"Die Anzahl der Verbindungen bleibt bei einer Erweiterung unverändert."},{"key":"D","text":"Das Netzwerk kann erweitert werden, ohne die bestehende Struktur zu beeinträchtigen."}],"loesung_key":"D","loesung":"Das Netzwerk kann erweitert werden, ohne die bestehende Struktur zu beeinträchtigen.","quelle":"extra"},{"id":"n07f005","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Geräte der Schutzklasse 2 benötigen keine Schutzerdung, weil sie über eine doppelte oder verstärkte Isolierung verfügen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n07f006","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Einmalpasswort (OTP) ist dauerhaft gültig und kann für mehrere Anmeldungen wiederverwendet werden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n07f007","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Beim LS-Schalter löst zusätzlich zur thermischen Auslösung ein elektromagnetischer Mechanismus aus, wenn ein plötzlicher Kurzschluss auftritt.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n07f008","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine aktive USV (Online-USV) schaltet sich erst dann ein, wenn der Strom bereits ausgefallen ist.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n07f009","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Geräte der Schutzklasse 3 arbeiten mit __________ (SELV, PELV), die so niedrig ist, dass selbst bei direktem Kontakt keine gefährlichen Spannungen auftreten können.","loesung":"Schutzkleinspannung","quelle":"extra"},{"id":"n07f010","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein FI-Schalter arbeitet nach dem Prinzip des __________ Gesetzes, wonach die Summe der Ströme in einem geschlossenen Stromkreis gleich null sein muss.","loesung":"Kirchhoffschen","alternativen":["Kirchhoffsche","Kirchhoff","kirchhoffschen"],"quelle":"extra"},{"id":"n07f011","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Die __________ USV ist eine Kombination aus aktiver und passiver USV und bietet sowohl Spannungsanpassungen als auch eine unterbrechungsfreie Versorgung.","loesung":"netzinteraktive","alternativen":["netzinteraktiv","Netzinteraktive"],"quelle":"extra"},{"id":"n07f012","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"lueckentext","typ_label":"Lückentext","frage":"Der Fehlerstromschutzschalter wird umgangssprachlich FI-Schalter genannt und trägt die englische Bezeichnung __________.","loesung":"RCD","alternativen":["Residual Current Device"],"quelle":"extra"},{"id":"n07f013","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheidet sich eine aktive USV (Online-USV) von einer passiven USV (Offline-USV)?","loesung":"Bei der aktiven USV läuft die Stromversorgung ständig durch die USV. Dadurch werden Spannungsabweichungen laufend ausgeglichen und die Versorgung bleibt völlig unterbrechungsfrei, weshalb sie für Rechenzentren oder Krankenhäuser empfohlen wird. Die passive USV schaltet sich erst bei einem Stromausfall oder einer starken Spannungsschwankung ein, wodurch es zu einer kurzen Unterbrechung kommen kann. Sie eignet sich daher für weniger kritische Systeme wie Büroumgebungen.","quelle":"extra"},{"id":"n07f014","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich Geräte der Schutzklasse 1 von Geräten der Schutzklasse 2? Nennen Sie zu jeder Schutzklasse ein Beispielgerät.","loesung":"Geräte der Schutzklasse 1 haben eine Basisisolierung und zusätzlich eine Schutzerdung, über die im Fall eines Isolationsfehlers der Strom sicher abgeleitet wird. Beispiele sind Kühlschränke oder Waschmaschinen. Geräte der Schutzklasse 2 besitzen stattdessen eine doppelte oder verstärkte Isolierung und brauchen deshalb keine Schutzerdung. Beispiele sind Bohrmaschinen oder Haartrockner.","quelle":"extra"},{"id":"n07f015","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie die thermisch-magnetische Funktionsweise eines LS-Schalters.","loesung":"Der LS-Schalter besitzt eine thermische Komponente in Form eines Bimetallstreifens. Dieser erhitzt sich bei einer dauerhaften Überlastung und unterbricht dadurch den Stromkreis. Zusätzlich gibt es einen elektromagnetischen Auslöser, der bei einem plötzlichen Kurzschluss sofort abschaltet. So werden die Leitungen vor Überhitzung und der damit verbundenen Brandgefahr geschützt.","quelle":"extra"},{"id":"n07f016","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Schutzklassen dem jeweils genannten Steckertyp zu:","begriffe":["Schutzklasse 1","Schutzklasse 2","Schutzklasse 3"],"beschreibungen":[{"key":"a","text":"Schukostecker (Schutzkontaktstecker)"},{"key":"b","text":"Flachstecker oder Eurostecker"},{"key":"c","text":"Niedervoltstecker oder USB-Stecker"}],"loesung_paare":{"Schutzklasse 1":"a","Schutzklasse 2":"b","Schutzklasse 3":"c"},"loesung":"Schutzklasse 1 = a; Schutzklasse 2 = b; Schutzklasse 3 = c","quelle":"extra"},{"id":"n07f017","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Authentifizierungsfaktoren der Multi-Faktor-Authentifizierung den passenden Beispielen zu:","begriffe":["Wissen","Besitz","Inhärenz"],"beschreibungen":[{"key":"a","text":"Das Passwort, das der Benutzer kennt"},{"key":"b","text":"Das Smartphone, auf dem ein einmaliger Code empfangen wird"},{"key":"c","text":"Biometrische Daten wie ein Fingerabdruck"}],"loesung_paare":{"Wissen":"a","Besitz":"b","Inhärenz":"c"},"loesung":"Wissen = a; Besitz = b; Inhärenz = c","quelle":"extra"},{"id":"n07f018","kapitel":7,"kapitel_name":"Sicherheitstechnik","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Schutzklassen den im Buch genannten Beispielgeräten zu:","begriffe":["Schutzklasse 1","Schutzklasse 2","Schutzklasse 3"],"beschreibungen":[{"key":"a","text":"Waschmaschine und Mikrowelle"},{"key":"b","text":"Schleifmaschine und elektrische Zahnbürste"},{"key":"c","text":"Tablet und tragbare LED-Leuchte"}],"loesung_paare":{"Schutzklasse 1":"a","Schutzklasse 2":"b","Schutzklasse 3":"c"},"loesung":"Schutzklasse 1 = a; Schutzklasse 2 = b; Schutzklasse 3 = c","quelle":"extra"},{"id":"n08f001","kapitel":8,"kapitel_name":"Datensicherung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie viele Festplatten sind für ein RAID 5 mindestens erforderlich?","optionen":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"6"}],"loesung_key":"B","loesung":"3","quelle":"extra"},{"id":"n08f002","kapitel":8,"kapitel_name":"Datensicherung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie hoch ist die Speichereffizienz eines RAID 6 mit vier Festplatten?","optionen":[{"key":"A","text":"50 %"},{"key":"B","text":"66,67 %"},{"key":"C","text":"75 %"},{"key":"D","text":"100 %"}],"loesung_key":"A","loesung":"50 %","quelle":"extra"},{"id":"n08f003","kapitel":8,"kapitel_name":"Datensicherung","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Merkmal trifft laut Buch auf ein Hardware-RAID zu?","optionen":[{"key":"A","text":"Die CPU wird stark belastet, wodurch die Gesamtperformance leidet."},{"key":"B","text":"Es ist in jedem Fall die kostengünstigste Lösung."},{"key":"C","text":"Der Tausch von Festplatten im laufenden Betrieb ist möglicherweise schwierig."},{"key":"D","text":"Es ist plattformunabhängig und entlastet die CPU, weil ein RAID-Controller die Steuerung übernimmt."}],"loesung_key":"D","loesung":"Es ist plattformunabhängig und entlastet die CPU, weil ein RAID-Controller die Steuerung übernimmt.","quelle":"extra"},{"id":"n08f004","kapitel":8,"kapitel_name":"Datensicherung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei einem RAID 10 gehen keine Daten verloren, solange nicht beide Festplatten desselben Spiegelpaares ausfallen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n08f005","kapitel":8,"kapitel_name":"Datensicherung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein RAID 5 verkraftet den gleichzeitigen Ausfall von zwei Festplatten, ohne dass Daten verloren gehen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n08f006","kapitel":8,"kapitel_name":"Datensicherung","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Beim Software-RAID übernimmt ein eigener RAID-Controller die Steuerung, wodurch die CPU entlastet wird.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n08f007","kapitel":8,"kapitel_name":"Datensicherung","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei RAID 0 werden die Daten in Streifen auf alle Festplatten verteilt. Dieses Verfahren wird als __________ bezeichnet.","loesung":"Striping","quelle":"extra"},{"id":"n08f008","kapitel":8,"kapitel_name":"Datensicherung","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein Hardware-RAID bietet __________, das heißt, Festplatten können im laufenden Betrieb getauscht werden.","loesung":"Hot-Swap","alternativen":["Hot Swap","Hot-Swap-Funktionalität","Hotswap"],"quelle":"extra"},{"id":"n08f009","kapitel":8,"kapitel_name":"Datensicherung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Aufgabe haben die Paritätsinformationen bei RAID 5 und welche Nachteile bringen sie mit sich?","loesung":"Bei RAID 5 werden neben den Daten auch Paritätsinformationen in Streifen auf alle Festplatten verteilt. Mit dieser Parität lassen sich die Daten wiederherstellen, wenn eine einzelne Festplatte ausfällt. Der Nachteil ist, dass die Berechnung und Verteilung der Parität die Schreib-Performance beeinträchtigen kann. Außerdem sind Implementierung und Wiederherstellung komplexer als bei einfacheren RAID-Leveln.","quelle":"extra"},{"id":"n08f010","kapitel":8,"kapitel_name":"Datensicherung","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie, wie im Großvater-Vater-Sohn-Prinzip aus den täglichen Backups wöchentliche und monatliche Sicherungen entstehen.","loesung":"Jeden Tag wird ein Sohn-Backup erstellt, das regelmäßig überschrieben wird. Am Ende jeder Woche wird eines dieser täglichen Backups als Vater-Backup aufbewahrt und erst am Ende eines Monats überschrieben. Am Ende jedes Monats wird eines der wöchentlichen Backups als Großvater-Backup archiviert. Die Großvater-Backups werden erst nach einem Jahr oder einem anderen festgelegten Zeitraum überschrieben.","quelle":"extra"},{"id":"n08f011","kapitel":8,"kapitel_name":"Datensicherung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie den RAID-Leveln die jeweils angegebene Speichereffizienz zu:","begriffe":["RAID 0","RAID 1","RAID 5"],"beschreibungen":[{"key":"a","text":"100 Prozent, es geht kein Speicherplatz durch Redundanz verloren"},{"key":"b","text":"50 Prozent beziehungsweise n/2"},{"key":"c","text":"(N-1)/N, bei vier Platten also 75 Prozent"}],"loesung_paare":{"RAID 0":"a","RAID 1":"b","RAID 5":"c"},"loesung":"RAID 0 = a; RAID 1 = b; RAID 5 = c","quelle":"extra"},{"id":"n08f012","kapitel":8,"kapitel_name":"Datensicherung","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Backup-Generationen des Großvater-Vater-Sohn-Prinzips der jeweils üblichen Frequenz und Anzahl zu:","begriffe":["Sohn-Backup","Vater-Backup","Großvater-Backup"],"beschreibungen":[{"key":"a","text":"Täglich, normalerweise 5 bis 7 Sicherungen"},{"key":"b","text":"Wöchentlich, normalerweise 4 bis 5 Sicherungen"},{"key":"c","text":"Monatlich, normalerweise 12 Sicherungen"}],"loesung_paare":{"Sohn-Backup":"a","Vater-Backup":"b","Großvater-Backup":"c"},"loesung":"Sohn-Backup = a; Vater-Backup = b; Großvater-Backup = c","quelle":"extra"},{"id":"n09f001","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Um wie viel Prozent darf ein unverbindlicher Kostenvoranschlag höchstens überschritten werden?","optionen":[{"key":"A","text":"Maximal 15 Prozent"},{"key":"B","text":"Maximal 5 Prozent"},{"key":"C","text":"Maximal 25 Prozent"},{"key":"D","text":"Er darf gar nicht überschritten werden"}],"loesung_key":"A","loesung":"Maximal 15 Prozent","quelle":"extra"},{"id":"n09f002","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Mindestkapital ist für die Gründung einer Aktiengesellschaft (AG) in Österreich erforderlich?","optionen":[{"key":"A","text":"10.000 Euro"},{"key":"B","text":"70.000 Euro"},{"key":"C","text":"35.000 Euro"},{"key":"D","text":"700.000 Euro"}],"loesung_key":"B","loesung":"70.000 Euro","quelle":"extra"},{"id":"n09f003","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Bis zu welchem Bruttobetrag darf eine Kleinbetragsrechnung ausgestellt werden?","optionen":[{"key":"A","text":"150 Euro"},{"key":"B","text":"250 Euro"},{"key":"C","text":"400 Euro"},{"key":"D","text":"1.000 Euro"}],"loesung_key":"C","loesung":"400 Euro","quelle":"extra"},{"id":"n09f004","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie lange müssen Firmen Rechnungen aufbewahren?","optionen":[{"key":"A","text":"Zwei Jahre"},{"key":"B","text":"Drei Jahre"},{"key":"C","text":"Fünf Jahre"},{"key":"D","text":"Sieben Jahre"}],"loesung_key":"D","loesung":"Sieben Jahre","quelle":"extra"},{"id":"n09f005","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wer haftet in einer Kommanditgesellschaft (KG) ausschließlich mit seiner Kapitaleinlage?","optionen":[{"key":"A","text":"Der Kommanditist"},{"key":"B","text":"Der Komplementär"},{"key":"C","text":"Jeder Gesellschafter zu gleichen Teilen"},{"key":"D","text":"Ausschließlich die Gesellschaft selbst"}],"loesung_key":"A","loesung":"Der Kommanditist","quelle":"extra"},{"id":"n09f006","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Aus wie vielen Stellen besteht die Kontonummer innerhalb einer österreichischen IBAN?","optionen":[{"key":"A","text":"2 Stellen"},{"key":"B","text":"11 Stellen"},{"key":"C","text":"5 Stellen"},{"key":"D","text":"20 Stellen"}],"loesung_key":"B","loesung":"11 Stellen","quelle":"extra"},{"id":"n09f007","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Umsatzsteuersatz gilt in Österreich für Pflanzen, Blumen und Tiernahrung?","optionen":[{"key":"A","text":"10 Prozent"},{"key":"B","text":"20 Prozent"},{"key":"C","text":"13 Prozent"},{"key":"D","text":"0 Prozent"}],"loesung_key":"C","loesung":"13 Prozent","quelle":"extra"},{"id":"n09f008","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Ab welchem Jahresumsatz in zwei aufeinanderfolgenden Geschäftsjahren muss sich ein Einzelunternehmen ins Firmenbuch eintragen lassen?","optionen":[{"key":"A","text":"35.000 Euro"},{"key":"B","text":"400.000 Euro"},{"key":"C","text":"500.000 Euro"},{"key":"D","text":"700.000 Euro"}],"loesung_key":"D","loesung":"700.000 Euro","quelle":"extra"},{"id":"n09f009","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein mündlich geschlossener Vertrag ist grundsätzlich ebenso rechtsverbindlich wie ein schriftlicher Vertrag.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n09f010","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Für die Gründung einer Offenen Gesellschaft (OG) ist ein Mindestkapital von 10.000 Euro vorgeschrieben.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n09f011","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei einem Kauf im Geschäft besteht ein gesetzliches 14-tägiges Rückgaberecht.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n09f012","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Skonto ist ein Preisnachlass, den der Käufer bei Zahlung innerhalb einer bestimmten Frist erhält.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n09f013","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die Gesellschafter einer GmbH haften neben ihrer Einlage auch mit ihrem gesamten Privatvermögen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n09f014","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei einer GmbH & Co KG übernimmt die GmbH die Rolle des Komplementärs.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n09f015","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Eine Gesellschaft bürgerlichen Rechts (GesbR) muss nicht ins Firmenbuch eingetragen werden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n09f016","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein Preisnachlass des Verkäufers auf den regulären Verkaufspreis wird als __________ bezeichnet.","loesung":"Rabatt","quelle":"extra"},{"id":"n09f017","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei einem verbindlichen __________ dürfen die angeführten Kosten nicht überschritten werden.","loesung":"Kostenvoranschlag","quelle":"extra"},{"id":"n09f018","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"lueckentext","typ_label":"Lückentext","frage":"Der __________ begleitet die Lieferung von Waren und enthält unter anderem das Lieferdatum sowie Menge und Bezeichnung der Produkte.","loesung":"Lieferschein","quelle":"extra"},{"id":"n09f019","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"lueckentext","typ_label":"Lückentext","frage":"Kann das Unternehmen im Gewährleistungsfall keinen Ersatz leisten, tritt die __________ in Kraft, bei der der Kaufvertrag annulliert und der Kaufpreis zurückerstattet wird.","loesung":"Wandlung","quelle":"extra"},{"id":"n09f020","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"lueckentext","typ_label":"Lückentext","frage":"Der __________ ist der Überschuss, der nach Abzug aller Kosten vom Umsatz übrig bleibt.","loesung":"Gewinn","alternativen":["Nettogewinn","Reingewinn"],"quelle":"extra"},{"id":"n09f021","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ wird zwischen Arbeitgeberverbänden und Gewerkschaften abgeschlossen und regelt Gehälter und Arbeitsbedingungen einer ganzen Branche.","loesung":"Kollektivvertrag","alternativen":["Kollektivvertrages","KV"],"quelle":"extra"},{"id":"n09f022","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie den Unterschied zwischen Gewährleistung und Garantie.","loesung":"Die Gewährleistung ist eine gesetzliche Verpflichtung des Händlers und stellt sicher, dass die verkaufte Ware frei von Mängeln ist. Sie ist im ABGB und für Verbrauchergeschäfte im Verbrauchergewährleistungsgesetz (VGG) geregelt und beträgt zwei Jahre für bewegliche und drei Jahre für unbewegliche Güter. Die Garantie ist dagegen eine freiwillige Zusatzleistung des Herstellers oder Verkäufers, die über die Gewährleistung hinausgehen muss, um für den Kunden einen Nutzen zu haben, etwa durch längere Laufzeit oder zusätzliche Serviceleistungen.","quelle":"extra"},{"id":"n09f023","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was versteht man unter der Vorsteuerabzugsberechtigung?","loesung":"Unternehmen mit einer UID-Nummer dürfen die auf Eingangsrechnungen bezahlte Mehrwertsteuer, also die Vorsteuer, von der Umsatzsteuer abziehen, die sie ihren Kunden verrechnen. Dadurch werden gezahlte und eingenommene Umsatzsteuer gegenverrechnet und die Steuerlast trägt letztlich nur der Endverbraucher. Voraussetzung ist, dass die Eingangsrechnungen korrekt ausgestellt sind und alle notwendigen Angaben enthalten.","quelle":"extra"},{"id":"n09f024","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen und erklären Sie die drei Voraussetzungen, die für einen rechtsgültigen Vertragsabschluss erfüllt sein müssen.","loesung":"Erstens die Geschäftsfähigkeit: Ab 18 Jahren ist man voll geschäftsfähig, davor nur mindergeschäftsfähig oder beschränkt geschäftsfähig. Zweitens die Freiwilligkeit: Der Vertrag muss ohne Zwang oder Täuschung zustande kommen. Drittens der rechtmäßige Inhalt: Der Vertrag darf nicht gegen Gesetze oder die guten Sitten verstoßen, zum Beispiel durch eine Entlohnung unter dem kollektivvertraglichen Mindestlohn.","quelle":"extra"},{"id":"n09f025","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie mindestens fünf Angaben, die eine vollständige Rechnung enthalten muss.","loesung":"Eine vollständige Rechnung enthält Name und Anschrift des Verkäufers, die UID-Nummern von Verkäufer und Käufer sowie Rechnungsnummer und Ausstellungsdatum. Dazu kommen der Zeitraum der Lieferung, Bezeichnung und Menge der Produkte, der Einzelpreis netto und der Nettogesamtbetrag. Außerdem müssen die Umsatzsteuersätze und -beträge und der Bruttogesamtbetrag ausgewiesen sein.","quelle":"extra"},{"id":"n09f026","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie den Unterschied zwischen Umsatz und Gewinn.","loesung":"Der Umsatz ist der Gesamtwert aller verkauften Waren und Dienstleistungen in einem bestimmten Zeitraum und wird aus verkaufter Menge mal Verkaufspreis berechnet. Er sagt aber nichts über die Rentabilität aus, weil die Kosten nicht berücksichtigt sind. Der Gewinn ist der Überschuss, der nach Abzug aller Kosten wie Herstellungskosten, Betriebskosten, Steuern und Zinsen vom Umsatz übrig bleibt.","quelle":"extra"},{"id":"n09f027","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Voraussetzungen muss eine Person erfüllen, um in Österreich ein Unternehmen gründen zu dürfen?","loesung":"Die Person muss volljährig sein, also das 18. Lebensjahr vollendet haben, und es darf keine gerichtliche Erwachsenenvertretung bestehen, die die Geschäftsfähigkeit einschränkt. Weiters darf sie keine Vorstrafen oder Anklagen im Finanzsektor oder wegen schwerwiegender Delikte wie Drogenhandel haben. Es dürfen keine Freiheitsstrafen von mehr als drei Monaten oder Geldstrafen von mehr als 180 Tagessätzen vorliegen (§ 13 GewO), und die Person muss Bürger der EU oder des EWR sein.","quelle":"extra"},{"id":"n09f028","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Unternehmensformen ihrem Haftungsmerkmal zu:","begriffe":["Einzelunternehmen","Offene Gesellschaft (OG)","Kommanditgesellschaft (KG)","Aktiengesellschaft (AG)"],"beschreibungen":[{"key":"a","text":"Eine einzelne Person haftet unbeschränkt mit Privat- und Geschäftsvermögen"},{"key":"b","text":"Alle Gesellschafter haften persönlich und unbeschränkt"},{"key":"c","text":"Ein Vollhafter haftet unbeschränkt, ein Teilhafter nur mit seiner Einlage"},{"key":"d","text":"Die Haftung der Aktionäre ist auf ihre Einlage beschränkt, Mindestkapital 70.000 Euro"}],"loesung_paare":{"Einzelunternehmen":"a","Offene Gesellschaft (OG)":"b","Kommanditgesellschaft (KG)":"c","Aktiengesellschaft (AG)":"d"},"loesung":"Einzelunternehmen = a; Offene Gesellschaft (OG) = b; Kommanditgesellschaft (KG) = c; Aktiengesellschaft (AG) = d","quelle":"extra"},{"id":"n09f029","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Steuerarten den passenden Beschreibungen zu:","begriffe":["Körperschaftsteuer","Kapitalertragsteuer","Lohnsteuer","Einkommensteuer"],"beschreibungen":[{"key":"a","text":"Steuer auf das Einkommen juristischer Personen wie GmbH oder AG"},{"key":"b","text":"Quellensteuer auf Kapitalerträge natürlicher Personen, etwa Dividenden"},{"key":"c","text":"Wird vom Einkommen unselbständig Angestellter eingehoben"},{"key":"d","text":"Wird vom Einkommen selbständig Erwerbstätiger eingehoben"}],"loesung_paare":{"Körperschaftsteuer":"a","Kapitalertragsteuer":"b","Lohnsteuer":"c","Einkommensteuer":"d"},"loesung":"Körperschaftsteuer = a; Kapitalertragsteuer = b; Lohnsteuer = c; Einkommensteuer = d","quelle":"extra"},{"id":"n09f030","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Zweige der Sozialversicherung ihrem Zweck zu:","begriffe":["Pensionsversicherung","Krankenversicherung","Unfallversicherung","Arbeitslosenversicherung"],"beschreibungen":[{"key":"a","text":"Sicherung der Altersversorgung"},{"key":"b","text":"Deckung medizinischer Kosten"},{"key":"c","text":"Schutz bei Arbeitsunfällen"},{"key":"d","text":"Unterstützung im Falle von Arbeitslosigkeit"}],"loesung_paare":{"Pensionsversicherung":"a","Krankenversicherung":"b","Unfallversicherung":"c","Arbeitslosenversicherung":"d"},"loesung":"Pensionsversicherung = a; Krankenversicherung = b; Unfallversicherung = c; Arbeitslosenversicherung = d","quelle":"extra"},{"id":"n09f031","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Mängelarten den passenden Beispielen zu:","begriffe":["Offener Mangel","Verdeckter Mangel","Schwerer Mangel","Arglistig verschwiegener Mangel"],"beschreibungen":[{"key":"a","text":"Sofort erkennbare Abweichung von der Produktbeschreibung, etwa ein Kratzer auf einem neuen Tisch"},{"key":"b","text":"Ein Elektronikdefekt, der erst nach Wochen des Gebrauchs auftritt"},{"key":"c","text":"Ein Auto, das wegen eines Motorproblems nicht fahrtüchtig ist"},{"key":"d","text":"Ein Wasserschaden im Keller, den der Verkäufer kennt, aber absichtlich verschweigt"}],"loesung_paare":{"Offener Mangel":"a","Verdeckter Mangel":"b","Schwerer Mangel":"c","Arglistig verschwiegener Mangel":"d"},"loesung":"Offener Mangel = a; Verdeckter Mangel = b; Schwerer Mangel = c; Arglistig verschwiegener Mangel = d","quelle":"extra"},{"id":"n09f032","kapitel":9,"kapitel_name":"Wirtschaftsrecht","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die kaufmännischen Dokumente ihrer Funktion zu:","begriffe":["Lieferschein","Kostenvoranschlag","Angebot","Kleinbetragsrechnung"],"beschreibungen":[{"key":"a","text":"Begleitet die Warenlieferung und weist Menge und Bezeichnung der gelieferten Produkte aus"},{"key":"b","text":"Schriftliche Aufstellung der voraussichtlichen Kosten mit Gültigkeitsdatum"},{"key":"c","text":"In der Regel kostenlos und weniger detailliert als eine Kostenaufstellung"},{"key":"d","text":"Vereinfachte Rechnung für Beträge bis 400 Euro brutto"}],"loesung_paare":{"Lieferschein":"a","Kostenvoranschlag":"b","Angebot":"c","Kleinbetragsrechnung":"d"},"loesung":"Lieferschein = a; Kostenvoranschlag = b; Angebot = c; Kleinbetragsrechnung = d","quelle":"extra"},{"id":"n10f001","kapitel":10,"kapitel_name":"DSGVO","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Innerhalb welcher Frist muss ein Unternehmen eine Datenschutzverletzung spätestens der zuständigen Datenschutzbehörde melden?","optionen":[{"key":"A","text":"Innerhalb von 72 Stunden"},{"key":"B","text":"Innerhalb von 24 Stunden"},{"key":"C","text":"Innerhalb von sieben Tagen"},{"key":"D","text":"Innerhalb eines Monats"}],"loesung_key":"A","loesung":"Innerhalb von 72 Stunden","quelle":"extra"},{"id":"n10f002","kapitel":10,"kapitel_name":"DSGVO","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie lange gilt das Urheberrecht in der Regel nach dem Tod des Urhebers?","optionen":[{"key":"A","text":"50 Jahre"},{"key":"B","text":"70 Jahre"},{"key":"C","text":"30 Jahre"},{"key":"D","text":"100 Jahre"}],"loesung_key":"B","loesung":"70 Jahre","quelle":"extra"},{"id":"n10f003","kapitel":10,"kapitel_name":"DSGVO","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wer entscheidet nach der DSGVO über die Zwecke und Mittel der Verarbeitung personenbezogener Daten?","optionen":[{"key":"A","text":"Der Auftragsverarbeiter"},{"key":"B","text":"Die betroffene Person"},{"key":"C","text":"Der Verantwortliche"},{"key":"D","text":"Der Datenschutzbeauftragte"}],"loesung_key":"C","loesung":"Der Verantwortliche","quelle":"extra"},{"id":"n10f004","kapitel":10,"kapitel_name":"DSGVO","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Gesetz regelt die Informationspflichten von Online-Händlern und die Anforderungen an elektronische Vertragsabschlüsse?","optionen":[{"key":"A","text":"Das Telekommunikationsgesetz (TKG)"},{"key":"B","text":"Das Urheberrechtsgesetz"},{"key":"C","text":"Das Datenschutzgesetz (DSG)"},{"key":"D","text":"Das E-Commerce-Gesetz (ECG)"}],"loesung_key":"D","loesung":"Das E-Commerce-Gesetz (ECG)","quelle":"extra"},{"id":"n10f005","kapitel":10,"kapitel_name":"DSGVO","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die DSGVO schützt sowohl natürliche als auch juristische Personen bei der Verarbeitung ihrer Daten.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n10f006","kapitel":10,"kapitel_name":"DSGVO","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"IP-Adressen zählen zu den personenbezogenen Daten im Sinne der DSGVO.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n10f007","kapitel":10,"kapitel_name":"DSGVO","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die Verarbeitung personenbezogener Daten durch natürliche Personen für rein persönliche oder familiäre Zwecke ist von der DSGVO ausgenommen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n10f008","kapitel":10,"kapitel_name":"DSGVO","typ":"lueckentext","typ_label":"Lückentext","frage":"Der Grundsatz der __________ schreibt vor, dass nur jene personenbezogenen Daten erhoben und verarbeitet werden dürfen, die für den jeweiligen Zweck notwendig sind.","loesung":"Datenminimierung","quelle":"extra"},{"id":"n10f009","kapitel":10,"kapitel_name":"DSGVO","typ":"lueckentext","typ_label":"Lückentext","frage":"Eine natürliche oder juristische Person, die personenbezogene Daten im Auftrag des Verantwortlichen verarbeitet, wird als __________ bezeichnet.","loesung":"Auftragsverarbeiter","quelle":"extra"},{"id":"n10f010","kapitel":10,"kapitel_name":"DSGVO","typ":"lueckentext","typ_label":"Lückentext","frage":"Betreiber von Webseiten sind verpflichtet, ein __________ mit Name, Adresse, Kontaktinformationen, Firmenbuchnummer und UID bereitzustellen.","loesung":"Impressum","quelle":"extra"},{"id":"n10f011","kapitel":10,"kapitel_name":"DSGVO","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie vier Rechte der betroffenen Person nach der DSGVO und erklären Sie zwei davon kurz.","loesung":"Betroffene haben unter anderem das Recht auf Auskunft, das Recht auf Berichtigung, das Recht auf Löschung und das Recht auf Datenübertragbarkeit. Beim Recht auf Auskunft kann eine Person eine Bestätigung verlangen, ob ihre Daten verarbeitet werden, und erhält Zugang zu diesen Daten. Beim Recht auf Datenübertragbarkeit kann sie ihre bereitgestellten Daten in einem strukturierten, gängigen und maschinenlesbaren Format erhalten und einem anderen Verantwortlichen übermitteln. Dazu kommen noch das Widerspruchsrecht und das Recht auf Einschränkung der Verarbeitung.","quelle":"extra"},{"id":"n10f012","kapitel":10,"kapitel_name":"DSGVO","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Aufgaben hat ein Datenschutzbeauftragter (DSB) in einem Unternehmen?","loesung":"Der Datenschutzbeauftragte wird vom Unternehmen benannt und überwacht die Einhaltung der Datenschutzbestimmungen. Er berät das Unternehmen und die Mitarbeiter und führt Schulungen durch. Außerdem ist er Ansprechpartner für die Aufsichtsbehörden und für die betroffenen Personen.","quelle":"extra"},{"id":"n10f013","kapitel":10,"kapitel_name":"DSGVO","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was sind besondere Kategorien personenbezogener Daten und wie dürfen sie verarbeitet werden?","loesung":"Besondere Kategorien, auch sensible Daten genannt, lassen Rückschlüsse auf rassische und ethnische Herkunft, politische Meinungen, religiöse oder weltanschauliche Überzeugungen, Gewerkschaftszugehörigkeit, genetische und biometrische Daten, Gesundheitsdaten sowie das Sexualleben oder die sexuelle Orientierung zu. Ihre Verarbeitung ist grundsätzlich verboten. Zulässig ist sie nur, wenn sie rechtmäßig und nachvollziehbar für festgelegte, eindeutige und legitime Zwecke erfolgt, auf das notwendige Maß beschränkt bleibt, nur solange wie erforderlich dauert und angemessen vor unrechtmäßiger Verarbeitung oder Verlust geschützt ist.","quelle":"extra"},{"id":"n10f014","kapitel":10,"kapitel_name":"DSGVO","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Rollen der DSGVO ihrer Beschreibung zu:","begriffe":["Betroffene Person","Verantwortlicher","Auftragsverarbeiter","Datenschutzbeauftragter"],"beschreibungen":[{"key":"a","text":"Individuum, dessen personenbezogene Daten verarbeitet werden"},{"key":"b","text":"Entscheidet allein oder gemeinsam mit anderen über Zwecke und Mittel der Verarbeitung"},{"key":"c","text":"Verarbeitet personenbezogene Daten im Auftrag einer anderen Stelle"},{"key":"d","text":"Überwacht die Einhaltung der Datenschutzbestimmungen und schult die Mitarbeiter"}],"loesung_paare":{"Betroffene Person":"a","Verantwortlicher":"b","Auftragsverarbeiter":"c","Datenschutzbeauftragter":"d"},"loesung":"Betroffene Person = a; Verantwortlicher = b; Auftragsverarbeiter = c; Datenschutzbeauftragter = d","quelle":"extra"},{"id":"n10f015","kapitel":10,"kapitel_name":"DSGVO","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Betroffenenrechte ihrer Beschreibung zu:","begriffe":["Recht auf Berichtigung","Recht auf Löschung","Recht auf Datenübertragbarkeit","Widerspruchsrecht"],"beschreibungen":[{"key":"a","text":"Unrichtige Daten müssen unverzüglich korrigiert, unvollständige vervollständigt werden"},{"key":"b","text":"Daten müssen unverzüglich gelöscht werden, wenn sie nicht mehr notwendig sind oder unrechtmäßig verarbeitet wurden"},{"key":"c","text":"Daten müssen in einem strukturierten, gängigen und maschinenlesbaren Format herausgegeben werden"},{"key":"d","text":"Aus Gründen der besonderen Situation kann der Verarbeitung widersprochen werden"}],"loesung_paare":{"Recht auf Berichtigung":"a","Recht auf Löschung":"b","Recht auf Datenübertragbarkeit":"c","Widerspruchsrecht":"d"},"loesung":"Recht auf Berichtigung = a; Recht auf Löschung = b; Recht auf Datenübertragbarkeit = c; Widerspruchsrecht = d","quelle":"extra"},{"id":"n10f016","kapitel":10,"kapitel_name":"DSGVO","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Gesetze ihrem Regelungsbereich zu:","begriffe":["Urheberrecht","E-Commerce-Gesetz","Telekommunikationsgesetz"],"beschreibungen":[{"key":"a","text":"Schützt Werke der Literatur, Wissenschaft und Kunst vor unbefugter Nutzung"},{"key":"b","text":"Regelt Informationspflichten von Online-Händlern und elektronische Vertragsabschlüsse"},{"key":"c","text":"Regelt die Bereitstellung von Telekommunikationsdiensten und sichert die Netzneutralität"}],"loesung_paare":{"Urheberrecht":"a","E-Commerce-Gesetz":"b","Telekommunikationsgesetz":"c"},"loesung":"Urheberrecht = a; E-Commerce-Gesetz = b; Telekommunikationsgesetz = c","quelle":"extra"},{"id":"n11f001","kapitel":11,"kapitel_name":"Drucker","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Bei welcher Tintenstrahltechnik erhitzt ein Heizelement die Tinte, sodass sie aus der Düse gespritzt wird?","optionen":[{"key":"A","text":"Piezo-Technik"},{"key":"B","text":"Thermotransfer-Technik"},{"key":"C","text":"Bubble-Jet-Technik"},{"key":"D","text":"Thermodirekt-Technik"}],"loesung_key":"C","loesung":"Bubble-Jet-Technik","quelle":"extra"},{"id":"n11f002","kapitel":11,"kapitel_name":"Drucker","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Druckerart wird im Buch für Werkstätten und raue Umgebungen an erster Stelle genannt?","optionen":[{"key":"A","text":"Nadeldrucker"},{"key":"B","text":"Tintenstrahldrucker"},{"key":"C","text":"Thermodirektdrucker"},{"key":"D","text":"Farbsimulationsdrucker"}],"loesung_key":"A","loesung":"Nadeldrucker","quelle":"extra"},{"id":"n11f003","kapitel":11,"kapitel_name":"Drucker","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein Arbeitsstationdrucker ist typischerweise über ein USB-Kabel direkt mit einem einzelnen Computer verbunden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n11f004","kapitel":11,"kapitel_name":"Drucker","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ausdrucke eines Thermodirekt-Druckers sind dokumentenecht.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n11f005","kapitel":11,"kapitel_name":"Drucker","typ":"lueckentext","typ_label":"Lückentext","frage":"Mechanische Drucker, die das Papier beim Druckvorgang berühren, werden als __________-Drucker bezeichnet.","loesung":"Impact","alternativen":["Impact-Drucker"],"quelle":"extra"},{"id":"n11f006","kapitel":11,"kapitel_name":"Drucker","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein __________ ist ein Plottertyp, der Formen aus Materialien ausschneidet.","loesung":"Schneideplotter","quelle":"extra"},{"id":"n11f007","kapitel":11,"kapitel_name":"Drucker","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie kurz, wie ein Laserdrucker das Druckbild erzeugt.","loesung":"Im Laserdrucker wird eine Walze negativ geladen. Der Laser entfernt die Ladung an genau jenen Stellen, an denen später Farbe sitzen soll, und dort haftet der Toner an. Der Toner wird anschließend auf das Papier übertragen und dort fixiert.","quelle":"extra"},{"id":"n11f008","kapitel":11,"kapitel_name":"Drucker","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Merkmale muss ein Ausdruck erfüllen, damit er als dokumentenecht gilt?","loesung":"Der Ausdruck muss wasser- und lichtbeständig sein und darf nicht ohne sichtbare Spuren verändert werden können. Außerdem muss die Farbe schnell trocknen und chemisch beständig sein. Erfüllt ein Druckverfahren diese Punkte, gilt es als dokumentenecht.","quelle":"extra"},{"id":"n11f009","kapitel":11,"kapitel_name":"Drucker","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Plottertypen ihrer Arbeitsweise zu:","begriffe":["Stiftplotter","Rollenplotter","Flachbettplotter","Schneideplotter"],"beschreibungen":[{"key":"a","text":"Zeichnet mit Stiften auf Papier"},{"key":"b","text":"Erstellt großformatige Drucke auf Papierrollen"},{"key":"c","text":"Druckt auf festen Papierbögen"},{"key":"d","text":"Schneidet Formen aus Materialien aus"}],"loesung_paare":{"Stiftplotter":"a","Rollenplotter":"b","Flachbettplotter":"c","Schneideplotter":"d"},"loesung":"Stiftplotter = a; Rollenplotter = b; Flachbettplotter = c; Schneideplotter = d","quelle":"extra"},{"id":"n11f010","kapitel":11,"kapitel_name":"Drucker","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die folgenden Impact-Drucker ihrem Arbeitsprinzip zu:","begriffe":["Kettendrucker","Typenraddrucker","Kugelkopfdrucker"],"beschreibungen":[{"key":"a","text":"Großer und schneller Drucker für Massendruckaufgaben"},{"key":"b","text":"Verwendet ein Rad mit geprägten Zeichen für hochwertigen Textdruck"},{"key":"c","text":"Nutzt eine Kugel mit Zeichen für präzisen Textdruck"}],"loesung_paare":{"Kettendrucker":"a","Typenraddrucker":"b","Kugelkopfdrucker":"c"},"loesung":"Kettendrucker = a; Typenraddrucker = b; Kugelkopfdrucker = c","quelle":"extra"},{"id":"n12f001","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wofür steht die Abkürzung BNC bei Steckern für Kupferkabel?","optionen":[{"key":"A","text":"Bayonet Neill-Concelman"},{"key":"B","text":"Broadband Network Connector"},{"key":"C","text":"Balanced Node Coupling"},{"key":"D","text":"Basic Network Cable"}],"loesung_key":"A","loesung":"Bayonet Neill-Concelman","quelle":"extra"},{"id":"n12f002","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie verläuft der Brechungsindex im Kern einer Stufenindex-Faser?","optionen":[{"key":"A","text":"Er nimmt vom Zentrum zum Rand hin kontinuierlich ab."},{"key":"B","text":"Er steigt vom Zentrum zum Rand hin kontinuierlich an."},{"key":"C","text":"Er ist konstant und fällt an der Grenzfläche zum Mantel abrupt ab."},{"key":"D","text":"Er ändert sich periodisch entlang der Faser."}],"loesung_key":"C","loesung":"Er ist konstant und fällt an der Grenzfläche zum Mantel abrupt ab.","quelle":"extra"},{"id":"n12f003","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Nachteil von Koaxialkabeln wird im Buch genannt?","optionen":[{"key":"A","text":"Sehr geringe Bandbreite"},{"key":"B","text":"Hohe Empfindlichkeit gegenüber elektromagnetischen Störungen"},{"key":"C","text":"Geringe Widerstandsfähigkeit gegenüber Umwelteinflüssen"},{"key":"D","text":"Größerer Durchmesser und geringere Flexibilität"}],"loesung_key":"D","loesung":"Größerer Durchmesser und geringere Flexibilität","quelle":"extra"},{"id":"n12f004","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Glasfaserkabel sind zerbrechlicher als Kupferkabel und erfordern deshalb eine sorgfältigere Handhabung.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n12f005","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei einem SSTP-Kabel ist ausschließlich das gesamte Kabel mit einem Schirm umwickelt, die einzelnen verdrillten Paare bleiben ungeschirmt.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n12f006","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Der Mantel eines Lichtwellenleiters hat einen niedrigeren Brechungsindex als der Kern, damit das Licht im Kern gehalten wird.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n12f007","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Abkürzung RJ45 steht ausgeschrieben für __________ 45.","loesung":"Registered Jack","quelle":"extra"},{"id":"n12f008","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"lueckentext","typ_label":"Lückentext","frage":"Bei Multi-Mode-Fasern unterscheidet man zwischen der Stufenindex-Faser und der __________-Faser.","loesung":"Gradientenindex","alternativen":["Gradientenindexfaser","Gradientenindex-Faser"],"quelle":"extra"},{"id":"n12f009","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"lueckentext","typ_label":"Lückentext","frage":"Single-Mode-Fasern werden in Weitverkehrsnetzen über Distanzen von bis zu __________ km und mehr eingesetzt.","loesung":"100","alternativen":["100 km","hundert"],"quelle":"extra"},{"id":"n12f010","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Nachteile von Lichtwellenleiterkabeln.","loesung":"Lichtwellenleiterkabel verursachen höhere Kosten, weil für die Verlegung spezialisierte Werkzeuge und Kenntnisse nötig sind. Außerdem sind sie empfindlicher gegenüber physischer Beschädigung als Kupferkabel. Auch die Installation und die Wartung sind aufwendiger und erfordern spezielles Fachwissen.","quelle":"extra"},{"id":"n12f011","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worin unterscheiden sich Gradientenindex-Faser und Stufenindex-Faser im Aufbau und in der Eignung?","loesung":"Bei der Gradientenindex-Faser nimmt der Brechungsindex des Kerns vom Zentrum zum Rand hin ab, wodurch die Lichtstrahlen schrittweise abgelenkt werden und die Übertragung gleichmäßiger wird. Sie bietet deshalb eine bessere Leistung bei höheren Datenraten und längeren Distanzen. Bei der Stufenindex-Faser ist der Brechungsindex im Kern konstant und fällt am Mantel abrupt ab, das Licht wird direkt reflektiert. Sie ist einfacher und kostengünstiger herzustellen und eignet sich für kürzere Distanzen und niedrigere Datenraten.","quelle":"extra"},{"id":"n12f012","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Warum ist die Installation von Koaxialkabeln aufwendiger als jene von Twisted-Pair-Kabeln?","loesung":"Koaxialkabel sind dicker und steifer als Twisted-Pair-Kabel, deshalb lassen sie sich in engen Räumen nur schwer verlegen. Zusätzlich sind sie teurer in der Anschaffung. Für die Installation werden außerdem spezielle Werkzeuge und Techniken benötigt, was die Komplexität und die Gesamtkosten erhöht.","quelle":"extra"},{"id":"n12f013","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Fasertypen den passenden Merkmalen zu:","begriffe":["Single-Mode-Faser","Gradientenindex-Faser","Stufenindex-Faser"],"beschreibungen":[{"key":"a","text":"Sehr kleiner Kern, der nur einen Lichtmodus transportiert und dadurch die Dispersion reduziert"},{"key":"b","text":"Der Brechungsindex nimmt vom Zentrum zum Rand hin ab und ermöglicht eine gleichmäßigere Übertragung"},{"key":"c","text":"Konstanter Brechungsindex im Kern, einfach und kostengünstig in der Herstellung"}],"loesung_paare":{"Single-Mode-Faser":"a","Gradientenindex-Faser":"b","Stufenindex-Faser":"c"},"loesung":"Single-Mode-Faser = a; Gradientenindex-Faser = b; Stufenindex-Faser = c","quelle":"extra"},{"id":"n12f014","kapitel":12,"kapitel_name":"Netzwerkkabel","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie den Kabeltypen den jeweils im Buch genannten Nachteil beziehungsweise die Einschränkung zu:","begriffe":["Koaxialkabel","Lichtwellenleiterkabel","UTP-Kabel"],"beschreibungen":[{"key":"a","text":"Dicker und steifer, dadurch in engen Räumen schwer zu installieren"},{"key":"b","text":"Empfindlich gegenüber physischer Beschädigung und aufwendig in Installation und Wartung"},{"key":"c","text":"Ohne zusätzliche Abschirmung und daher vor allem für weniger störungsanfällige Umgebungen geeignet"}],"loesung_paare":{"Koaxialkabel":"a","Lichtwellenleiterkabel":"b","UTP-Kabel":"c"},"loesung":"Koaxialkabel = a; Lichtwellenleiterkabel = b; UTP-Kabel = c","quelle":"extra"},{"id":"n13f001","kapitel":13,"kapitel_name":"Domänencontroller","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Art von Domänencontroller wird laut Buch in Außenstellen oder besonders gesicherten Umgebungen eingesetzt?","optionen":[{"key":"A","text":"Hauptdomänencontroller (PDC)"},{"key":"B","text":"Zusätzlicher Domänencontroller (ADC)"},{"key":"C","text":"Nur-Lese-Domänencontroller (RODC)"},{"key":"D","text":"Lese-Schreib-Domänencontroller"}],"loesung_key":"C","loesung":"Nur-Lese-Domänencontroller (RODC)","quelle":"extra"},{"id":"n13f002","kapitel":13,"kapitel_name":"Domänencontroller","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches Werkzeug nennt das Buch zur Verwaltung und Sicherung lokaler Administratorpasswörter?","optionen":[{"key":"A","text":"Gruppenrichtlinienverwaltungskonsole (GPMC)"},{"key":"B","text":"Microsoft Local Administrator Password Solution (LAPS)"},{"key":"C","text":"AD-Benutzer und -Computer"},{"key":"D","text":"PowerShell"}],"loesung_key":"B","loesung":"Microsoft Local Administrator Password Solution (LAPS)","quelle":"extra"},{"id":"n13f003","kapitel":13,"kapitel_name":"Domänencontroller","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche zusätzliche Rolle übernimmt laut Buch der Hauptdomänencontroller (PDC)?","optionen":[{"key":"A","text":"Die Rolle des Zeitdienstes"},{"key":"B","text":"Die Vergabe von IP-Adressen über DHCP"},{"key":"C","text":"Die Auflösung von Namen über DNS"},{"key":"D","text":"Die Verwaltung von Softwarelizenzen"}],"loesung_key":"A","loesung":"Die Rolle des Zeitdienstes","quelle":"extra"},{"id":"n13f004","kapitel":13,"kapitel_name":"Domänencontroller","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein zusätzlicher Domänencontroller (ADC) repliziert die Datenbank und kann bei einem Ausfall des PDC dessen Aufgaben übernehmen.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n13f005","kapitel":13,"kapitel_name":"Domänencontroller","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Active Directory organisiert Benutzer, Computer und Gruppen in einer flachen Struktur ohne Hierarchie.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n13f006","kapitel":13,"kapitel_name":"Domänencontroller","typ":"lueckentext","typ_label":"Lückentext","frage":"Ein Domänencontroller ist ein Server, der die __________ (AD DS) bereitstellt.","loesung":"Active Directory Domain Services","alternativen":["AD DS","Active-Directory-Domänendienste"],"quelle":"extra"},{"id":"n13f007","kapitel":13,"kapitel_name":"Domänencontroller","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Gruppenrichtlinienverwaltungskonsole wird mit __________ abgekürzt.","loesung":"GPMC","quelle":"extra"},{"id":"n13f008","kapitel":13,"kapitel_name":"Domänencontroller","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie zwei Best Practices im Umgang mit lokalen Administratorkonten.","loesung":"Nach dem Prinzip der minimalen Berechtigung sollen lokale Administratorrechte nur so vielen Benutzern wie nötig gegeben werden, um die Sicherheit zu erhöhen. Außerdem müssen die Passwörter lokaler Administratorkonten komplex sein und regelmäßig aktualisiert werden. Zusätzlich empfiehlt sich der Einsatz von Verwaltungstools wie Microsoft LAPS zur Verwaltung und Sicherung dieser Passwörter.","quelle":"extra"},{"id":"n13f009","kapitel":13,"kapitel_name":"Domänencontroller","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Was ist Active Directory und mit welchen Werkzeugen wird es verwaltet? Nennen Sie zwei Werkzeuge.","loesung":"Active Directory ist ein Verzeichnisdienst von Microsoft, der Netzwerkelemente in einer hierarchischen Struktur organisiert. Dazu gehören Benutzer, Computer, Gruppen und andere Ressourcen. Zur Verwaltung dienen unter anderem AD-Benutzer und -Computer sowie die Gruppenrichtlinienverwaltungskonsole (GPMC). Auch PowerShell ist ein gängiges Werkzeug für die Verwaltung von Active Directory.","quelle":"extra"},{"id":"n13f010","kapitel":13,"kapitel_name":"Domänencontroller","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Sicherheitsprinzipien der Domänenverwaltung den passenden Maßnahmen zu:","begriffe":["Zugriffskontrolle","Überwachung","Sicherung"],"beschreibungen":[{"key":"a","text":"Einsatz von Zugriffskontrolllisten (ACLs) und Berechtigungen, damit nur autorisierte Benutzer zugreifen"},{"key":"b","text":"Regelmäßige Überprüfung von Sicherheitsprotokollen und Ereignisberichten"},{"key":"c","text":"Regelmäßige Backups der Active-Directory-Datenbank und anderer wichtiger Daten"}],"loesung_paare":{"Zugriffskontrolle":"a","Überwachung":"b","Sicherung":"c"},"loesung":"Zugriffskontrolle = a; Überwachung = b; Sicherung = c","quelle":"extra"},{"id":"n13f011","kapitel":13,"kapitel_name":"Domänencontroller","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Funktionen eines Domänencontrollers den passenden Beschreibungen zu:","begriffe":["Benutzerauthentifizierung","Verzeichnisdienste","Gruppenrichtlinien","Replikation"],"beschreibungen":[{"key":"a","text":"Überprüft die Anmeldedaten von Benutzern und Computern"},{"key":"b","text":"Verwaltet die Verzeichnisdatenbank mit allen Benutzern, Computern und Ressourcen der Domäne"},{"key":"c","text":"Setzt Sicherheits- und Verwaltungsrichtlinien für Benutzer und Computer durch"},{"key":"d","text":"Synchronisiert die Daten zwischen mehreren Domänencontrollern"}],"loesung_paare":{"Benutzerauthentifizierung":"a","Verzeichnisdienste":"b","Gruppenrichtlinien":"c","Replikation":"d"},"loesung":"Benutzerauthentifizierung = a; Verzeichnisdienste = b; Gruppenrichtlinien = c; Replikation = d","quelle":"extra"},{"id":"n14f001","kapitel":14,"kapitel_name":"Ergonomie","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welchem Abstand zum Benutzer soll der Monitor am ergonomischen Arbeitsplatz stehen?","optionen":[{"key":"A","text":"30 bis 45 cm"},{"key":"B","text":"45 bis 60 cm"},{"key":"C","text":"80 bis 100 cm"},{"key":"D","text":"60 bis 75 cm"}],"loesung_key":"D","loesung":"60 bis 75 cm","quelle":"extra"},{"id":"n14f002","kapitel":14,"kapitel_name":"Ergonomie","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Farbtemperatur sollten Leuchtmittel haben, damit die künstliche Beleuchtung Tageslicht simuliert?","optionen":[{"key":"A","text":"2000 bis 2700 Kelvin"},{"key":"B","text":"5000 bis 6500 Kelvin"},{"key":"C","text":"3000 bis 4000 Kelvin"},{"key":"D","text":"8000 bis 9500 Kelvin"}],"loesung_key":"B","loesung":"5000 bis 6500 Kelvin","quelle":"extra"},{"id":"n14f003","kapitel":14,"kapitel_name":"Ergonomie","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welchem Abstand werden kurze Pausen zur Entlastung von Augen und Muskulatur empfohlen?","optionen":[{"key":"A","text":"Alle 10 bis 15 Minuten"},{"key":"B","text":"Alle 15 bis 30 Minuten"},{"key":"C","text":"Alle 30 bis 60 Minuten"},{"key":"D","text":"Alle 2 bis 3 Stunden"}],"loesung_key":"C","loesung":"Alle 30 bis 60 Minuten","quelle":"extra"},{"id":"n14f004","kapitel":14,"kapitel_name":"Ergonomie","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein ergonomischer Bürostuhl soll mit mindestens fünf Rollen ausgestattet sein, um eine stabile Beweglichkeit zu gewährleisten.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n14f005","kapitel":14,"kapitel_name":"Ergonomie","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Bei einem elektrischen Unfall soll die betroffene Person mit einem metallenen Gegenstand von der Stromquelle getrennt werden.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n14f006","kapitel":14,"kapitel_name":"Ergonomie","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Werden zwei Monitore als Hauptmonitore eingesetzt, sollen sie gleich groß sein und dieselbe Auflösung haben.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n14f007","kapitel":14,"kapitel_name":"Ergonomie","typ":"lueckentext","typ_label":"Lückentext","frage":"Das Wort Ergonomie setzt sich aus den griechischen Wörtern „Ergon“ (Arbeit) und „__________“ (Gesetz) zusammen.","loesung":"Nomos","quelle":"extra"},{"id":"n14f008","kapitel":14,"kapitel_name":"Ergonomie","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Tastatur soll etwa __________ cm von der Tischkante entfernt liegen, damit die Handgelenke auf dem Tisch ruhen können.","loesung":"10 bis 15","alternativen":["10-15","10 - 15","zehn bis fünfzehn"],"quelle":"extra"},{"id":"n14f009","kapitel":14,"kapitel_name":"Ergonomie","typ":"lueckentext","typ_label":"Lückentext","frage":"Zum Trennen einer verunfallten Person von der Stromquelle ist immer ein Holzstab oder ein anderes __________ Material zu verwenden.","loesung":"nicht leitendes","alternativen":["nichtleitendes","nicht leitfähiges","isolierendes"],"quelle":"extra"},{"id":"n14f010","kapitel":14,"kapitel_name":"Ergonomie","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Welche Leistungen erbringt die AUVA in Österreich im Zusammenhang mit Arbeitsunfällen?","loesung":"Die AUVA ist die Unfallversicherung der Arbeitnehmerinnen und Arbeitnehmer und übernimmt die Kosten der medizinischen Versorgung nach einem Arbeitsunfall. Darüber hinaus unterstützt sie bei der Rehabilitation und bei der Wiedereingliederung in den Arbeitsprozess. Zusätzlich stellt sie Informationsmaterialien und Schulungen zur Unfallverhütung bereit und hilft Betrieben, Sicherheitsmaßnahmen umzusetzen.","quelle":"extra"},{"id":"n14f011","kapitel":14,"kapitel_name":"Ergonomie","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Wie soll ein dritter Monitor positioniert werden, der nur als Anzeigemonitor genutzt wird?","loesung":"Ein dritter Monitor, der nur Inhalte wie Dokumente, Kommunikations-Apps oder Überwachungsaufgaben anzeigt, gehört seitlich neben die Hauptmonitore. Er soll so stehen, dass man ihn ohne übermäßige Kopf- oder Augenbewegungen ablesen kann. Empfohlen wird eine Neigung von etwa 30 Grad zur Seite des Hauptmonitors.","quelle":"extra"},{"id":"n14f012","kapitel":14,"kapitel_name":"Ergonomie","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Warum ist eine regelmäßige Frischluftzufuhr am Büroarbeitsplatz wichtig und wie kann sie sichergestellt werden?","loesung":"Frische Luft hält die Sauerstoffkonzentration im Raum aufrecht und beugt dadurch Müdigkeit vor. Das fördert Konzentration und Wohlbefinden. Sicherstellen lässt sich das durch regelmäßiges Lüften oder durch den Einsatz von Luftreinigern.","quelle":"extra"},{"id":"n14f013","kapitel":14,"kapitel_name":"Ergonomie","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die ergonomischen Richtwerte den passenden Angaben zu:","begriffe":["Kniewinkel beim Sitzen","Neigung des Monitors nach hinten","Seitliche Neigung eines zusätzlichen Anzeigemonitors","Abstand zwischen Auge und Monitor"],"beschreibungen":[{"key":"a","text":"Etwa 90 Grad"},{"key":"b","text":"Etwa 10 Grad"},{"key":"c","text":"Etwa 30 Grad"},{"key":"d","text":"60 bis 75 cm"}],"loesung_paare":{"Kniewinkel beim Sitzen":"a","Neigung des Monitors nach hinten":"b","Seitliche Neigung eines zusätzlichen Anzeigemonitors":"c","Abstand zwischen Auge und Monitor":"d"},"loesung":"Kniewinkel beim Sitzen = a; Neigung des Monitors nach hinten = b; Seitliche Neigung eines zusätzlichen Anzeigemonitors = c; Abstand zwischen Auge und Monitor = d","quelle":"extra"},{"id":"n14f014","kapitel":14,"kapitel_name":"Ergonomie","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Ausstattungselemente ihrer ergonomischen Funktion zu:","begriffe":["Handballenauflage","Sonnenblende","Höhenverstellbarer Tisch","Rückenlehne"],"beschreibungen":[{"key":"a","text":"Hält die Handgelenke beim Tippen in einer neutralen Position"},{"key":"b","text":"Verhindert Blendungen durch einfallendes Tageslicht"},{"key":"c","text":"Ermöglicht den Wechsel zwischen Arbeiten im Sitzen und im Stehen"},{"key":"d","text":"Stützt die Lendenwirbelsäule in ihrer natürlichen Krümmung"}],"loesung_paare":{"Handballenauflage":"a","Sonnenblende":"b","Höhenverstellbarer Tisch":"c","Rückenlehne":"d"},"loesung":"Handballenauflage = a; Sonnenblende = b; Höhenverstellbarer Tisch = c; Rückenlehne = d","quelle":"extra"},{"id":"n15f001","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche Aufgabenart des überwachten Lernens sagt einen Zahlenwert wie einen Preis oder eine Temperatur voraus?","optionen":[{"key":"A","text":"Regression"},{"key":"B","text":"Klassifikation"},{"key":"C","text":"Clustering"},{"key":"D","text":"Dimensionsreduktion"}],"loesung_key":"A","loesung":"Regression","quelle":"extra"},{"id":"n15f002","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welches KI-Tool wird im Buch wegen seiner sehr großen Kontextfenster für lange Dokumente genannt?","optionen":[{"key":"A","text":"Claude"},{"key":"B","text":"DeepL Write"},{"key":"C","text":"Midjourney"},{"key":"D","text":"GitHub Copilot"}],"loesung_key":"A","loesung":"Claude","quelle":"extra"},{"id":"n15f003","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Wie heißt der Mechanismus, mit dem Transformer-Modelle ermitteln, welche Teile eines Textes für die Bedeutung am wichtigsten sind?","optionen":[{"key":"A","text":"Epoche"},{"key":"B","text":"Attention"},{"key":"C","text":"Dimensionsreduktion"},{"key":"D","text":"Merkmalsextraktion"}],"loesung_key":"B","loesung":"Attention","quelle":"extra"},{"id":"n15f004","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welchem Bereich eines neuronalen Netzes findet die eigentliche Mustererkennung statt?","optionen":[{"key":"A","text":"In der Eingabeschicht"},{"key":"B","text":"In den versteckten Schichten"},{"key":"C","text":"In der Ausgabeschicht"},{"key":"D","text":"In der Parameterschicht"}],"loesung_key":"B","loesung":"In den versteckten Schichten","quelle":"extra"},{"id":"n15f005","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welche KI-Systeme sind nach dem EU AI Act in der EU vollständig verboten?","optionen":[{"key":"A","text":"Systeme mit geringem Risiko"},{"key":"B","text":"Hochrisiko-Systeme mit Dokumentationspflicht"},{"key":"C","text":"Systeme mit inakzeptablem Risiko wie Social Scoring"},{"key":"D","text":"Multimodale Systeme"}],"loesung_key":"C","loesung":"Systeme mit inakzeptablem Risiko wie Social Scoring","quelle":"extra"},{"id":"n15f006","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"Welcher Schritt der KI-Entwicklung prüft bereits während des Trainings, ob das Modell sinnvoll lernt und nicht übertrainiert?","optionen":[{"key":"A","text":"Datensammlung"},{"key":"B","text":"Testen"},{"key":"C","text":"Training"},{"key":"D","text":"Validierung"}],"loesung_key":"D","loesung":"Validierung","quelle":"extra"},{"id":"n15f007","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"multiple_choice","typ_label":"Multiple Choice","frage":"In welcher Einheit wird das Erinnerungsvermögen einer KI innerhalb eines Chats gemessen?","optionen":[{"key":"A","text":"In Epochen"},{"key":"B","text":"In Parametern"},{"key":"C","text":"In Schichten"},{"key":"D","text":"In Tokens"}],"loesung_key":"D","loesung":"In Tokens","quelle":"extra"},{"id":"n15f008","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Deep Learning ist eine Unterkategorie des Machine Learning.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n15f009","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Beim unüberwachten Lernen erhält das Modell zu jedem Eingabedatensatz den passenden Zielwert.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n15f010","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Beim bestärkenden Lernen passt der Agent sein Verhalten aufgrund von Belohnungen oder Strafen an.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n15f011","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Die Verantwortung für die Nutzung KI-generierter Inhalte liegt beim KI-System und nicht beim Anwender.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n15f012","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Ein neuronales Netz kann Merkmale selbstständig lernen, die früher ein Entwickler von Hand definieren musste.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"A","loesung":"Wahr","quelle":"extra"},{"id":"n15f013","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"Für möglichst klare Ergebnisse empfiehlt das Buch, lieber drei große Chats zu führen als dreißig kleine.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n15f014","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"wahr_falsch","typ_label":"Wahr/Falsch","frage":"GitHub Copilot ist ein Beispiel für eine starke (General) KI.","optionen":[{"key":"A","text":"Wahr"},{"key":"B","text":"Falsch"}],"loesung_key":"B","loesung":"Falsch","quelle":"extra"},{"id":"n15f015","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Wenn eine KI falsche Informationen liefert, die aber plausibel klingen, spricht man von __________.","loesung":"Halluzinationen","alternativen":["Halluzination"],"quelle":"extra"},{"id":"n15f016","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Falsche oder einseitige Trainingsdaten führen zu Verzerrungen, die als __________ bezeichnet werden.","loesung":"Bias","alternativen":["Verzerrung","Verzerrungen"],"quelle":"extra"},{"id":"n15f017","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Die vielen Durchläufe, die ein Modell während des Trainings über den Datensatz macht, nennt man __________.","loesung":"Epochen","alternativen":["Epoche"],"quelle":"extra"},{"id":"n15f018","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Werden beim unüberwachten Lernen ähnliche Daten zu Gruppen zusammengefasst, spricht man von __________.","loesung":"Clustering","alternativen":["Cluster-Analyse","Clusteranalyse"],"quelle":"extra"},{"id":"n15f019","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Die internen Werte eines Modells, die beim Training optimiert werden, heißen __________.","loesung":"Parameter","quelle":"extra"},{"id":"n15f020","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"lueckentext","typ_label":"Lückentext","frage":"Die Menge an Informationen, die einer KI in einer Unterhaltung zur Verfügung steht, bezeichnet man als __________.","loesung":"Kontext","alternativen":["Kontextfenster","Kontext-Fenster"],"quelle":"extra"},{"id":"n15f021","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Erklären Sie den Unterschied zwischen schwacher und starker KI.","loesung":"Eine schwache oder Narrow KI ist auf eine einzige, spezifische Aufgabe spezialisiert und kann nur das lösen, wofür sie trainiert wurde. Beispiele dafür sind Chatbots, Bilderkennung, Spamfilter oder GitHub Copilot. Eine starke oder General KI könnte dagegen wie ein Mensch denken, eigenständig Probleme lösen und ohne Grenzen dazulernen. Sie existiert bisher nur theoretisch.","quelle":"extra"},{"id":"n15f022","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Beschreiben Sie den Aufbau eines typischen neuronalen Netzes.","loesung":"Ein neuronales Netz besteht aus drei Hauptbereichen. Die Eingabeschicht nimmt die Rohdaten entgegen, etwa Pixelwerte eines Bildes oder numerische Werte. Danach folgen eine oder mehrere versteckte Schichten, in denen die eigentliche Mustererkennung stattfindet. Die Ausgabeschicht gibt schließlich das Ergebnis aus, zum Beispiel eine Klassifikation oder einen vorhergesagten Zahlenwert.","quelle":"extra"},{"id":"n15f023","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie drei Risiken beim Einsatz von KI und erklären Sie eines davon kurz.","loesung":"Risiken sind zum Beispiel Halluzinationen, Bias in den Trainingsdaten, Datenschutzrisiken, Abhängigkeit und urheberrechtliche Probleme. Bei Halluzinationen liefert die KI Informationen, die falsch sind, aber plausibel klingen. Deshalb muss jede Ausgabe überprüft werden, denn die KI liefert nur Vorschläge und die Verantwortung bleibt beim Menschen.","quelle":"extra"},{"id":"n15f024","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Worauf muss man beim Einsatz von KI-Tools mit Blick auf die DSGVO achten?","loesung":"Personenbezogene Daten dürfen nicht ohne Erlaubnis in KI-Tools eingegeben werden. Es gilt der Grundsatz der Datenminimierung, also nur so viele Daten wie nötig. Außerdem gilt die Zweckbindung: Die Daten dürfen nur für den Zweck verwendet werden, für den sie erhoben wurden.","quelle":"extra"},{"id":"n15f025","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Nennen Sie drei Einsatzmöglichkeiten von KI in der Softwareentwicklung.","loesung":"KI kann Code vervollständigen, etwa mit GitHub Copilot, und Vorschläge für Verbesserungen machen. Sie kann Dokumentation automatisiert erstellen. Außerdem unterstützt sie bei der Fehlersuche und beim Debugging.","quelle":"extra"},{"id":"n15f026","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"kurzantwort","typ_label":"Kurzantwort","frage":"Warum empfiehlt das Buch, in einem Chat bei einem Thema zu bleiben?","loesung":"Das Erinnerungsvermögen eines Chats ist begrenzt und wird in Tokens gemessen. Werden zu viele verschiedene Themen im selben Chat behandelt, läuft dieser Speicher über und die KI verwirft die ältesten oder am seltensten genutzten Informationen. Sie kann dann nicht mehr korrekt auf Vergangenes im selben Chat verweisen, die Antworten werden ungenauer und falsche Angaben werden wahrscheinlicher. Deshalb sind viele kleine, thematisch saubere Chats besser als wenige große.","quelle":"extra"},{"id":"n15f027","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Aufgabenarten des Machine Learnings ihrer Beschreibung zu:","begriffe":["Klassifikation","Regression","Clustering","Dimensionsreduktion"],"beschreibungen":[{"key":"a","text":"Sagt eine Kategorie voraus, zum Beispiel „Hund“ oder „Katze“"},{"key":"b","text":"Sagt einen Zahlenwert voraus, zum Beispiel Preis oder Temperatur"},{"key":"c","text":"Gruppiert ähnliche Daten, etwa Kundentypen"},{"key":"d","text":"Vereinfacht Daten und macht sie übersichtlicher"}],"loesung_paare":{"Klassifikation":"a","Regression":"b","Clustering":"c","Dimensionsreduktion":"d"},"loesung":"Klassifikation = a; Regression = b; Clustering = c; Dimensionsreduktion = d","quelle":"extra"},{"id":"n15f028","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Schichten eines neuronalen Netzes ihrer Aufgabe zu:","begriffe":["Eingabeschicht","Versteckte Schichten","Ausgabeschicht"],"beschreibungen":[{"key":"a","text":"Nimmt als erste Schicht die Rohdaten entgegen"},{"key":"b","text":"Hier findet die eigentliche Mustererkennung statt"},{"key":"c","text":"Gibt das Ergebnis aus, etwa eine Klassifikation oder eine Zahlvorhersage"}],"loesung_paare":{"Eingabeschicht":"a","Versteckte Schichten":"b","Ausgabeschicht":"c"},"loesung":"Eingabeschicht = a; Versteckte Schichten = b; Ausgabeschicht = c","quelle":"extra"},{"id":"n15f029","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die KI-Tools ihrem Haupteinsatzgebiet zu:","begriffe":["GitHub Copilot","Midjourney","DeepL Write","Gemini"],"beschreibungen":[{"key":"a","text":"Unterstützung beim Programmieren direkt in der Entwicklungsumgebung"},{"key":"b","text":"Generierung von Bildern"},{"key":"c","text":"Korrigieren und Verbessern von Texten"},{"key":"d","text":"Multimodale Verarbeitung von Text, Bild und Video"}],"loesung_paare":{"GitHub Copilot":"a","Midjourney":"b","DeepL Write":"c","Gemini":"d"},"loesung":"GitHub Copilot = a; Midjourney = b; DeepL Write = c; Gemini = d","quelle":"extra"},{"id":"n15f030","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Schritte der KI-Entwicklung ihrer Beschreibung zu:","begriffe":["Datensammlung","Training","Validierung","Testen"],"beschreibungen":[{"key":"a","text":"Zusammentragen von Texten, Bildern, Audio- oder Messdaten"},{"key":"b","text":"Das Modell passt seine Parameter in mehreren Epochen an die Daten an"},{"key":"c","text":"Laufende Kontrolle während des Trainings auf Overfitting"},{"key":"d","text":"Prüfung mit neuen, unbekannten Daten auf Generalisierung"}],"loesung_paare":{"Datensammlung":"a","Training":"b","Validierung":"c","Testen":"d"},"loesung":"Datensammlung = a; Training = b; Validierung = c; Testen = d","quelle":"extra"},{"id":"n15f031","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Risiken der KI-Nutzung ihrer Beschreibung zu:","begriffe":["Halluzinationen","Bias","Datenschutzrisiken","Abhängigkeit"],"beschreibungen":[{"key":"a","text":"Die KI liefert falsche Informationen, die plausibel klingen"},{"key":"b","text":"Einseitige Trainingsdaten führen zu verzerrten Ergebnissen"},{"key":"c","text":"Sensible Daten gelangen unkontrolliert in KI-Tools"},{"key":"d","text":"Übermäßige Nutzung reduziert das eigene Verständnis"}],"loesung_paare":{"Halluzinationen":"a","Bias":"b","Datenschutzrisiken":"c","Abhängigkeit":"d"},"loesung":"Halluzinationen = a; Bias = b; Datenschutzrisiken = c; Abhängigkeit = d","quelle":"extra"},{"id":"n15f032","kapitel":15,"kapitel_name":"Künstliche Intelligenz","typ":"zuordnung","typ_label":"Zuordnungsfrage","frage":"Ordnen Sie die Vorteile der Künstlichen Intelligenz ihrer Beschreibung zu:","begriffe":["Effizienzsteigerung","Fehlerreduktion","Lernunterstützung","Automatisierung"],"beschreibungen":[{"key":"a","text":"Schnelleres Arbeiten und weniger Routineaufwand"},{"key":"b","text":"Erkennen von Mustern, die Menschen übersehen könnten"},{"key":"c","text":"Erklären von Code, Konzepten und Zusammenhängen"},{"key":"d","text":"Wiederholbare Aufgaben laufen vollständig selbsttätig ab"}],"loesung_paare":{"Effizienzsteigerung":"a","Fehlerreduktion":"b","Lernunterstützung":"c","Automatisierung":"d"},"loesung":"Effizienzsteigerung = a; Fehlerreduktion = b; Lernunterstützung = c; Automatisierung = d","quelle":"extra"}];

